window.CFA_DEEP_EQUITY=[{"module_id":"CFA26-05-01","module_title":"Market Organization and Structure","subject":"Equity Investments","version":"3.6","qa_status":"SOURCE_GROUNDED_DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT","language":"Vietnamese explanations, English stems/options","source_policy":"Original paraphrased study notes and questions based on CFAI 2026 Vol 5 LM1","los":[{"id":"CFA26-05-01-LOS01","letter":"1.a","title_en":"Functions of the Financial System","outcome_en":"explain the main functions of the financial system","overview_vi":"Bám mục tiêu 1.a theo CFAI 2026. Nội dung được biên soạn lại tiếng Việt với thuật ngữ English; các illustrations và câu hỏi là tình huống gốc, cần kiểm định học thuật bổ sung trước khi coi là bản cuối.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5, LM1","pages":"13–21 (physical PDF; chapter pp13–90)"}],"sections":[{"heading":"Capital allocation and financing","body":"Hệ thống tài chính chuyển nguồn vốn từ người có tiền nhàn rỗi sang doanh nghiệp, chính phủ và cá nhân có dự án đầu tư; quá trình này hình thành giá vốn, hỗ trợ tích lũy tư bản và tăng trưởng.","trap":"Không nhầm primary-market financing với giao dịch lại giữa nhà đầu tư trên secondary market."},{"heading":"Saving, borrowing and timing","body":"Saving chuyển sức mua hiện tại thành khả năng tiêu dùng tương lai; borrowing cho phép chi tiêu/đầu tư trước rồi hoàn trả sau. Một khoản nợ là asset của lender và liability của borrower.","trap":"Lãi suất phản ánh thời gian, rủi ro và điều kiện thị trường; không chỉ là phí dịch vụ ngân hàng."},{"heading":"Risk transfer and hedging","body":"Bảo hiểm và phái sinh chuyển hoặc phân bổ lại rủi ro giữa những người có khả năng/chủ đích chịu rủi ro khác nhau; hedging giảm phơi nhiễm nhưng không tự tạo lợi nhuận chắc chắn.","trap":"Cân bằng rủi ro không có nghĩa xóa toàn bộ rủi ro hệ thống."},{"heading":"Liquidity, settlement and information","body":"Thị trường giúp tìm đối tác giao dịch, khám phá giá, thanh toán và lưu ký; liquidity giảm chi phí chuyển tài sản thành tiền. Thông tin giá hỗ trợ phân bổ vốn nhưng có thể bị nhiễu.","trap":"Thanh khoản không đồng nghĩa không có price risk."},{"heading":"Agency costs and information asymmetry","body":"Thông tin bất cân xứng có thể gây adverse selection; khác biệt lợi ích giữa principal và agent có thể gây moral hazard. Contracts, disclosure, monitoring và quy định là cơ chế hạn chế vấn đề.","trap":"Không giả định giao dịch tài chính luôn có đầy đủ thông tin."}],"formulas":[{"name":"Net funds flow","expr":"Surplus units → financial system → deficit units","meaning":"Capital channeling; không hàm ý mọi nguồn vốn đi qua securities markets.","conditions":"Khung phân tích, không phải phương trình tiền tệ."}],"examples":[{"question_en":"A household deposits spare cash at a bank, which lends to a manufacturing firm. Explain the allocation and timing functions.","steps_vi":["Household delays consumption and supplies funding; firm can invest before accumulating all internal cash.","Bank intermediation matches savers and borrowers, but the bank still faces credit/liquidity risk."],"answer":"Funding moves from savings toward productive borrowing.","check":"This is financing intermediation, not automatically an equity primary issue."}],"questions":[{"stem_en":"An investor buys newly issued corporate bonds. Which financial-system function is most directly served?","options":["Providing new financing to an issuer","Trading existing claims between investors","Eliminating all borrower default risk"],"correct":0,"why_vi":"Doanh nghiệp nhận tiền từ phát hành sơ cấp, vì vậy được cấp vốn mới.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"A pension fund uses a derivative to reduce its foreign-currency exposure. This mainly illustrates:","options":["Primary market capital formation","Risk transfer","Guaranteed arbitrage profits"],"correct":1,"why_vi":"Phái sinh phân bổ lại phơi nhiễm tỷ giá; không bảo đảm lợi nhuận.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Which characteristic makes selling an asset quickly with limited price concession easier?","options":["Liquidity","Leverage","Maturity transformation"],"correct":0,"why_vi":"Liquidity là khả năng giao dịch nhanh, chi phí và price impact thấp.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."}],"cards":[{"front_en":"Capital allocation and financing","back_vi":"Hệ thống tài chính chuyển nguồn vốn từ người có tiền nhàn rỗi sang doanh nghiệp, chính phủ và cá nhân có dự án đầu tư; quá trình này hình thành giá vốn, hỗ trợ tích lũy tư bản và tăng trưởng. Exam trap: Không nhầm primary-market financing với giao dịch lại giữa nhà đầu tư trên secondary market."},{"front_en":"Saving, borrowing and timing","back_vi":"Saving chuyển sức mua hiện tại thành khả năng tiêu dùng tương lai; borrowing cho phép chi tiêu/đầu tư trước rồi hoàn trả sau. Một khoản nợ là asset của lender và liability của borrower. Exam trap: Lãi suất phản ánh thời gian, rủi ro và điều kiện thị trường; không chỉ là phí dịch vụ ngân hàng."},{"front_en":"Risk transfer and hedging","back_vi":"Bảo hiểm và phái sinh chuyển hoặc phân bổ lại rủi ro giữa những người có khả năng/chủ đích chịu rủi ro khác nhau; hedging giảm phơi nhiễm nhưng không tự tạo lợi nhuận chắc chắn. Exam trap: Cân bằng rủi ro không có nghĩa xóa toàn bộ rủi ro hệ thống."},{"front_en":"Liquidity, settlement and information","back_vi":"Thị trường giúp tìm đối tác giao dịch, khám phá giá, thanh toán và lưu ký; liquidity giảm chi phí chuyển tài sản thành tiền. Thông tin giá hỗ trợ phân bổ vốn nhưng có thể bị nhiễu. Exam trap: Thanh khoản không đồng nghĩa không có price risk."},{"front_en":"Agency costs and information asymmetry","back_vi":"Thông tin bất cân xứng có thể gây adverse selection; khác biệt lợi ích giữa principal và agent có thể gây moral hazard. Contracts, disclosure, monitoring và quy định là cơ chế hạn chế vấn đề. Exam trap: Không giả định giao dịch tài chính luôn có đầy đủ thông tin."}]},{"id":"CFA26-05-01-LOS02","letter":"1.b","title_en":"Asset and Market Classifications","outcome_en":"describe classifications of assets and markets","overview_vi":"Bám mục tiêu 1.b theo CFAI 2026. Nội dung được biên soạn lại tiếng Việt với thuật ngữ English; các illustrations và câu hỏi là tình huống gốc, cần kiểm định học thuật bổ sung trước khi coi là bản cuối.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5, LM1","pages":"16–26 (physical PDF; chapter pp13–90)"}],"sections":[{"heading":"Real assets and financial assets","body":"Real assets (bất động sản, nhà xưởng, hàng hóa) tạo dòng dịch vụ/sản xuất; financial assets là claims đối với cash flows/ownership của thực thể khác. Financial claims cuối cùng phụ thuộc khả năng tạo giá trị của nền kinh tế thực.","trap":"Cổ phiếu của công ty bất động sản là financial asset, còn tòa nhà là real asset."},{"heading":"Debt and equity; traditional and alternative","body":"Debt là nghĩa vụ thanh toán theo hợp đồng với seniority; equity là residual claim và thường có quyền biểu quyết. Alternative investments bao gồm nhiều loại cấu trúc và tài sản với thanh khoản/hạn chế khác nhau.","trap":"Không coi mọi alternative asset luôn thanh khoản kém hoặc có return cao."},{"heading":"Primary and secondary markets","body":"Primary market: issuer tạo/bán claim mới; secondary market: các nhà đầu tư trao đổi claim đã phát hành. Secondary-market liquidity giúp người mua sẵn sàng góp vốn khi phát hành.","trap":"Giá cổ phiếu tăng trên sàn không tự động cấp vốn mới cho issuer."},{"heading":"Spot, forward, money and capital markets","body":"Spot giao nhận gần như ngay; forwards/futures cho giao nhận/thanh toán tương lai. Money market thường là công cụ nợ ngắn hạn; capital market bao gồm các khoản tài trợ dài hạn như stocks/bonds.","trap":"Thời hạn và loại claim quan trọng hơn tên sàn."},{"heading":"Public/private, regulated/unregulated venues","body":"Public markets chào bán và giao dịch rộng rãi hơn; private placements hạn chế nhà đầu tư/khả năng chuyển nhượng. Có thị trường tập trung và OTC; địa điểm giao dịch không tự quyết định mức độ an toàn.","trap":"OTC không đồng nghĩa bất hợp pháp."}],"formulas":[{"name":"Claims vs assets","expr":"Financial claim = contractual/ownership claim on an issuer; real asset = productive resource","meaning":"Phân biệt legal claim và physical resource.","conditions":"Không suy từ công ty thuộc ngành nào để phân loại stock thành real asset."},{"name":"New funding","expr":"Primary issue proceeds → issuer; secondary trade proceeds → selling investor","meaning":"Dùng xác định ai nhận cash.","conditions":"Không tính primary shares do selling shareholder bán là vốn mới của issuer."}],"examples":[{"question_en":"A company sells $4 million of new shares and next week one shareholder sells $10,000 of shares on the exchange. Identify issuer receipts.","steps_vi":["Issuer receives $4 million from issuance (before fees).","The following secondary trade transfers $10,000 between investors, not into issuer treasury."],"answer":"$4 million of new issuer funding","check":"The listed share itself is a financial claim."}],"questions":[{"stem_en":"A share of a listed real estate developer is best classified as:","options":["A real asset","A financial asset","A commodity"],"correct":1,"why_vi":"Cổ phần là claim tài chính đối với doanh nghiệp sở hữu real assets.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Which transaction creates new funding for the issuer?","options":["Investor A sells an outstanding bond to Investor B","An issuer sells newly created bonds to investors","An investor buys stock on an exchange"],"correct":1,"why_vi":"Chỉ phát hành claim mới đưa tiền cho issuer trong giao dịch được nêu.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"A 90-day Treasury bill is generally traded in the:","options":["Money market","Long-term equity market","Physical commodity market"],"correct":0,"why_vi":"Treasury bill ngắn hạn thuộc money market.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."}],"cards":[{"front_en":"Real assets and financial assets","back_vi":"Real assets (bất động sản, nhà xưởng, hàng hóa) tạo dòng dịch vụ/sản xuất; financial assets là claims đối với cash flows/ownership của thực thể khác. Financial claims cuối cùng phụ thuộc khả năng tạo giá trị của nền kinh tế thực. Exam trap: Cổ phiếu của công ty bất động sản là financial asset, còn tòa nhà là real asset."},{"front_en":"Debt and equity; traditional and alternative","back_vi":"Debt là nghĩa vụ thanh toán theo hợp đồng với seniority; equity là residual claim và thường có quyền biểu quyết. Alternative investments bao gồm nhiều loại cấu trúc và tài sản với thanh khoản/hạn chế khác nhau. Exam trap: Không coi mọi alternative asset luôn thanh khoản kém hoặc có return cao."},{"front_en":"Primary and secondary markets","back_vi":"Primary market: issuer tạo/bán claim mới; secondary market: các nhà đầu tư trao đổi claim đã phát hành. Secondary-market liquidity giúp người mua sẵn sàng góp vốn khi phát hành. Exam trap: Giá cổ phiếu tăng trên sàn không tự động cấp vốn mới cho issuer."},{"front_en":"Spot, forward, money and capital markets","back_vi":"Spot giao nhận gần như ngay; forwards/futures cho giao nhận/thanh toán tương lai. Money market thường là công cụ nợ ngắn hạn; capital market bao gồm các khoản tài trợ dài hạn như stocks/bonds. Exam trap: Thời hạn và loại claim quan trọng hơn tên sàn."},{"front_en":"Public/private, regulated/unregulated venues","back_vi":"Public markets chào bán và giao dịch rộng rãi hơn; private placements hạn chế nhà đầu tư/khả năng chuyển nhượng. Có thị trường tập trung và OTC; địa điểm giao dịch không tự quyết định mức độ an toàn. Exam trap: OTC không đồng nghĩa bất hợp pháp."}]},{"id":"CFA26-05-01-LOS03","letter":"1.c","title_en":"Major Tradable Instruments","outcome_en":"describe the major types of securities, currencies, contracts, commodities, and real assets that trade in organized markets, including their distinguishing characteristics and major subtypes","overview_vi":"Bám mục tiêu 1.c theo CFAI 2026. Nội dung được biên soạn lại tiếng Việt với thuật ngữ English; các illustrations và câu hỏi là tình huống gốc, cần kiểm định học thuật bổ sung trước khi coi là bản cuối.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5, LM1","pages":"21–38 (physical PDF; chapter pp13–90)"}],"sections":[{"heading":"Fixed income instruments","body":"Treasury bills, notes/bonds, commercial paper, certificates of deposit và corporate bonds tạo quyền nhận lãi/gốc theo điều khoản. Zero-coupon securities không trả coupon định kỳ nhưng vẫn có yield. Credit risk phụ thuộc issuer và seniority.","trap":"Bond không mặc nhiên có coupon cố định; floating-rate và zero-coupon cũng là debt."},{"heading":"Equity and pooled vehicles","body":"Common shares là residual ownership; preferred shares thường ưu tiên cổ tức/thu hồi hơn common nhưng quyền biểu quyết hạn chế. Mutual funds, ETFs và các pooled vehicles cho phép đầu tư gián tiếp vào danh mục.","trap":"ETF trade intraday còn open-end mutual fund thông thường giao dịch theo NAV cuối ngày."},{"heading":"Currencies and commodities","body":"Currency markets trao đổi đơn vị tiền tệ; commodity markets gồm energy, industrial metals, precious metals và agricultural goods. Giá spot và futures có thể khác vì financing/storage/convenience yield.","trap":"Không coi commodity return như coupon của trái phiếu."},{"heading":"Derivatives","body":"Forward là thỏa thuận bilateral tùy chỉnh; futures chuẩn hóa thường được margin/mark to market; swaps trao đổi dòng tiền; options trao quyền (không bắt buộc) thực hiện cho holder.","trap":"Option holder không có nghĩa vụ exercise, nhưng writer có nghĩa vụ nếu được thực hiện."},{"heading":"Real assets and property","body":"Land, buildings, infrastructure và physical resources có chi phí lưu giữ, chi phí giao dịch và tính đặc thù cao; đầu tư gián tiếp qua securities khác với sở hữu trực tiếp.","trap":"REIT share là security, khác với tòa nhà mà REIT nắm giữ."}],"formulas":[{"name":"Equity claim priority","expr":"Senior debt claims → subordinated debt → preferred equity → common equity (stylized)","meaning":"Illustrates typical liquidation priorities.","conditions":"Actual order depends on contractual/legal structure."},{"name":"Derivative rights","expr":"Option buyer has a right, not an exercise obligation","meaning":"Option buyer pays premium; writer may have obligation.","conditions":"Distinguish forward/future bilateral obligations."}],"examples":[{"question_en":"An investor buys a call option with a $25 strike while the stock later trades at $21. Does the holder have to exercise?","steps_vi":["A call gives the holder an exercise right, not obligation.","Since stock price is below strike, exercising would be economically inferior to buying stock in the market (ignoring edge cases)."],"answer":"No; the call holder can let the option expire.","check":"Premium is still lost if option expires worthless."}],"questions":[{"stem_en":"Which instrument gives its holder a right, but not an obligation, to transact at a specified price?","options":["Forward contract","Option contract","Ordinary bond"],"correct":1,"why_vi":"Option có asymmetric payoff và quyền exercise của holder.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Which instrument usually represents a residual claim after creditors?","options":["Common stock","Senior secured bond","Treasury bill"],"correct":0,"why_vi":"Common equity thường đứng sau debt trong liquidation waterfall.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Which vehicle is generally designed to trade on an exchange during the trading session?","options":["Conventional open-end mutual fund","Exchange-traded fund","Private real estate title"],"correct":1,"why_vi":"ETF shares có thể được giao dịch intraday trên exchange.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."}],"cards":[{"front_en":"Fixed income instruments","back_vi":"Treasury bills, notes/bonds, commercial paper, certificates of deposit và corporate bonds tạo quyền nhận lãi/gốc theo điều khoản. Zero-coupon securities không trả coupon định kỳ nhưng vẫn có yield. Credit risk phụ thuộc issuer và seniority. Exam trap: Bond không mặc nhiên có coupon cố định; floating-rate và zero-coupon cũng là debt."},{"front_en":"Equity and pooled vehicles","back_vi":"Common shares là residual ownership; preferred shares thường ưu tiên cổ tức/thu hồi hơn common nhưng quyền biểu quyết hạn chế. Mutual funds, ETFs và các pooled vehicles cho phép đầu tư gián tiếp vào danh mục. Exam trap: ETF trade intraday còn open-end mutual fund thông thường giao dịch theo NAV cuối ngày."},{"front_en":"Currencies and commodities","back_vi":"Currency markets trao đổi đơn vị tiền tệ; commodity markets gồm energy, industrial metals, precious metals và agricultural goods. Giá spot và futures có thể khác vì financing/storage/convenience yield. Exam trap: Không coi commodity return như coupon của trái phiếu."},{"front_en":"Derivatives","back_vi":"Forward là thỏa thuận bilateral tùy chỉnh; futures chuẩn hóa thường được margin/mark to market; swaps trao đổi dòng tiền; options trao quyền (không bắt buộc) thực hiện cho holder. Exam trap: Option holder không có nghĩa vụ exercise, nhưng writer có nghĩa vụ nếu được thực hiện."},{"front_en":"Real assets and property","back_vi":"Land, buildings, infrastructure và physical resources có chi phí lưu giữ, chi phí giao dịch và tính đặc thù cao; đầu tư gián tiếp qua securities khác với sở hữu trực tiếp. Exam trap: REIT share là security, khác với tòa nhà mà REIT nắm giữ."}]},{"id":"CFA26-05-01-LOS04","letter":"1.d","title_en":"Financial Intermediaries","outcome_en":"describe types of financial intermediaries and services that they provide","overview_vi":"Bám mục tiêu 1.d theo CFAI 2026. Nội dung được biên soạn lại tiếng Việt với thuật ngữ English; các illustrations và câu hỏi là tình huống gốc, cần kiểm định học thuật bổ sung trước khi coi là bản cuối.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5, LM1","pages":"37–48 (physical PDF; chapter pp13–90)"}],"sections":[{"heading":"Brokers and agents","body":"Broker thay mặt client tìm counterparties và thực hiện orders, hưởng commission/fee; không nhất thiết giữ inventory của chứng khoán. Agent phải xử lý xung đột lợi ích và execution quality.","trap":"Broker acting as agent khác dealer acting as principal."},{"heading":"Dealers and market makers","body":"Dealer mua/bán cho tài khoản của mình; bid–ask spread là nguồn bù đắp inventory, adverse-selection, processing risks. Market maker có thể cung cấp quotes nhưng không cam kết không có price impact.","trap":"Dealer chịu inventory risk, khác broker chỉ làm trung gian."},{"heading":"Exchanges, ATS and clearing","body":"Exchanges/alternative trading systems có hệ thống khớp lệnh; clearinghouses tính nghĩa vụ, quản lý collateral và có thể đứng giữa counterparties. Custodians giữ và quản lý tài sản được ghi nhận.","trap":"Trade execution, clearing và settlement là các giai đoạn khác nhau."},{"heading":"Arbitrageurs and securitizers","body":"Arbitrageurs tìm chênh lệch giá có thể khóa bằng các giao dịch tương ứng nhưng vẫn có execution/funding/basis risk. Securitizers gộp tài sản và tạo securities dựa vào dòng tiền; credit enhancement không xóa toàn bộ default risk.","trap":"Không gọi mọi giao dịch buy low/sell high theo kỳ vọng là risk-free arbitrage."},{"heading":"Banks, insurers, investment managers","body":"Depository institutions tạo điều kiện chuyển giao vốn/thanh toán và có rủi ro thanh khoản/kỳ hạn; insurers nhận phí bảo hiểm đổi lấy cam kết chi trả theo điều kiện; asset managers quản lý danh mục cho khách hàng.","trap":"Investment manager không nhất thiết sở hữu assets mà họ quản lý."}],"formulas":[{"name":"Dealer spread","expr":"Quoted spread = ask price − bid price","meaning":"Spread có thể bù inventory and adverse-selection risk.","conditions":"Quoted spread không phải tổng cost của mọi giao dịch."},{"name":"Intermediation role","expr":"Broker acts as agent; dealer acts as principal","meaning":"Vai trò và rủi ro pháp lý khác nhau.","conditions":"Một tổ chức có thể thực hiện nhiều vai trò trong các transactions khác nhau."}],"examples":[{"question_en":"A dealer quotes a bond bid of 99.20 and ask of 99.60 per 100 face. Calculate the quoted spread.","steps_vi":["Quoted spread = 99.60−99.20.","Dealer buys near bid and sells near ask, bearing inventory and credit/market risks."],"answer":"0.40 points per 100 par","check":"The dealer may also charge other fees; spread is not riskless income."}],"questions":[{"stem_en":"A firm posts bid and ask quotes and trades from its own inventory. It primarily acts as a:","options":["Broker","Dealer","Custodian"],"correct":1,"why_vi":"Dealer giao dịch với vai trò principal.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Which institution primarily safekeeps securities and administers asset records?","options":["Custodian","Speculative arbitrageur","Underwriter"],"correct":0,"why_vi":"Custodian thực hiện dịch vụ lưu giữ và hồ sơ tài sản.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Pooling loan cash flows and issuing securities backed by them is:","options":["Securitization","Share repurchase","Open market execution"],"correct":0,"why_vi":"Securitizer tạo claims dựa trên pooled financial assets.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."}],"cards":[{"front_en":"Brokers and agents","back_vi":"Broker thay mặt client tìm counterparties và thực hiện orders, hưởng commission/fee; không nhất thiết giữ inventory của chứng khoán. Agent phải xử lý xung đột lợi ích và execution quality. Exam trap: Broker acting as agent khác dealer acting as principal."},{"front_en":"Dealers and market makers","back_vi":"Dealer mua/bán cho tài khoản của mình; bid–ask spread là nguồn bù đắp inventory, adverse-selection, processing risks. Market maker có thể cung cấp quotes nhưng không cam kết không có price impact. Exam trap: Dealer chịu inventory risk, khác broker chỉ làm trung gian."},{"front_en":"Exchanges, ATS and clearing","back_vi":"Exchanges/alternative trading systems có hệ thống khớp lệnh; clearinghouses tính nghĩa vụ, quản lý collateral và có thể đứng giữa counterparties. Custodians giữ và quản lý tài sản được ghi nhận. Exam trap: Trade execution, clearing và settlement là các giai đoạn khác nhau."},{"front_en":"Arbitrageurs and securitizers","back_vi":"Arbitrageurs tìm chênh lệch giá có thể khóa bằng các giao dịch tương ứng nhưng vẫn có execution/funding/basis risk. Securitizers gộp tài sản và tạo securities dựa vào dòng tiền; credit enhancement không xóa toàn bộ default risk. Exam trap: Không gọi mọi giao dịch buy low/sell high theo kỳ vọng là risk-free arbitrage."},{"front_en":"Banks, insurers, investment managers","back_vi":"Depository institutions tạo điều kiện chuyển giao vốn/thanh toán và có rủi ro thanh khoản/kỳ hạn; insurers nhận phí bảo hiểm đổi lấy cam kết chi trả theo điều kiện; asset managers quản lý danh mục cho khách hàng. Exam trap: Investment manager không nhất thiết sở hữu assets mà họ quản lý."}]},{"id":"CFA26-05-01-LOS05","letter":"1.e","title_en":"Investment Positions","outcome_en":"compare positions an investor can take in an asset","overview_vi":"Bám mục tiêu 1.e theo CFAI 2026. Nội dung được biên soạn lại tiếng Việt với thuật ngữ English; các illustrations và câu hỏi là tình huống gốc, cần kiểm định học thuật bổ sung trước khi coi là bản cuối.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5, LM1","pages":"48–56 (physical PDF; chapter pp13–90)"}],"sections":[{"heading":"Long exposure","body":"Long position có lợi khi asset price tăng (bỏ qua carry); maximum loss khi sở hữu cổ phiếu hoàn toàn bằng vốn tự có thường bằng khoản đầu tư, trong khi upside không bị chặn theo giá.","trap":"Long underlying khác long put/short call về payoff."},{"heading":"Short selling","body":"Short seller vay asset rồi bán, kỳ vọng mua lại giá thấp hơn và hoàn trả; có borrow fees, margin requirements, dividend obligations và nguy cơ squeeze/recall. Loss lý thuyết không giới hạn khi giá tăng.","trap":"Short sale không đồng nghĩa sở hữu một put option."},{"heading":"Hedging versus speculation","body":"Hedging thiết kế giảm risk exposure đang có; speculation cố ý chịu exposure vì kỳ vọng return. Một vị thế futures có thể phục vụ cả hai tùy danh mục cơ sở.","trap":"Đừng phân loại bằng tên công cụ mà bỏ qua mục đích giao dịch."},{"heading":"Payoff and funding","body":"Net payoff = biến động giá trị exposure trừ financing fees/transaction costs và cộng các cash flows liên quan. Long leveraged equity có thể bị margin call ngay cả khi quan điểm dài hạn chưa thay đổi.","trap":"Phân biệt dollar P&L, gross return và return trên equity bỏ ra."}],"formulas":[{"name":"Long stock capital gain","expr":"P&L = N × (sale price − purchase price)","meaning":"Trước dividends, interest và fees.","conditions":"Gross P&L khác return on investor equity."},{"name":"Short stock capital gain","expr":"P&L = N × (initial short sale price − covering purchase price)","meaning":"Trước borrowing fee/dividends owed/margin interest.","conditions":"Loss của short stock không bị chặn khi price tăng."}],"examples":[{"question_en":"An investor shorts 40 shares at $52, covers at $60, and pays $12 in borrow fees. Calculate net P&L.","steps_vi":["Short-sale cash inflow = 40×52=$2,080.","Cover cost = 40×60=$2,400.","Net P&L = 2,080−2,400−12."],"answer":"−$332","check":"Assumes no dividends owed, margin interest, commissions or taxes."}],"questions":[{"stem_en":"Which investor position can have theoretically unlimited losses when the underlying stock price rises?","options":["Fully paid long stock","Short stock","Long put option"],"correct":1,"why_vi":"Short stock cần mua lại để cover nên loss không có trần theo giá tăng.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"An airline buys fuel futures to reduce exposure to fuel price increases. The use is primarily:","options":["A hedge","A guaranteed profit","A corporate bond issuance"],"correct":0,"why_vi":"Đây là hedging exposure chi phí nhiên liệu.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"An investor buys one share for $40 and sells it for $47, ignoring fees and dividends. The gain is:","options":["$7","$40","$47"],"correct":0,"why_vi":"Gain = sale price − purchase price = 7 USD.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."}],"cards":[{"front_en":"Long exposure","back_vi":"Long position có lợi khi asset price tăng (bỏ qua carry); maximum loss khi sở hữu cổ phiếu hoàn toàn bằng vốn tự có thường bằng khoản đầu tư, trong khi upside không bị chặn theo giá. Exam trap: Long underlying khác long put/short call về payoff."},{"front_en":"Short selling","back_vi":"Short seller vay asset rồi bán, kỳ vọng mua lại giá thấp hơn và hoàn trả; có borrow fees, margin requirements, dividend obligations và nguy cơ squeeze/recall. Loss lý thuyết không giới hạn khi giá tăng. Exam trap: Short sale không đồng nghĩa sở hữu một put option."},{"front_en":"Hedging versus speculation","back_vi":"Hedging thiết kế giảm risk exposure đang có; speculation cố ý chịu exposure vì kỳ vọng return. Một vị thế futures có thể phục vụ cả hai tùy danh mục cơ sở. Exam trap: Đừng phân loại bằng tên công cụ mà bỏ qua mục đích giao dịch."},{"front_en":"Payoff and funding","back_vi":"Net payoff = biến động giá trị exposure trừ financing fees/transaction costs và cộng các cash flows liên quan. Long leveraged equity có thể bị margin call ngay cả khi quan điểm dài hạn chưa thay đổi. Exam trap: Phân biệt dollar P&L, gross return và return trên equity bỏ ra."}]},{"id":"CFA26-05-01-LOS06","letter":"1.f","title_en":"Margin and Leverage","outcome_en":"calculate and interpret the leverage ratio, the rate of return on a margin transaction, and the security price at which the investor would receive a margin call","overview_vi":"Bám mục tiêu 1.f theo CFAI 2026. Nội dung được biên soạn lại tiếng Việt với thuật ngữ English; các illustrations và câu hỏi là tình huống gốc, cần kiểm định học thuật bổ sung trước khi coi là bản cuối.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5, LM1","pages":"51–56 (physical PDF; chapter pp13–90)"}],"sections":[{"heading":"Initial margin and leverage","body":"Nếu mua V USD stocks, tự có E USD và vay D=V−E, initial margin m0=E/V. Leverage ratio V/E=1/m0. Đòn bẩy làm biến động return trên equity lớn hơn return asset khi bỏ qua interest/fees.","trap":"Initial margin 40% tương ứng leverage 2.5×, không phải 0.4×."},{"heading":"Return on margined long","body":"Equity cuối kỳ = N×P1−D−interest; equity đầu kỳ = N×P0−D. HPR = (ending equity + dividends − beginning equity)/beginning equity; có thể viết (N(P1−P0)+dividends−interest−fees)/initial equity.","trap":"Khoản vay gốc không phải interest expense và phải được trừ khỏi ending equity."},{"heading":"Maintenance margin and call price","body":"Maintenance margin m = (market value−loan)/market value. Với long margin và nợ không đổi, call price P* = loan/[N(1−m)] = P0(1−m0)/(1−m), nếu chưa gồm lãi/phí tích lũy. Giá xuống dưới ngưỡng sẽ gây margin call.","trap":"Mẫu số là (1−maintenance margin), không phải maintenance margin."},{"heading":"Short margin and constraints","body":"Short sale proceeds thường bị giữ làm collateral cùng initial margin; khi price tăng, collateral equity giảm và có thể xảy ra margin call. Công thức ngưỡng của long không được áp nguyên xi cho short.","trap":"Loan proceeds không phải số tiền người bán khống được tùy ý rút."},{"heading":"Stress and liquidation","body":"Margin call có thể buộc nộp thêm collateral hoặc liquidate asset; broker có thể áp house requirements cao hơn minimum. Interest, borrow cost và dividends làm realized margin return thấp hơn gross price return.","trap":"Leverage tăng cả gains lẫn losses, có thể làm equity về 0 trước khi asset price về 0."}],"formulas":[{"name":"Initial margin","expr":"m₀ = equity / initial market value","meaning":"Equity invested relative to gross stock exposure.","conditions":"Long margined stock."},{"name":"Leverage ratio","expr":"L = initial market value / initial equity = 1/m₀","meaning":"Tỷ số exposure trên equity.","conditions":"Before costs."},{"name":"Long leveraged HPR","expr":"R = [N(P₁−P₀)+dividends−interest−fees] / initial equity","meaning":"Lãi vốn trên equity nhà đầu tư.","conditions":"Loan principal remains owed."},{"name":"Long margin call","expr":"P* = loan / [N(1−maintenance margin)]","meaning":"Giá mà equity/market value chạm maintenance requirement.","conditions":"Only long; constant loan; disregard accrued costs."}],"examples":[{"question_en":"A trader buys 150 shares at $40 using 35% initial equity. Maintenance margin is 25%. Find long margin-call price (ignore interest).","steps_vi":["Initial market value=150×40=$6,000; equity=$2,100; loan=$3,900.","Set (150P−3,900)/(150P)=25%.","Solve P =3,900/(150×0.75)."],"answer":"$34.67 per share (rounded)","check":"Different broker house margin may cause an earlier call."},{"question_en":"A margined share position costs $25,000, funded with $10,000 equity and $15,000 loan. Stock rises 12%; interest paid is $150. Compute equity return.","steps_vi":["Stock P&L =25,000×12%=$3,000.","Net P&L after interest=$2,850.","Return=$2,850/$10,000."],"answer":"28.5%","check":"No dividends, fees, loan repayment or principal changes beyond stated."}],"questions":[{"stem_en":"An investor purchases $20,000 of shares using $8,000 equity. The initial leverage ratio is closest to:","options":["1.5 times","2.5 times","4.0 times"],"correct":1,"why_vi":"Leverage = 20,000/8,000 = 2.5×.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"A trader buys 100 shares at $50 with 40% initial margin and 25% maintenance margin. Ignoring interest, the long margin-call price is closest to:","options":["$30","$40","$45"],"correct":1,"why_vi":"Loan = 100×50×60%=3,000; threshold=3,000/(100×0.75)=$40.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"A trader buys $10,000 in stock with $5,000 equity and $5,000 debt. The stock value rises to $11,000. Ignoring costs, the equity return is closest to:","options":["10%","20%","25%"],"correct":1,"why_vi":"Ending equity = 11,000−5,000=6,000; return=(6,000−5,000)/5,000=20%.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."}],"cards":[{"front_en":"Initial margin and leverage","back_vi":"Nếu mua V USD stocks, tự có E USD và vay D=V−E, initial margin m0=E/V. Leverage ratio V/E=1/m0. Đòn bẩy làm biến động return trên equity lớn hơn return asset khi bỏ qua interest/fees. Exam trap: Initial margin 40% tương ứng leverage 2.5×, không phải 0.4×."},{"front_en":"Return on margined long","back_vi":"Equity cuối kỳ = N×P1−D−interest; equity đầu kỳ = N×P0−D. HPR = (ending equity + dividends − beginning equity)/beginning equity; có thể viết (N(P1−P0)+dividends−interest−fees)/initial equity. Exam trap: Khoản vay gốc không phải interest expense và phải được trừ khỏi ending equity."},{"front_en":"Maintenance margin and call price","back_vi":"Maintenance margin m = (market value−loan)/market value. Với long margin và nợ không đổi, call price P* = loan/[N(1−m)] = P0(1−m0)/(1−m), nếu chưa gồm lãi/phí tích lũy. Giá xuống dưới ngưỡng sẽ gây margin call. Exam trap: Mẫu số là (1−maintenance margin), không phải maintenance margin."},{"front_en":"Short margin and constraints","back_vi":"Short sale proceeds thường bị giữ làm collateral cùng initial margin; khi price tăng, collateral equity giảm và có thể xảy ra margin call. Công thức ngưỡng của long không được áp nguyên xi cho short. Exam trap: Loan proceeds không phải số tiền người bán khống được tùy ý rút."},{"front_en":"Stress and liquidation","back_vi":"Margin call có thể buộc nộp thêm collateral hoặc liquidate asset; broker có thể áp house requirements cao hơn minimum. Interest, borrow cost và dividends làm realized margin return thấp hơn gross price return. Exam trap: Leverage tăng cả gains lẫn losses, có thể làm equity về 0 trước khi asset price về 0."}]},{"id":"CFA26-05-01-LOS07","letter":"1.g","title_en":"Execution, Validity and Clearing Instructions","outcome_en":"compare execution, validity, and clearing instructions","overview_vi":"Bám mục tiêu 1.g theo CFAI 2026. Nội dung được biên soạn lại tiếng Việt với thuật ngữ English; các illustrations và câu hỏi là tình huống gốc, cần kiểm định học thuật bổ sung trước khi coi là bản cuối.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5, LM1","pages":"56–63 (physical PDF; chapter pp13–90)"}],"sections":[{"heading":"Execution instructions","body":"Execution rules xác định cách lệnh được khớp: market, limit, stop, stop-limit, all-or-none, immediate-or-cancel (IOC) và fill-or-kill (FOK) là các ví dụ cần phân biệt theo điều kiện.","trap":"All-or-none có thể chờ khớp; FOK thường yêu cầu khớp ngay toàn bộ hoặc hủy."},{"heading":"Validity instructions","body":"Validity xác định lệnh có hiệu lực bao lâu: day order hết hiệu lực cuối phiên; good-til-canceled duy trì đến khi khớp/hủy hoặc hết giới hạn broker; IOC xử lý phần không khớp ngay.","trap":"Validity là thời gian tồn tại, không phải giá tối đa/minimum."},{"heading":"Clearing instructions","body":"Clearing xác định cách xử lý sau execution: tài khoản được phân bổ, đối tác/clearing agent và cơ chế settlement. Confirmation có thể đến trước khi actual cash/securities settlement hoàn tất.","trap":"Executed trade chưa đồng nghĩa settled trade."},{"heading":"Stop orders and conditional logic","body":"Stop buy được kích hoạt khi giá lên tới stop (thường dùng để cover short hoặc momentum); stop sell khi giá giảm đến stop. Sau kích hoạt, stop market có execution uncertainty về giá; stop limit có nguy cơ không khớp.","trap":"Stop price là trigger, không phải giá khớp được bảo đảm."}],"formulas":[{"name":"IOC","expr":"Immediate fill of available quantity; cancel remainder","meaning":"Xác định validity/execution.","conditions":"Some venue-specific details vary."},{"name":"FOK","expr":"Execute entire quantity immediately or cancel","meaning":"Không được partial fill.","conditions":"Do not conflate with all-or-none non-immediate."},{"name":"Stop market","expr":"When triggered → market order","meaning":"Kích hoạt không đảm bảo trigger price là execution price.","conditions":"Gaps cause slippage."}],"examples":[{"question_en":"A buy order for 600 shares is marked IOC. Only 350 shares are immediately available at acceptable prices. What happens?","steps_vi":["An IOC executes the available 350 shares immediately.","The remaining 250 shares are canceled; they do not rest in the book."],"answer":"350 filled; 250 canceled","check":"If the instruction had been FOK, the whole order would be canceled."}],"questions":[{"stem_en":"A day order that is not executed is generally canceled:","options":["At the close of the trading day","Only after 30 calendar days","Immediately upon submission"],"correct":0,"why_vi":"Day order hết hiệu lực cuối phiên nếu không khớp.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"An instruction to execute any immediately available quantity and cancel the remainder is:","options":["GTC","IOC","Day only"],"correct":1,"why_vi":"IOC fill phần có thể fill ngay và cancel phần còn lại.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Which instruction mainly identifies how an executed trade should be processed after execution?","options":["Clearing instruction","Limit-price instruction","Stop trigger"],"correct":0,"why_vi":"Clearing liên quan post-trade processing.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."}],"cards":[{"front_en":"Execution instructions","back_vi":"Execution rules xác định cách lệnh được khớp: market, limit, stop, stop-limit, all-or-none, immediate-or-cancel (IOC) và fill-or-kill (FOK) là các ví dụ cần phân biệt theo điều kiện. Exam trap: All-or-none có thể chờ khớp; FOK thường yêu cầu khớp ngay toàn bộ hoặc hủy."},{"front_en":"Validity instructions","back_vi":"Validity xác định lệnh có hiệu lực bao lâu: day order hết hiệu lực cuối phiên; good-til-canceled duy trì đến khi khớp/hủy hoặc hết giới hạn broker; IOC xử lý phần không khớp ngay. Exam trap: Validity là thời gian tồn tại, không phải giá tối đa/minimum."},{"front_en":"Clearing instructions","back_vi":"Clearing xác định cách xử lý sau execution: tài khoản được phân bổ, đối tác/clearing agent và cơ chế settlement. Confirmation có thể đến trước khi actual cash/securities settlement hoàn tất. Exam trap: Executed trade chưa đồng nghĩa settled trade."},{"front_en":"Stop orders and conditional logic","back_vi":"Stop buy được kích hoạt khi giá lên tới stop (thường dùng để cover short hoặc momentum); stop sell khi giá giảm đến stop. Sau kích hoạt, stop market có execution uncertainty về giá; stop limit có nguy cơ không khớp. Exam trap: Stop price là trigger, không phải giá khớp được bảo đảm."}]},{"id":"CFA26-05-01-LOS08","letter":"1.h","title_en":"Market and Limit Orders","outcome_en":"compare market orders with limit orders","overview_vi":"Bám mục tiêu 1.h theo CFAI 2026. Nội dung được biên soạn lại tiếng Việt với thuật ngữ English; các illustrations và câu hỏi là tình huống gốc, cần kiểm định học thuật bổ sung trước khi coi là bản cuối.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5, LM1","pages":"53–63 (physical PDF; chapter pp13–90)"}],"sections":[{"heading":"Market order","body":"Market order ưu tiên tốc độ/khả năng khớp theo giá đang có, không bảo đảm mức giá cụ thể; market impact và price slippage có thể cao khi thanh khoản thấp.","trap":"Market order bảo đảm execution priority chứ không bảo đảm price."},{"heading":"Limit order","body":"Limit buy quy định mức giá tối đa muốn trả; limit sell là mức giá tối thiểu chấp nhận. Nếu thị trường không chạm điều kiện hoặc thiếu counterparties, lệnh có thể không khớp.","trap":"Limit order kiểm soát giá nhưng hy sinh execution certainty."},{"heading":"Bid and ask","body":"Bid là giá mà dealer/buyer sẵn sàng mua, ask/offer là giá bán. Buy market order thường hitting ask; sell market order hitting bid. Spread là ask−bid và phản ánh liquidity/risks.","trap":"Không nhầm bid là mức giá bạn phải trả khi mua."},{"heading":"Price-time priority and queue","body":"Trong order-driven market, lệnh giá tốt hơn được ưu tiên; giữa các lệnh cùng giá, thời điểm đặt thường quyết định thứ tự theo quy tắc venue. A limit order may be marketable nếu giá của nó vượt best opposite quote.","trap":"Limit order không nhất thiết chờ: aggressive limit có thể fill ngay."},{"heading":"Execution trade-off","body":"Lệnh lớn trong thị trường mỏng có thể khớp nhiều mức giá; trader cân đối certainty, spread, market impact và opportunity cost. Đơn vị giá có thể chịu tick size.","trap":"Price guarantee của limit chỉ áp giá, không áp số lượng được khớp."}],"formulas":[{"name":"Quoted spread","expr":"Ask − bid","meaning":"Measure of quoted dealing friction.","conditions":"Actual fills may involve depth/slippage."},{"name":"Buy limit","expr":"Execution price ≤ specified limit price","meaning":"Giá cao nhất chấp nhận trả.","conditions":"No execution certainty."},{"name":"Sell limit","expr":"Execution price ≥ specified limit price","meaning":"Giá thấp nhất chấp nhận nhận.","conditions":"No execution certainty."}],"examples":[{"question_en":"The best bid is $49.80 and ask $50.10. A client posts a buy limit order at $49.95 with no seller willing to transact there. Describe execution.","steps_vi":["The buy limit order cannot pay above $49.95.","The best ask is $50.10, so this order does not immediately cross the spread."],"answer":"It rests unfilled (subject to venue rules).","check":"A market buy would normally execute near the available ask, ignoring depth."}],"questions":[{"stem_en":"The primary benefit of a buy limit order relative to a market order is:","options":["Guaranteed immediate execution","Control of maximum execution price","No trading costs"],"correct":1,"why_vi":"Buy limit đặt giá trần chấp nhận.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"A trader submits a market buy order when the best bid is $20.00 and the best ask is $20.08. In a liquid market, the trader initially buys near:","options":["$20.00","$20.08","$20.04"],"correct":1,"why_vi":"Market buy thường khớp với resting ask.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"An investor enters a sell limit order at $32. Which outcome is most consistent?","options":["An execution at $31.50 is acceptable","The order may not execute if buyers bid below $32","Execution is guaranteed immediately"],"correct":1,"why_vi":"Sell limit chỉ chấp nhận giá bán ít nhất $32.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."}],"cards":[{"front_en":"Market order","back_vi":"Market order ưu tiên tốc độ/khả năng khớp theo giá đang có, không bảo đảm mức giá cụ thể; market impact và price slippage có thể cao khi thanh khoản thấp. Exam trap: Market order bảo đảm execution priority chứ không bảo đảm price."},{"front_en":"Limit order","back_vi":"Limit buy quy định mức giá tối đa muốn trả; limit sell là mức giá tối thiểu chấp nhận. Nếu thị trường không chạm điều kiện hoặc thiếu counterparties, lệnh có thể không khớp. Exam trap: Limit order kiểm soát giá nhưng hy sinh execution certainty."},{"front_en":"Bid and ask","back_vi":"Bid là giá mà dealer/buyer sẵn sàng mua, ask/offer là giá bán. Buy market order thường hitting ask; sell market order hitting bid. Spread là ask−bid và phản ánh liquidity/risks. Exam trap: Không nhầm bid là mức giá bạn phải trả khi mua."},{"front_en":"Price-time priority and queue","back_vi":"Trong order-driven market, lệnh giá tốt hơn được ưu tiên; giữa các lệnh cùng giá, thời điểm đặt thường quyết định thứ tự theo quy tắc venue. A limit order may be marketable nếu giá của nó vượt best opposite quote. Exam trap: Limit order không nhất thiết chờ: aggressive limit có thể fill ngay."},{"front_en":"Execution trade-off","back_vi":"Lệnh lớn trong thị trường mỏng có thể khớp nhiều mức giá; trader cân đối certainty, spread, market impact và opportunity cost. Đơn vị giá có thể chịu tick size. Exam trap: Price guarantee của limit chỉ áp giá, không áp số lượng được khớp."}]},{"id":"CFA26-05-01-LOS09","letter":"1.i","title_en":"Primary and Secondary Markets","outcome_en":"define primary and secondary markets and explain how secondary markets support primary markets","overview_vi":"Bám mục tiêu 1.i theo CFAI 2026. Nội dung được biên soạn lại tiếng Việt với thuật ngữ English; các illustrations và câu hỏi là tình huống gốc, cần kiểm định học thuật bổ sung trước khi coi là bản cuối.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5, LM1","pages":"60–68 (physical PDF; chapter pp13–90)"}],"sections":[{"heading":"Primary issuance","body":"Issuer bán securities mới qua IPO, seasoned offering, rights offering, private placement hoặc debt issue. Cash proceeds trực tiếp đến issuer (ngoại trừ selling shareholders trong một số offerings).","trap":"Không phải mọi IPO share do công ty phát hành mới; có thể có secondary sale của cổ đông hiện hữu."},{"heading":"Underwriting and book building","body":"Investment banks hỗ trợ price discovery/distribution, có thể underwrite (firm commitment) hoặc best efforts; book building thu demand của institutional investors, allocation không nhất thiết đơn giản theo thứ tự đặt mua.","trap":"Firm commitment khiến underwriter nhận risk bán không hết nhiều hơn best efforts."},{"heading":"Secondary trading","body":"Securities đã lưu hành được trao đổi giữa investors; liquidity và transparent prices làm giảm required liquidity premium và hỗ trợ issuer huy động vốn ở primary.","trap":"Secondary trading của một outstanding share thường không đem cash mới cho issuer."},{"heading":"Public and private markets","body":"Public offerings thường có disclosure/registration chặt hơn và khả năng giao dịch rộng; private placements có thể phù hợp doanh nghiệp nhỏ hoặc nhà đầu tư chuyên nghiệp nhưng restrictions khiến secondary liquidity kém.","trap":"Private là hình thức phân phối chứ không nhất thiết có tài sản tốt/xấu khác."},{"heading":"Why secondary liquidity matters","body":"Nếu nhà đầu tư tin có thể thoái vốn với chi phí thấp, họ sẵn sàng góp vốn dài hạn cho issuer; tuy nhiên liquidity thay đổi theo stress, không bảo đảm chống drawdown.","trap":"Thanh khoản thị trường thứ cấp hỗ trợ, không thay thế, fundamental credit/equity risk."}],"formulas":[{"name":"Primary market cash","expr":"New securities issued → issuer financing proceeds","meaning":"Company receives funds through issuance.","conditions":"Secondary holder sales can appear in the same public offering."},{"name":"Secondary market cash","expr":"Outstanding asset transferred: buyer → seller","meaning":"Issuer typically not direct counterparty.","conditions":"Market value of issuer may change, but does not imply newly raised cash."}],"examples":[{"question_en":"An issuer sells 2 million newly issued shares at $12 per share. One month later their exchange price rises to $15. Find initial gross financing, ignoring fees.","steps_vi":["Initial gross issuer proceeds=2,000,000×$12=$24,000,000.","The move to $15 in the secondary market does not by itself issue new shares."],"answer":"$24 million","check":"Market capitalization may grow without a cash inflow to issuer."}],"questions":[{"stem_en":"An investor buys outstanding shares from another investor on an exchange. The issuing firm generally:","options":["Receives the full trade proceeds","Receives no proceeds from the investor-to-investor trade","Issues new debt automatically"],"correct":1,"why_vi":"Secondary trade chuyển cash giữa nhà đầu tư.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"A company newly sells shares to raise capital. The sale occurs in the:","options":["Primary market","Secondary market","Interdealer market only"],"correct":0,"why_vi":"New issuance phục vụ financing của issuer.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Under a firm-commitment underwriting, which party typically bears greater risk of unsold securities?","options":["The underwriting dealer","The securities depository","The exchange regulator"],"correct":0,"why_vi":"Underwriter mua securities rồi phân phối, chịu placement risk.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."}],"cards":[{"front_en":"Primary issuance","back_vi":"Issuer bán securities mới qua IPO, seasoned offering, rights offering, private placement hoặc debt issue. Cash proceeds trực tiếp đến issuer (ngoại trừ selling shareholders trong một số offerings). Exam trap: Không phải mọi IPO share do công ty phát hành mới; có thể có secondary sale của cổ đông hiện hữu."},{"front_en":"Underwriting and book building","back_vi":"Investment banks hỗ trợ price discovery/distribution, có thể underwrite (firm commitment) hoặc best efforts; book building thu demand của institutional investors, allocation không nhất thiết đơn giản theo thứ tự đặt mua. Exam trap: Firm commitment khiến underwriter nhận risk bán không hết nhiều hơn best efforts."},{"front_en":"Secondary trading","back_vi":"Securities đã lưu hành được trao đổi giữa investors; liquidity và transparent prices làm giảm required liquidity premium và hỗ trợ issuer huy động vốn ở primary. Exam trap: Secondary trading của một outstanding share thường không đem cash mới cho issuer."},{"front_en":"Public and private markets","back_vi":"Public offerings thường có disclosure/registration chặt hơn và khả năng giao dịch rộng; private placements có thể phù hợp doanh nghiệp nhỏ hoặc nhà đầu tư chuyên nghiệp nhưng restrictions khiến secondary liquidity kém. Exam trap: Private là hình thức phân phối chứ không nhất thiết có tài sản tốt/xấu khác."},{"front_en":"Why secondary liquidity matters","back_vi":"Nếu nhà đầu tư tin có thể thoái vốn với chi phí thấp, họ sẵn sàng góp vốn dài hạn cho issuer; tuy nhiên liquidity thay đổi theo stress, không bảo đảm chống drawdown. Exam trap: Thanh khoản thị trường thứ cấp hỗ trợ, không thay thế, fundamental credit/equity risk."}]},{"id":"CFA26-05-01-LOS10","letter":"1.j","title_en":"Trading Market Structures","outcome_en":"describe how securities, contracts, and currencies are traded in quote-driven, order-driven, and brokered markets","overview_vi":"Bám mục tiêu 1.j theo CFAI 2026. Nội dung được biên soạn lại tiếng Việt với thuật ngữ English; các illustrations và câu hỏi là tình huống gốc, cần kiểm định học thuật bổ sung trước khi coi là bản cuối.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5, LM1","pages":"65–71 (physical PDF; chapter pp13–90)"}],"sections":[{"heading":"Quote-driven/dealer markets","body":"Dealers liên tục báo bid/ask và sẵn sàng giao dịch trên inventory theo quote và quy tắc; OTC FX và một số bond markets có nhiều dealer quotation. Liquidity gắn với risk capacity của dealers.","trap":"Quote-driven không đồng nghĩa market không có electronic systems."},{"heading":"Order-driven markets","body":"Orders của buyers và sellers tương tác trong limit order book; matched trades dựa trên price/time hoặc venue priority. No intermediary principal need take every other side.","trap":"Order-driven vẫn có thể có market makers tham gia như những traders."},{"heading":"Brokered markets","body":"Brokers chuyên tìm và kết nối counterparties khi assets kém chuẩn hóa hoặc giao dịch có kích thước lớn; sau negotiation, terms có thể tùy chỉnh, mất thời gian hơn.","trap":"Brokered market không bảo đảm nhanh hoặc spread thấp."},{"heading":"Auction and trading sessions","body":"Call auction gom lệnh và match tại thời điểm riêng; continuous trading khớp liên tục khi xuất hiện orders phù hợp. Đấu giá giúp tập trung liquidity lúc mở/đóng phiên.","trap":"Auction price discovery khác market order qua continuous book."},{"heading":"Transparency and information","body":"Pre-trade transparency (quotes/order depth) khác post-trade transparency (reported prices/volume); disclosure hỗ trợ price discovery nhưng quá trình hình thành giá có thể chịu strategic order submission.","trap":"Transparent quote không bảo đảm không có hidden liquidity hoặc dark pools."}],"formulas":[{"name":"Quote-driven","expr":"Dealer ↔ client (quoted bid/ask)","meaning":"Principal-based market-making mechanism.","conditions":"Not all dealer markets lack electronic order facilities."},{"name":"Order-driven","expr":"Buyer order ↔ seller order via matching rules","meaning":"Price/time priority usually relevant.","conditions":"Trading venues can hybridize mechanisms."},{"name":"Brokered","expr":"Broker searches/matches counterparties","meaning":"For illiquid, bespoke and large transactions.","conditions":"Broker is agent, not necessarily dealer."}],"examples":[{"question_en":"A large nonstandard loan portfolio is hard to match on a centralized limit order book. A specialist contacts candidate buyers for the seller. Classify the execution structure.","steps_vi":["The specialist searches for and negotiates with counterparties.","The broker does not necessarily commit inventory as principal."],"answer":"Brokered market","check":"Quote-driven would imply dealers offering their own bid/ask as principals."}],"questions":[{"stem_en":"Which structure relies primarily on dealers posting prices at which they are willing to trade?","options":["Quote-driven market","Pure brokered market","Issuer primary sale"],"correct":0,"why_vi":"Dealer quotes là nét phân biệt.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Orders are matched directly using an electronic limit order book. The market is primarily:","options":["Quote-driven","Order-driven","Brokered only"],"correct":1,"why_vi":"Order-driven match orders theo price/time/venue rules.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Which market structure is most associated with brokers seeking counterparties for difficult-to-trade assets?","options":["Brokered","Exchange call auction only","Central bank auction only"],"correct":0,"why_vi":"Broker tìm counterparts cho giao dịch kém tiêu chuẩn hóa.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."}],"cards":[{"front_en":"Quote-driven/dealer markets","back_vi":"Dealers liên tục báo bid/ask và sẵn sàng giao dịch trên inventory theo quote và quy tắc; OTC FX và một số bond markets có nhiều dealer quotation. Liquidity gắn với risk capacity của dealers. Exam trap: Quote-driven không đồng nghĩa market không có electronic systems."},{"front_en":"Order-driven markets","back_vi":"Orders của buyers và sellers tương tác trong limit order book; matched trades dựa trên price/time hoặc venue priority. No intermediary principal need take every other side. Exam trap: Order-driven vẫn có thể có market makers tham gia như những traders."},{"front_en":"Brokered markets","back_vi":"Brokers chuyên tìm và kết nối counterparties khi assets kém chuẩn hóa hoặc giao dịch có kích thước lớn; sau negotiation, terms có thể tùy chỉnh, mất thời gian hơn. Exam trap: Brokered market không bảo đảm nhanh hoặc spread thấp."},{"front_en":"Auction and trading sessions","back_vi":"Call auction gom lệnh và match tại thời điểm riêng; continuous trading khớp liên tục khi xuất hiện orders phù hợp. Đấu giá giúp tập trung liquidity lúc mở/đóng phiên. Exam trap: Auction price discovery khác market order qua continuous book."},{"front_en":"Transparency and information","back_vi":"Pre-trade transparency (quotes/order depth) khác post-trade transparency (reported prices/volume); disclosure hỗ trợ price discovery nhưng quá trình hình thành giá có thể chịu strategic order submission. Exam trap: Transparent quote không bảo đảm không có hidden liquidity hoặc dark pools."}]},{"id":"CFA26-05-01-LOS11","letter":"1.k","title_en":"Well-Functioning Financial Systems","outcome_en":"describe characteristics of a well-functioning financial system","overview_vi":"Bám mục tiêu 1.k theo CFAI 2026. Nội dung được biên soạn lại tiếng Việt với thuật ngữ English; các illustrations và câu hỏi là tình huống gốc, cần kiểm định học thuật bổ sung trước khi coi là bản cuối.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5, LM1","pages":"69–76 (physical PDF; chapter pp13–90)"}],"sections":[{"heading":"Liquidity and low transaction costs","body":"A good financial system allows investors to trade with reasonable spread, market impact, processing and settlement risk. Liquidity phụ thuộc conditions và có thể biến mất khi market stress.","trap":"Low quoted spread không phải bằng chứng duy nhất của liquidity."},{"heading":"Accurate price discovery","body":"Thông tin liên quan được reflected reasonably quickly in prices; transparency và competitive participation cải thiện chất lượng giá; mispricing tạm thời vẫn có thể xảy ra.","trap":"Efficiency không yêu cầu mọi giá luôn chính xác tuyệt đối."},{"heading":"Efficient capital allocation","body":"Dòng vốn hướng đến các cơ hội có risk-adjusted expected returns phù hợp; borrowers và savers tiếp cận thị trường, có contracts thực thi được và investor protections.","trap":"Lợi nhuận cao không chứng minh thị trường phân bổ vốn tốt nếu risk bị che giấu."},{"heading":"Risk management and robustness","body":"Clearing, settlement, custody, governance và regulation giúp hạn chế fraud, systemic externalities và operational failures; hệ thống cần chịu được shocks.","trap":"Hệ thống well-functioning vẫn có losses và defaults."},{"heading":"Market integrity and equal access","body":"Fair dealing, disclosure và chống market manipulation giúp investors tin tưởng; một thị trường có liquidity cao nhưng pervasive insider abuse chưa đạt chất lượng cao.","trap":"Công bằng là fairness of rules/information—not guaranteed investor profits."}],"formulas":[{"name":"Transaction frictions","expr":"All-in trading cost ≈ commissions + spread costs + market impact + delay","meaning":"Qualitative approximation of sources of implementation cost.","conditions":"Avoid treating all components as fixed or independent."},{"name":"Market quality","expr":"Liquidity + information efficiency + safety + fairness","meaning":"Schematic multidimensional framework.","conditions":"No single metric suffices."}],"examples":[{"question_en":"A market reports a bid of $120, ask of $121 and rapid settlement. Yet issuers frequently hide material information. Is it fully well functioning?","steps_vi":["Low spreads and timely settlement support market liquidity and operations.","Material information withholding damages transparency, price discovery and confidence."],"answer":"No; market integrity and information efficiency also matter.","check":"Do not equate high liquidity with fair/efficient capital allocation."}],"questions":[{"stem_en":"Which characteristic best supports a well-functioning financial system?","options":["Low execution and settlement frictions","Guaranteed equity returns","Permanent elimination of credit losses"],"correct":0,"why_vi":"Low frictions hỗ trợ huy động và phân bổ vốn.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"A market with prompt incorporation of public information most directly supports:","options":["Price discovery","Risk-free leverage","Fixed investor payoffs"],"correct":0,"why_vi":"Price discovery phản ánh thông tin vào giá.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Which feature improves confidence in financial markets?","options":["Reliable disclosure and enforcement","Guaranteed stock appreciation","Prohibition of all losses"],"correct":0,"why_vi":"Market integrity dựa trên transparency, supervision và enforcement.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."}],"cards":[{"front_en":"Liquidity and low transaction costs","back_vi":"A good financial system allows investors to trade with reasonable spread, market impact, processing and settlement risk. Liquidity phụ thuộc conditions và có thể biến mất khi market stress. Exam trap: Low quoted spread không phải bằng chứng duy nhất của liquidity."},{"front_en":"Accurate price discovery","back_vi":"Thông tin liên quan được reflected reasonably quickly in prices; transparency và competitive participation cải thiện chất lượng giá; mispricing tạm thời vẫn có thể xảy ra. Exam trap: Efficiency không yêu cầu mọi giá luôn chính xác tuyệt đối."},{"front_en":"Efficient capital allocation","back_vi":"Dòng vốn hướng đến các cơ hội có risk-adjusted expected returns phù hợp; borrowers và savers tiếp cận thị trường, có contracts thực thi được và investor protections. Exam trap: Lợi nhuận cao không chứng minh thị trường phân bổ vốn tốt nếu risk bị che giấu."},{"front_en":"Risk management and robustness","back_vi":"Clearing, settlement, custody, governance và regulation giúp hạn chế fraud, systemic externalities và operational failures; hệ thống cần chịu được shocks. Exam trap: Hệ thống well-functioning vẫn có losses và defaults."},{"front_en":"Market integrity and equal access","back_vi":"Fair dealing, disclosure và chống market manipulation giúp investors tin tưởng; một thị trường có liquidity cao nhưng pervasive insider abuse chưa đạt chất lượng cao. Exam trap: Công bằng là fairness of rules/information—not guaranteed investor profits."}]},{"id":"CFA26-05-01-LOS12","letter":"1.l","title_en":"Market Regulation Objectives","outcome_en":"describe objectives of market regulation","overview_vi":"Bám mục tiêu 1.l theo CFAI 2026. Nội dung được biên soạn lại tiếng Việt với thuật ngữ English; các illustrations và câu hỏi là tình huống gốc, cần kiểm định học thuật bổ sung trước khi coi là bản cuối.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5, LM1","pages":"73–76 (physical PDF; chapter pp13–90)"}],"sections":[{"heading":"Fair and orderly markets","body":"Market regulation nhằm hạn chế fraud, manipulation, insider abuse và bảo vệ fair access/process; chú trọng public confidence. Không thể bảo đảm returns cho từng nhà đầu tư.","trap":"Investor protection khác investment loss insurance."},{"heading":"Transparency and issuer disclosure","body":"Disclosure rules làm giảm informational asymmetry; có standards về listing, accounting, material information và periodic filing. Excessive disclosure without quality không đủ bảo vệ.","trap":"Cơ quan quản lý không nhất thiết chứng nhận mọi business projection là đúng."},{"heading":"Competition and market integrity","body":"Competition policy, conduct supervision và conflict-management giúp tránh lạm dụng market power và abusive trading; coordination across markets giảm gaps.","trap":"Bảo vệ thị trường không có nghĩa cấm mọi speculative positions."},{"heading":"Systemic risk and infrastructure","body":"Margin/capital requirements, central clearing oversight và settlement safeguards hạn chế contagion, counterparty exposures và operational failures; rủi ro mới có thể phát sinh từ tập trung clearing.","trap":"Regulation giảm nhưng không xóa systemic risk."},{"heading":"Agency and externality problems","body":"Một số quy định giảm agency costs, moral hazard, externalities và public-goods problems; luôn tồn tại trade-off giữa costs of compliance, innovation và market access.","trap":"Không suy ra tăng regulation luôn làm thị trường hiệu quả hơn trong mọi hoàn cảnh."}],"formulas":[{"name":"Market regulation aims","expr":"Integrity + investor protection + orderly markets + reduced systemic/agency problems","meaning":"Không bao gồm bảo đảm investor returns.","conditions":"Different jurisdictions implement differently."},{"name":"Investor disclosure","expr":"Issuer disclosures → less information asymmetry (ceteris paribus)","meaning":"Transparency supports price discovery.","conditions":"Disclosure is not assurance of investment performance."}],"examples":[{"question_en":"A market regulator proposes guaranteeing investors at least 5% annual stock returns. Is this consistent with core securities regulation objectives?","steps_vi":["Stocks have uncertain returns and can suffer capital losses.","Regulation aims for disclosure, orderly trading and reduced abuse; it cannot eliminate market risk."],"answer":"No; guaranteed equity returns are not a core objective.","check":"Investor protection does not imply protection from all losses."}],"questions":[{"stem_en":"Which is the most appropriate objective of securities market regulation?","options":["Guaranteeing returns above T-bills","Reducing fraud and promoting fair, orderly trading","Eliminating every investment loss"],"correct":1,"why_vi":"Regulation hỗ trợ fairness/integrity chứ không guarantee returns.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Mandatory timely disclosure primarily aims to reduce:","options":["Information asymmetry","The need for investor analysis","All market volatility"],"correct":0,"why_vi":"Disclosure hỗ trợ thông tin bình đẳng hơn.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."},{"stem_en":"Rules requiring brokers to manage conflicts of interest primarily address:","options":["Agency problems","The time value of money","Stock split mechanics"],"correct":0,"why_vi":"Broker có incentives khác client; rules giúp giảm agency risk.","trap_vi":"Đọc kỹ yêu cầu: distinguishing function, claim, condition, and trading risk."}],"cards":[{"front_en":"Fair and orderly markets","back_vi":"Market regulation nhằm hạn chế fraud, manipulation, insider abuse và bảo vệ fair access/process; chú trọng public confidence. Không thể bảo đảm returns cho từng nhà đầu tư. Exam trap: Investor protection khác investment loss insurance."},{"front_en":"Transparency and issuer disclosure","back_vi":"Disclosure rules làm giảm informational asymmetry; có standards về listing, accounting, material information và periodic filing. Excessive disclosure without quality không đủ bảo vệ. Exam trap: Cơ quan quản lý không nhất thiết chứng nhận mọi business projection là đúng."},{"front_en":"Competition and market integrity","back_vi":"Competition policy, conduct supervision và conflict-management giúp tránh lạm dụng market power và abusive trading; coordination across markets giảm gaps. Exam trap: Bảo vệ thị trường không có nghĩa cấm mọi speculative positions."},{"front_en":"Systemic risk and infrastructure","back_vi":"Margin/capital requirements, central clearing oversight và settlement safeguards hạn chế contagion, counterparty exposures và operational failures; rủi ro mới có thể phát sinh từ tập trung clearing. Exam trap: Regulation giảm nhưng không xóa systemic risk."},{"front_en":"Agency and externality problems","back_vi":"Một số quy định giảm agency costs, moral hazard, externalities và public-goods problems; luôn tồn tại trade-off giữa costs of compliance, innovation và market access. Exam trap: Không suy ra tăng regulation luôn làm thị trường hiệu quả hơn trong mọi hoàn cảnh."}]}]},{"module_id":"CFA26-05-02","module_title":"Security Market Indexes","subject":"Equity Investments","version":"3.7","qa_status":"SOURCE_GROUNDED_DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT","language":"Vietnamese explanations, English stems and options","source_policy":"Original source-mapped study notes and exam questions; no copied questions","los":[{"id":"CFA26-05-02-LOS01","letter":"2.a","title_en":"Security Market Index Definition","outcome_en":"describe a security market index","overview_vi":"Tài liệu tự học theo phạm vi CFAI 2026; mỗi ví dụ và trắc nghiệm được tự biên soạn, không trích nguyên văn đề nguồn. Các giả định weighting, divisor và return convention phải được kiểm tra trước khi áp dụng.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5 LM2","pages":"91–130 (physical PDF, chapter-level range; exact subtopic mapping pending independent audit)"}],"sections":[{"heading":"Index as a portfolio measure","body":"Security market index theo dõi mức giá hoặc return của một tập securities có quy tắc thành phần/trọng số. Index value là đại lượng quy ước, không phải số tiền một investor sở hữu.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Base date and divisor","body":"Index level thường được chuẩn hóa với base value tại base date; divisor điều chỉnh các corporate actions để tránh index nhảy giả tạo. Index return mới phản ánh performance theo kỳ.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Investable versus broad market","body":"Một index có thể là benchmark mô tả thị trường hoặc cơ sở cho sản phẩm đầu tư. Investability, free float, transaction costs và liquidity là điều kiện thực tế để replicate.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Price versus total return","body":"Price index chỉ theo dõi price movements; total return index cộng tác động của cash distributions được tái đầu tư theo giả định. Đối với bonds còn có coupon interest.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."}],"formulas":[{"name":"Simple index level","expr":"Index level = aggregate weighted current value / adjusted divisor","meaning":"Chỉ có ý nghĩa sau khi xác định selection, weighting và divisor.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Base normalization","expr":"Index_t = Index_0 × (weighted portfolio value_t / weighted portfolio value_0)","meaning":"Cần cùng quy tắc và adjustment cho corporate actions.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."}],"examples":[{"question_en":"A two-stock portfolio value doubles from $5 million to $10 million, and the index base level is 200 with unchanged divisor. What is the index level?","steps_vi":["Giá trị danh mục chuẩn tăng theo tỷ lệ 10/5=2.","Index level =200×2."],"answer":"400","check":"Original numerical or conceptual case; independent academic review pending."}],"questions":[{"stem_en":"An equity index is best understood as:","options":["A rules-based measure of selected securities","A guarantee of investor performance","A corporation that owns all public securities"],"correct":0,"why_vi":"Index được xác định bằng selection/weighting/calculation rules.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."},{"stem_en":"Which distinction is most relevant when moving from price return to total return?","options":["Adding distributions such as dividends","Ignoring corporate actions entirely","Using nominal value instead of index level"],"correct":0,"why_vi":"Total return bao gồm distributions theo giả định index.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."}],"cards":[{"front_en":"Index as a portfolio measure","back_vi":"Security market index theo dõi mức giá hoặc return của một tập securities có quy tắc thành phần/trọng số. Index value là đại lượng quy ước, không phải số tiền một investor sở hữu."},{"front_en":"Base date and divisor","back_vi":"Index level thường được chuẩn hóa với base value tại base date; divisor điều chỉnh các corporate actions để tránh index nhảy giả tạo. Index return mới phản ánh performance theo kỳ."},{"front_en":"Investable versus broad market","back_vi":"Một index có thể là benchmark mô tả thị trường hoặc cơ sở cho sản phẩm đầu tư. Investability, free float, transaction costs và liquidity là điều kiện thực tế để replicate."},{"front_en":"Price versus total return","back_vi":"Price index chỉ theo dõi price movements; total return index cộng tác động của cash distributions được tái đầu tư theo giả định. Đối với bonds còn có coupon interest."}]},{"id":"CFA26-05-02-LOS02","letter":"2.b","title_en":"Index Value, Price Return, and Total Return","outcome_en":"calculate and interpret index value, price return, and total return","overview_vi":"Tài liệu tự học theo phạm vi CFAI 2026; mỗi ví dụ và trắc nghiệm được tự biên soạn, không trích nguyên văn đề nguồn. Các giả định weighting, divisor và return convention phải được kiểm tra trước khi áp dụng.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5 LM2","pages":"91–130 (physical PDF, chapter-level range; exact subtopic mapping pending independent audit)"}],"sections":[{"heading":"Single-period price return","body":"Price return = (ending index level − beginning index level) / beginning level, với divisor đã chỉnh phù hợp. Không cộng dividend vào numerator của price return.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Total return with cash flows","body":"Một kỳ: total return=(P1−P0+D)/P0 khi D là distributions attributable to comparable index units; chỉ số total return tích lũy theo compounding với reinvestment.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Multi-period linked index","body":"Chuỗi các single-period returns liên kết bằng ∏(1+R_t)−1; không cộng arithmetic returns khi kỳ biến động đáng kể.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Corporate action neutrality","body":"Stock split tự nó không tạo return kinh tế; index divisor hoặc share count được điều chỉnh. Special distributions có thể làm thay đổi convention, nên cần xác nhận rulebook.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."}],"formulas":[{"name":"Price return","expr":"R_P = I₁/I₀ − 1","meaning":"Tính từ index levels consistent với rulebook.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Total return","expr":"R_T = (I₁−I₀+cash distributions)/I₀","meaning":"Một kỳ, distributions phân bổ theo cùng unit.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Linked return","expr":"R_total = ∏ₜ(1+Rₜ) − 1","meaning":"Returns theo các kỳ liên tiếp được compounded.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."}],"examples":[{"question_en":"An index begins at 1,000, ends at 1,080, and pays distributions worth 20 index points. Compute price and total returns.","steps_vi":["Price return=(1,080−1,000)/1,000=8%.","Total return=(1,080−1,000+20)/1,000=10%."],"answer":"Price 8%; total 10%","check":"Original numerical or conceptual case; independent academic review pending."}],"questions":[{"stem_en":"An index rises from 250 to 265 with a 5-point cash distribution. Its total return is:","options":["6%","8%","10%"],"correct":1,"why_vi":"(265−250+5)/250=8%.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."},{"stem_en":"An index earns 10% in year one and loses 10% in year two. Its cumulative return is:","options":["0%","−1%","1%"],"correct":1,"why_vi":"(1.10)(0.90)−1=−1%.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."}],"cards":[{"front_en":"Single-period price return","back_vi":"Price return = (ending index level − beginning index level) / beginning level, với divisor đã chỉnh phù hợp. Không cộng dividend vào numerator của price return."},{"front_en":"Total return with cash flows","back_vi":"Một kỳ: total return=(P1−P0+D)/P0 khi D là distributions attributable to comparable index units; chỉ số total return tích lũy theo compounding với reinvestment."},{"front_en":"Multi-period linked index","back_vi":"Chuỗi các single-period returns liên kết bằng ∏(1+R_t)−1; không cộng arithmetic returns khi kỳ biến động đáng kể."},{"front_en":"Corporate action neutrality","back_vi":"Stock split tự nó không tạo return kinh tế; index divisor hoặc share count được điều chỉnh. Special distributions có thể làm thay đổi convention, nên cần xác nhận rulebook."}]},{"id":"CFA26-05-02-LOS03","letter":"2.c","title_en":"Index Construction and Management Choices","outcome_en":"describe choices and issues in index construction and management","overview_vi":"Tài liệu tự học theo phạm vi CFAI 2026; mỗi ví dụ và trắc nghiệm được tự biên soạn, không trích nguyên văn đề nguồn. Các giả định weighting, divisor và return convention phải được kiểm tra trước khi áp dụng.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5 LM2","pages":"91–130 (physical PDF, chapter-level range; exact subtopic mapping pending independent audit)"}],"sections":[{"heading":"Target market and selection","body":"Xác định geography, sector, asset class, market cap, float, liquidity và eligibility; broad market khác narrow sector/style index. Quy tắc lựa chọn phải tái lập được.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Weighting and maintenance","body":"Equal, price, market-cap, float-adjusted và fundamental weighting tạo exposures và turnover khác nhau. Rebalance, reconstitution và corporate-action rules tạo index governance.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Investability and costs","body":"Index có nhiều securities thanh khoản thấp hoặc free float nhỏ khó replicate, dẫn tới tracking error và chi phí. Index return công bố thường chưa trừ fees của ETF/fund.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Governance and methodology risk","body":"Calculation agent cần rulebook minh bạch, xử lý IPO/delistings/spin-offs, data quality và methodological changes; backtested histories không phải actual investable performance.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."}],"formulas":[{"name":"Eligible universe","expr":"Target market → eligibility screening → constituents → weights → divisor/maintenance","meaning":"Khung quy trình xây dựng index.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Index implementation gap","expr":"Fund return ≈ index return − fees − trading frictions ± tracking differences","meaning":"Quan hệ tham khảo, không phải accounting identity.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."}],"examples":[{"question_en":"A small-cap index includes securities with very low free float. What practical problem arises for an index-tracking fund?","steps_vi":["Trading enough shares may move prices and increase tracking costs.","Published index performance can differ from realized fund net returns."],"answer":"Higher replication costs and potentially tracking error","check":"Original numerical or conceptual case; independent academic review pending."}],"questions":[{"stem_en":"An investability screen primarily considers:","options":["Free float and liquidity","Only issuer founding dates","Only the par value of bonds"],"correct":0,"why_vi":"Free float và thanh khoản quyết định khả năng tái tạo danh mục.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."},{"stem_en":"An index fund may lag its benchmark because of:","options":["Management fees and transaction costs","Guaranteed arbitrage profit","A prohibition on rebalancing"],"correct":0,"why_vi":"Tracking difference bao gồm costs và friction.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."}],"cards":[{"front_en":"Target market and selection","back_vi":"Xác định geography, sector, asset class, market cap, float, liquidity và eligibility; broad market khác narrow sector/style index. Quy tắc lựa chọn phải tái lập được."},{"front_en":"Weighting and maintenance","back_vi":"Equal, price, market-cap, float-adjusted và fundamental weighting tạo exposures và turnover khác nhau. Rebalance, reconstitution và corporate-action rules tạo index governance."},{"front_en":"Investability and costs","back_vi":"Index có nhiều securities thanh khoản thấp hoặc free float nhỏ khó replicate, dẫn tới tracking error và chi phí. Index return công bố thường chưa trừ fees của ETF/fund."},{"front_en":"Governance and methodology risk","back_vi":"Calculation agent cần rulebook minh bạch, xử lý IPO/delistings/spin-offs, data quality và methodological changes; backtested histories không phải actual investable performance."}]},{"id":"CFA26-05-02-LOS04","letter":"2.d","title_en":"Index Weighting Methods","outcome_en":"compare different weighting methods used in index construction","overview_vi":"Tài liệu tự học theo phạm vi CFAI 2026; mỗi ví dụ và trắc nghiệm được tự biên soạn, không trích nguyên văn đề nguồn. Các giả định weighting, divisor và return convention phải được kiểm tra trước khi áp dụng.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5 LM2","pages":"91–130 (physical PDF, chapter-level range; exact subtopic mapping pending independent audit)"}],"sections":[{"heading":"Price weighting","body":"Price-weighted index weights ∝ share price, không phụ thuộc shares outstanding; high-priced shares ảnh hưởng hơn dù market cap nhỏ. Splits cần divisor adjustment để index không nhảy sai.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Equal weighting","body":"Mỗi security target cùng weight; price movement làm weights drift và cần rebalance, thường tăng exposure tương đối tới small caps so với market-cap index.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Market capitalization weighting","body":"Full-cap weights ∝ price×shares outstanding; float-adjusted chỉ dùng shares có thể giao dịch. Price rises thường tự làm weight tăng mà không cần rebalance cơ học.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Fundamental weighting","body":"Weights dựa trên fundamentals như revenue, cash flow, book value hay dividends; có thể tạo value/size tilts và turnover tùy quy tắc; không đơn giản là market cap weighting.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."}],"formulas":[{"name":"Price weight","expr":"wᵢ = Pᵢ / ΣPⱼ","meaning":"Ignore share count; adjust index divisor for splits.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Equal weight","expr":"wᵢ = 1/N","meaning":"At rebalance date; weights subsequently drift.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Cap weight","expr":"wᵢ = PᵢQᵢ / ΣPⱼQⱼ","meaning":"Q=shares outstanding or free-float shares as specified.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Fundamental weight","expr":"wᵢ = fundamentalᵢ / Σfundamentalⱼ","meaning":"Depends on selected positive fundamental metric.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."}],"examples":[{"question_en":"Stock A costs $20 with 10 million shares; Stock B costs $80 with 1 million shares. Compare price weights and cap weights.","steps_vi":["Price weights: A=20/(20+80)=20%, B=80%.","Market caps: A=$200m, B=$80m; cap weights A=200/280=71.43%, B=28.57%."],"answer":"Price: A 20%, B 80%. Cap: A 71.43%, B 28.57%.","check":"Original numerical or conceptual case; independent academic review pending."}],"questions":[{"stem_en":"A two-stock price-weighted index holds prices of $30 and $90. The higher-priced stock weight is:","options":["25%","50%","75%"],"correct":2,"why_vi":"90/(30+90)=75%.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."},{"stem_en":"Which method mechanically assigns the same target weight to every constituent?","options":["Equal weighting","Price weighting","Market-cap weighting"],"correct":0,"why_vi":"Equal weight=1/N tại ngày rebalance.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."}],"cards":[{"front_en":"Price weighting","back_vi":"Price-weighted index weights ∝ share price, không phụ thuộc shares outstanding; high-priced shares ảnh hưởng hơn dù market cap nhỏ. Splits cần divisor adjustment để index không nhảy sai."},{"front_en":"Equal weighting","back_vi":"Mỗi security target cùng weight; price movement làm weights drift và cần rebalance, thường tăng exposure tương đối tới small caps so với market-cap index."},{"front_en":"Market capitalization weighting","back_vi":"Full-cap weights ∝ price×shares outstanding; float-adjusted chỉ dùng shares có thể giao dịch. Price rises thường tự làm weight tăng mà không cần rebalance cơ học."},{"front_en":"Fundamental weighting","back_vi":"Weights dựa trên fundamentals như revenue, cash flow, book value hay dividends; có thể tạo value/size tilts và turnover tùy quy tắc; không đơn giản là market cap weighting."}]},{"id":"CFA26-05-02-LOS05","letter":"2.e","title_en":"Index Return by Weighting Method","outcome_en":"calculate and analyze index value and return under different weighting methods","overview_vi":"Tài liệu tự học theo phạm vi CFAI 2026; mỗi ví dụ và trắc nghiệm được tự biên soạn, không trích nguyên văn đề nguồn. Các giả định weighting, divisor và return convention phải được kiểm tra trước khi áp dụng.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5 LM2","pages":"91–130 (physical PDF, chapter-level range; exact subtopic mapping pending independent audit)"}],"sections":[{"heading":"Index portfolio return","body":"Với weights ở đầu kỳ, một kỳ index portfolio return thường là Σw_i R_i khi constituent returns phản ánh distributions nhất quán. Reweighting liên tục có thể thay đổi kết quả multi-period.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Price-weighted calculation","body":"Nếu không có corporate action, index level = Σprices/divisor. Split điều chỉnh divisor để level tại thời điểm split không đổi; price changes của shares high-price chi phối performance.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Cap-weight return","body":"Market-cap-weighted index return có thể tính bằng thay đổi aggregate market value khi share counts/issuances được xử lý phù hợp. Reconstitution/divisor adjustments ngăn flows và corporate actions thành fake returns.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Float and fundamentals","body":"Float-adjusted weights khác full-cap khi insiders nắm tỷ lệ lớn. Fundamental reweighting làm exposures drift giữa kỳ và đôi khi trade ngược momentum sau tăng giá.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Return contribution","body":"Cấu phần đóng góp của một constituent là beginning weight nhân return của constituent trong cùng kỳ.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."}],"formulas":[{"name":"Weighted single-period return","expr":"R_index = Σᵢ wᵢ,0 Rᵢ","meaning":"Beginning-of-period weights, comparable returns.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Price-weighted level","expr":"I = Σᵢ Pᵢ / divisor","meaning":"Corporate actions require divisor adjustment.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Contribution","expr":"cᵢ = wᵢ,0 × Rᵢ","meaning":"Sum of contributions for simple portfolio period.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."}],"examples":[{"question_en":"An index has two constituents with beginning weights 30% and 70%; their total returns are 10% and −2%. Find index total return.","steps_vi":["Return=0.30×0.10+0.70×(−0.02)=0.016.","Portfolio total return=1.6%."],"answer":"1.6%","check":"Original numerical or conceptual case; independent academic review pending."}],"questions":[{"stem_en":"A two-stock index has beginning weights 40% and 60% and returns 20% and −5%. Its return is:","options":["5%","8%","15%"],"correct":0,"why_vi":"0.4×20%+0.6×(−5%)=5%.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."},{"stem_en":"A security has 25% start weight and 12% period return. Its index return contribution is:","options":["3 percentage points","12 percentage points","48 percentage points"],"correct":0,"why_vi":"25%×12%=3 percentage points.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."}],"cards":[{"front_en":"Index portfolio return","back_vi":"Với weights ở đầu kỳ, một kỳ index portfolio return thường là Σw_i R_i khi constituent returns phản ánh distributions nhất quán. Reweighting liên tục có thể thay đổi kết quả multi-period."},{"front_en":"Price-weighted calculation","back_vi":"Nếu không có corporate action, index level = Σprices/divisor. Split điều chỉnh divisor để level tại thời điểm split không đổi; price changes của shares high-price chi phối performance."},{"front_en":"Cap-weight return","back_vi":"Market-cap-weighted index return có thể tính bằng thay đổi aggregate market value khi share counts/issuances được xử lý phù hợp. Reconstitution/divisor adjustments ngăn flows và corporate actions thành fake returns."},{"front_en":"Float and fundamentals","back_vi":"Float-adjusted weights khác full-cap khi insiders nắm tỷ lệ lớn. Fundamental reweighting làm exposures drift giữa kỳ và đôi khi trade ngược momentum sau tăng giá."},{"front_en":"Return contribution","back_vi":"Cấu phần đóng góp của một constituent là beginning weight nhân return của constituent trong cùng kỳ."}]},{"id":"CFA26-05-02-LOS06","letter":"2.f","title_en":"Rebalancing and Reconstitution","outcome_en":"describe index rebalancing and reconstitution","overview_vi":"Tài liệu tự học theo phạm vi CFAI 2026; mỗi ví dụ và trắc nghiệm được tự biên soạn, không trích nguyên văn đề nguồn. Các giả định weighting, divisor và return convention phải được kiểm tra trước khi áp dụng.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5 LM2","pages":"91–130 (physical PDF, chapter-level range; exact subtopic mapping pending independent audit)"}],"sections":[{"heading":"Rebalancing","body":"Rebalancing điều chỉnh weights của các constituents hiện hữu về target rule (ví dụ equal weight hàng quý). Việc này có thể tạo turnover và trading costs.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Reconstitution","body":"Reconstitution xét lại danh sách constituents theo eligibility rules: thêm/xóa firms, sector classifications, float/liquidity. Thành phần khác làm coverage và turnover thay đổi.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Corporate actions","body":"Stock splits, spinoffs, dividends, mergers, share issuance và delistings đòi hỏi adjustments; index không được coi split là economic gain.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Frequency trade-offs","body":"Thường xuyên rebalance tăng turnover/cost nhưng giữ exposures gần target; ít rebalance có weight drift. Quy tắc scheduled/event-driven khác nhau theo benchmark.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."}],"formulas":[{"name":"Rebalance","expr":"Adjust existing constituents to target weights","meaning":"Typically changes sizes of holdings.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Reconstitute","expr":"Add or remove constituents following eligibility review","meaning":"Changes index membership.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."}],"examples":[{"question_en":"An equal-weight index contains four stocks. After a rally, their weights become 40%, 25%, 20%, and 15%. What does rebalancing require?","steps_vi":["Target equal weight is 25% each.","Sell some of the first stock and buy underweight names; index membership does not necessarily change."],"answer":"Restore 25% each (conceptually)","check":"Original numerical or conceptual case; independent academic review pending."}],"questions":[{"stem_en":"Removing a company that no longer meets an index liquidity requirement is:","options":["Rebalancing","Reconstitution","A price return"],"correct":1,"why_vi":"Reconstitution thay đổi membership.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."},{"stem_en":"Restoring constituent weights to 20% each without adding/removing names is:","options":["Reconstitution","Rebalancing","Dividend reinvestment"],"correct":1,"why_vi":"Rebalancing thay đổi allocation trong danh sách hiện có.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."}],"cards":[{"front_en":"Rebalancing","back_vi":"Rebalancing điều chỉnh weights của các constituents hiện hữu về target rule (ví dụ equal weight hàng quý). Việc này có thể tạo turnover và trading costs."},{"front_en":"Reconstitution","back_vi":"Reconstitution xét lại danh sách constituents theo eligibility rules: thêm/xóa firms, sector classifications, float/liquidity. Thành phần khác làm coverage và turnover thay đổi."},{"front_en":"Corporate actions","back_vi":"Stock splits, spinoffs, dividends, mergers, share issuance và delistings đòi hỏi adjustments; index không được coi split là economic gain."},{"front_en":"Frequency trade-offs","back_vi":"Thường xuyên rebalance tăng turnover/cost nhưng giữ exposures gần target; ít rebalance có weight drift. Quy tắc scheduled/event-driven khác nhau theo benchmark."}]},{"id":"CFA26-05-02-LOS07","letter":"2.g","title_en":"Uses of Security Market Indexes","outcome_en":"describe uses of security market indexes","overview_vi":"Tài liệu tự học theo phạm vi CFAI 2026; mỗi ví dụ và trắc nghiệm được tự biên soạn, không trích nguyên văn đề nguồn. Các giả định weighting, divisor và return convention phải được kiểm tra trước khi áp dụng.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5 LM2","pages":"91–130 (physical PDF, chapter-level range; exact subtopic mapping pending independent audit)"}],"sections":[{"heading":"Market barometers","body":"Index tóm tắt sentiment và performance của segment; index narrow có thể lệch mạnh do sector/style bias.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Risk and return modeling","body":"Benchmarks làm proxy cho asset class/systematic return, beta estimation và capital market assumptions; quality phụ thuộc alignment với investable universe.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Performance benchmarks","body":"So sánh fund manager với index cùng mandate/risk. Outperformance trước fees không đồng nghĩa alpha; cần điều chỉnh risk, fees và holdings.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Underlying of investment products","body":"Index funds, ETFs, futures, swaps, options và structured products có thể tham chiếu index. Replication và licensing khác index calculation.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Asset allocation","body":"Broad market indexes giúp ước lượng risk/return/covariance của equity, fixed income và alternative asset classes; benchmark mismatch gây sai kết luận.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."}],"formulas":[{"name":"Active excess return","expr":"Excess return = portfolio return − benchmark return","meaning":"Cần benchmark phù hợp và cùng return convention.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Tracking difference","expr":"Fund return − referenced index return","meaning":"Negative due to fees and operational frictions in many cases.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."}],"examples":[{"question_en":"A manager invests exclusively in large-cap domestic stocks but is compared with a global small-cap index. Explain the flaw.","steps_vi":["Benchmark không khớp mandate, market risk và size/geographic exposures.","Excess returns có thể phản ánh factor exposure chứ không phải skill."],"answer":"Inappropriate benchmark comparison","check":"Original numerical or conceptual case; independent academic review pending."}],"questions":[{"stem_en":"A benchmark for a domestic large-cap manager should preferably:","options":["Match the mandate and risk exposures","Have the highest recent return","Exclude all declining stocks"],"correct":0,"why_vi":"Benchmark phù hợp cơ hội đầu tư và exposures.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."},{"stem_en":"An equity-index futures contract uses the index primarily as:","options":["A reference underlying","A guaranteed dividend","A private equity claim"],"correct":0,"why_vi":"Index là underlying/reference value cho derivative.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."}],"cards":[{"front_en":"Market barometers","back_vi":"Index tóm tắt sentiment và performance của segment; index narrow có thể lệch mạnh do sector/style bias."},{"front_en":"Risk and return modeling","back_vi":"Benchmarks làm proxy cho asset class/systematic return, beta estimation và capital market assumptions; quality phụ thuộc alignment với investable universe."},{"front_en":"Performance benchmarks","back_vi":"So sánh fund manager với index cùng mandate/risk. Outperformance trước fees không đồng nghĩa alpha; cần điều chỉnh risk, fees và holdings."},{"front_en":"Underlying of investment products","back_vi":"Index funds, ETFs, futures, swaps, options và structured products có thể tham chiếu index. Replication và licensing khác index calculation."},{"front_en":"Asset allocation","back_vi":"Broad market indexes giúp ước lượng risk/return/covariance của equity, fixed income và alternative asset classes; benchmark mismatch gây sai kết luận."}]},{"id":"CFA26-05-02-LOS08","letter":"2.h","title_en":"Types of Equity Indexes","outcome_en":"describe types of equity indexes","overview_vi":"Tài liệu tự học theo phạm vi CFAI 2026; mỗi ví dụ và trắc nghiệm được tự biên soạn, không trích nguyên văn đề nguồn. Các giả định weighting, divisor và return convention phải được kiểm tra trước khi áp dụng.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5 LM2","pages":"91–130 (physical PDF, chapter-level range; exact subtopic mapping pending independent audit)"}],"sections":[{"heading":"Broad-market and multi-market","body":"Broad-market indexes theo dõi phần lớn equity market của một quốc gia; multi-market/global indexes tổng hợp nhiều quốc gia, cần quy tắc currency, float và investability.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Sector and industry","body":"Sector indexes chỉ gồm companies thuộc sector/industry theo taxonomy; concentration risk cao dù có nhiều constituents cùng ngành.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Style indexes","body":"Growth/value, small/large, quality, momentum, dividend yield hoặc volatility style có quy tắc screening/weighting khác nhau, nhiều securities có thể nằm nhiều baskets.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Market cap tiers","body":"Large, mid, small-cap indices xác định qua market caps/float thresholds, không nhất thiết có một cut-off phổ quát; capitalizations biến động.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Total and price versions","body":"Cùng constituents có price-return và total-return series; benchmark choice nên khớp dividend reinvestment practice của portfolio.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."}],"formulas":[{"name":"Market cap segmentation","expr":"Large-cap vs mid-cap vs small-cap eligibility","meaning":"Threshold depends on index provider.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Sector index","expr":"Constituents screened by sector taxonomy","meaning":"Higher concentration than broad-market indexes.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."}],"examples":[{"question_en":"An index contains only publicly traded healthcare companies. Which equity index category best fits it?","steps_vi":["A sector index because membership is industry based.","It may have high idiosyncratic/sector risk even with many names."],"answer":"Sector index","check":"Original numerical or conceptual case; independent academic review pending."}],"questions":[{"stem_en":"An index tracking large value stocks is primarily a:","options":["Style index","Fixed income duration index","Direct real estate property index"],"correct":0,"why_vi":"Value là style/characteristics-based equity segment.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."},{"stem_en":"An index restricted to technology-sector firms is:","options":["Sector index","Global broad-market index","Treasury bill index"],"correct":0,"why_vi":"Selection dựa vào ngành technology.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."}],"cards":[{"front_en":"Broad-market and multi-market","back_vi":"Broad-market indexes theo dõi phần lớn equity market của một quốc gia; multi-market/global indexes tổng hợp nhiều quốc gia, cần quy tắc currency, float và investability."},{"front_en":"Sector and industry","back_vi":"Sector indexes chỉ gồm companies thuộc sector/industry theo taxonomy; concentration risk cao dù có nhiều constituents cùng ngành."},{"front_en":"Style indexes","back_vi":"Growth/value, small/large, quality, momentum, dividend yield hoặc volatility style có quy tắc screening/weighting khác nhau, nhiều securities có thể nằm nhiều baskets."},{"front_en":"Market cap tiers","back_vi":"Large, mid, small-cap indices xác định qua market caps/float thresholds, không nhất thiết có một cut-off phổ quát; capitalizations biến động."},{"front_en":"Total and price versions","back_vi":"Cùng constituents có price-return và total-return series; benchmark choice nên khớp dividend reinvestment practice của portfolio."}]},{"id":"CFA26-05-02-LOS09","letter":"2.i","title_en":"Comparing Security Market Index Types","outcome_en":"compare types of security market indexes","overview_vi":"Tài liệu tự học theo phạm vi CFAI 2026; mỗi ví dụ và trắc nghiệm được tự biên soạn, không trích nguyên văn đề nguồn. Các giả định weighting, divisor và return convention phải được kiểm tra trước khi áp dụng.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5 LM2","pages":"91–130 (physical PDF, chapter-level range; exact subtopic mapping pending independent audit)"}],"sections":[{"heading":"Asset class differences","body":"Equity indexes thường được xây bằng shares/mkt cap/float, fixed-income indexes phải xử lý issuance, maturity, coupon, duration, credit và bond liquidity; commodity indexes thường sử dụng futures rolls.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Diversification and concentration","body":"Broad vs focused indexes có tracking, risk, exposures khác nhau; cap weighting có thể concentration theo mega-caps, equal weighting có tilt về firms nhỏ hơn.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Return conventions","body":"Equity price vs total return, bond total return with interest/accrual và commodity futures excess vs total return khác nhau; không so sánh vô điều kiện.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Investability and replication","body":"Market liquidity và custody conventions khác nhau; obscure bond/hedge-fund indexes có non-synchronous pricing, selection/survivorship bias, stale marks.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Currencies and hedging","body":"Global index returns phụ thuộc currency choice; hedged vs unhedged versions có different returns due to FX, carry and hedging costs.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."}],"formulas":[{"name":"Common comparability dimensions","expr":"Universe + weighting + return type + currency + rebalancing + investability","meaning":"Trước khi so sánh bất kỳ hai indexes.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Currency choice","expr":"Local-currency return ≠ investor-currency return when FX moves","meaning":"Need convert or use hedged variant appropriately.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."}],"examples":[{"question_en":"Two indexes both rise 6%, but one is a price index and one a total-return index. Are performance measures directly comparable?","steps_vi":["Price index omits distributions; total-return index includes them.","Use consistent return conventions before concluding equal economic performance."],"answer":"No; return types differ","check":"Original numerical or conceptual case; independent academic review pending."}],"questions":[{"stem_en":"When comparing a bond index with an equity price index, analysts should first adjust for:","options":["Return conventions and asset class characteristics","Only the number of constituents","Only the index ticker length"],"correct":0,"why_vi":"Bond coupon accrual and equity dividends change comparability.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."},{"stem_en":"A global index reported in USD may differ from its local-currency return because of:","options":["Foreign exchange movements","The number of letters in currency code","Identical exchange rates worldwide"],"correct":0,"why_vi":"FX conversion changes investor-currency performance.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."}],"cards":[{"front_en":"Asset class differences","back_vi":"Equity indexes thường được xây bằng shares/mkt cap/float, fixed-income indexes phải xử lý issuance, maturity, coupon, duration, credit và bond liquidity; commodity indexes thường sử dụng futures rolls."},{"front_en":"Diversification and concentration","back_vi":"Broad vs focused indexes có tracking, risk, exposures khác nhau; cap weighting có thể concentration theo mega-caps, equal weighting có tilt về firms nhỏ hơn."},{"front_en":"Return conventions","back_vi":"Equity price vs total return, bond total return with interest/accrual và commodity futures excess vs total return khác nhau; không so sánh vô điều kiện."},{"front_en":"Investability and replication","back_vi":"Market liquidity và custody conventions khác nhau; obscure bond/hedge-fund indexes có non-synchronous pricing, selection/survivorship bias, stale marks."},{"front_en":"Currencies and hedging","back_vi":"Global index returns phụ thuộc currency choice; hedged vs unhedged versions có different returns due to FX, carry and hedging costs."}]},{"id":"CFA26-05-02-LOS10","letter":"2.j","title_en":"Fixed-Income Indexes","outcome_en":"describe types of fixed-income indexes","overview_vi":"Tài liệu tự học theo phạm vi CFAI 2026; mỗi ví dụ và trắc nghiệm được tự biên soạn, không trích nguyên văn đề nguồn. Các giả định weighting, divisor và return convention phải được kiểm tra trước khi áp dụng.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5 LM2","pages":"91–130 (physical PDF, chapter-level range; exact subtopic mapping pending independent audit)"}],"sections":[{"heading":"Government and corporate bond indexes","body":"Issuer category, maturity, credit quality và currency tạo segmentation; fixed income universe thay đổi liên tục do issuance, maturity và calls.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Duration and maturity","body":"Short/intermediate/long duration indexes khác interest-rate sensitivity; duration thường được dùng để mô tả risk hơn số lượng constituents.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Credit and liquidity","body":"Investment-grade vs high-yield, sovereign, agency, securitized indexes có credit risk khác nhau. Trái phiếu khó giao dịch gây valuation/rebalancing challenges.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Market-value weighting","body":"Debt outstanding lớn có thể dẫn đến higher index weight cho more indebted issuers, trái với equity fundamentals; cap weighting cần xử lý bond pricing/accrued interest.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Bond total return","body":"Bond index return gồm price change, coupon income và accrual/reinvestment convention; yield level không bằng realized holding-period return.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."}],"formulas":[{"name":"Bond index weight","expr":"wᵢ ∝ market value of eligible bonds outstanding","meaning":"Implementation subject to eligibility and valuation.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Bond total return","expr":"R ≈ (P_end − P_begin + coupon income)/P_begin","meaning":"Accrued interest and reinvestment conventions matter.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."}],"examples":[{"question_en":"A bond index holds both short-duration government bonds and long-duration corporate bonds. Which subgroup is generally more sensitive to a parallel yield change?","steps_vi":["All else equal, the group with longer duration has larger approximate price sensitivity.","Credit spreads and convexity can modify realized returns."],"answer":"Longer-duration group","check":"Original numerical or conceptual case; independent academic review pending."}],"questions":[{"stem_en":"A bond index restricted to issuers below investment grade is a:","options":["High-yield bond index","Large-cap equity index","Commodity spot index"],"correct":0,"why_vi":"High yield được phân loại theo credit rating.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."},{"stem_en":"A longer-duration bond index generally has:","options":["Higher interest-rate sensitivity","No interest-rate sensitivity","Guaranteed higher realized returns"],"correct":0,"why_vi":"Modified duration xấp xỉ sensitivity đối với yield changes.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."}],"cards":[{"front_en":"Government and corporate bond indexes","back_vi":"Issuer category, maturity, credit quality và currency tạo segmentation; fixed income universe thay đổi liên tục do issuance, maturity và calls."},{"front_en":"Duration and maturity","back_vi":"Short/intermediate/long duration indexes khác interest-rate sensitivity; duration thường được dùng để mô tả risk hơn số lượng constituents."},{"front_en":"Credit and liquidity","back_vi":"Investment-grade vs high-yield, sovereign, agency, securitized indexes có credit risk khác nhau. Trái phiếu khó giao dịch gây valuation/rebalancing challenges."},{"front_en":"Market-value weighting","back_vi":"Debt outstanding lớn có thể dẫn đến higher index weight cho more indebted issuers, trái với equity fundamentals; cap weighting cần xử lý bond pricing/accrued interest."},{"front_en":"Bond total return","back_vi":"Bond index return gồm price change, coupon income và accrual/reinvestment convention; yield level không bằng realized holding-period return."}]},{"id":"CFA26-05-02-LOS11","letter":"2.k","title_en":"Indexes for Alternative Investments","outcome_en":"describe indexes representing alternative investments","overview_vi":"Tài liệu tự học theo phạm vi CFAI 2026; mỗi ví dụ và trắc nghiệm được tự biên soạn, không trích nguyên văn đề nguồn. Các giả định weighting, divisor và return convention phải được kiểm tra trước khi áp dụng.","source":[{"id":"CFA Institute CFA Level I Curriculum 2026 — Equity Investments Volume 5 LM2","pages":"91–130 (physical PDF, chapter-level range; exact subtopic mapping pending independent audit)"}],"sections":[{"heading":"Commodity futures indexes","body":"Thường dựa trên futures chứ không nhất thiết nắm physical commodities; return gồm spot/price movement, roll yield và collateral return tùy benchmark methodology.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Real estate and REIT indexes","body":"Listed REIT indexes có high liquidity và thường giống stock-market behavior hơn appraisal-based private property indexes; direct-property indexes có stale/appraisal smoothing risks.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Hedge fund indexes","body":"Reported/indexed hedge fund returns có reporting, survivorship, backfill và selection biases; nhiều funds không bắt buộc báo cáo và exposures có thể biến đổi.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Private markets and appraisal lag","body":"Private equity/real estate indexes có infrequent valuations và illiquidity; điều này có thể artificially reduce measured volatility/correlation trong dữ liệu được báo cáo.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."},{"heading":"Benchmark choice","body":"Index availability, investability, strategy fit và net/gross reporting conventions quyết định benchmark phù hợp; alternative indexes có thể không replicated dễ dàng.","trap":"Bẫy thi: Luôn xác định rõ methodology, universe, return convention và giả định."}],"formulas":[{"name":"Commodity futures return components","expr":"Futures index return ≈ spot component + roll component + collateral yield (per methodology)","meaning":"Components are conceptual; signs and benchmark conventions matter.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."},{"name":"Hedge fund bias checklist","expr":"Survivorship + backfill + voluntary reporting + stale pricing","meaning":"Do not treat reported Sharpe ratio as directly comparable without adjustments.","conditions":"Khung/công thức chỉ áp dụng theo ghi chú ngay trong mục."}],"examples":[{"question_en":"A hedge fund index is constructed using only funds that still report returns. What is the principal concern?","steps_vi":["Survivorship bias, because failed funds may be missing.","The reported average may overstate representative historical returns."],"answer":"Survivorship bias","check":"Original numerical or conceptual case; independent academic review pending."}],"questions":[{"stem_en":"An index based on privately appraised property values may exhibit:","options":["Smoothing and delayed recognition of market movements","Perfect daily liquidity","Real-time transaction prices for every property"],"correct":0,"why_vi":"Appraisal-based valuations có thể làm volatility đo thấp.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."},{"stem_en":"A collateralized commodity futures index total return can differ from a futures excess return due to:","options":["Collateral interest earned","Voting rights in commodity producers","Corporate stock dividends"],"correct":0,"why_vi":"Collateral yield có thể cộng vào total return theo index methodology.","trap_vi":"Kiểm tra return type, weighting rule và index methodology."}],"cards":[{"front_en":"Commodity futures indexes","back_vi":"Thường dựa trên futures chứ không nhất thiết nắm physical commodities; return gồm spot/price movement, roll yield và collateral return tùy benchmark methodology."},{"front_en":"Real estate and REIT indexes","back_vi":"Listed REIT indexes có high liquidity và thường giống stock-market behavior hơn appraisal-based private property indexes; direct-property indexes có stale/appraisal smoothing risks."},{"front_en":"Hedge fund indexes","back_vi":"Reported/indexed hedge fund returns có reporting, survivorship, backfill và selection biases; nhiều funds không bắt buộc báo cáo và exposures có thể biến đổi."},{"front_en":"Private markets and appraisal lag","back_vi":"Private equity/real estate indexes có infrequent valuations và illiquidity; điều này có thể artificially reduce measured volatility/correlation trong dữ liệu được báo cáo."},{"front_en":"Benchmark choice","back_vi":"Index availability, investability, strategy fit và net/gross reporting conventions quyết định benchmark phù hợp; alternative indexes có thể không replicated dễ dàng."}]}]},{"module_id":"CFA26-05-03","module_title":"Market Efficiency","subject":"Equity Investments","version":"3.8","qa_status":"SOURCE_GROUNDED_DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT","language":"Vietnamese explanatory notes; original English question stems and options","source_policy":"Original bilingual paraphrased lessons and original practice based on CFAI 2026 Equity Volume 5, module 3; primary PDF directly inspected; additional line-by-line editorial checks pending","los":[{"id":"CFA26-05-03-LOS01","letter":"3.a","title_en":"Market Efficiency and Why It Matters","outcome_en":"describe market efficiency and related concepts and their relevance to investment work","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM3 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM3 — Market Efficiency","pages":"official outcomes at physical PDF p133; teaching chapter physical pp133–168"}],"sections":[{"heading":"Informational efficiency","body":"Thị trường hiệu quả về thông tin khi giá phản ánh nhanh và đủ thông tin thuộc tập thông tin đang xét. Điều này không có nghĩa mỗi giao dịch đều đúng giá trị nội tại hoặc giá không biến động.","trap":"Đừng nhầm informational efficiency với operational efficiency hay certainty về cash flows."},{"heading":"Competitive price discovery","body":"Khi analyst cạnh tranh tìm và giao dịch dựa trên thông tin, lợi ích dự kiến của một tín hiệu sẽ được phản ánh vào giá. Information production có chi phí nên hiệu quả là khái niệm về lợi nhuận sau chi phí và điều chỉnh rủi ro.","trap":"Giá mới vẫn thay đổi khi news mới xuất hiện."},{"heading":"Fair risk-adjusted returns","body":"Trong thị trường đủ hiệu quả, không thể đều đặn tạo abnormal risk-adjusted return sau costs chỉ nhờ thông tin đã nằm trong giá. Nhà đầu tư vẫn có thể nhận positive expected return do chịu systematic risk.","trap":"EMH không dự đoán cổ phiếu có expected return bằng 0."},{"heading":"Random changes versus randomness","body":"Nếu tin mới khó dự đoán, price changes do news có thể khó dự báo; đây là lập luận, không phải khẳng định tất cả prices luôn random walk hoàn hảo. Expected return có thể thay đổi theo risk premia.","trap":"Không dùng chỉ một chuỗi giá ngắn để chứng minh EMH."},{"heading":"Market efficiency in practice","body":"Market efficiency quyết định giá trị của research, cách đặt benchmark và quyết định active/passive. Đánh giá kết quả active fund nên xét đúng benchmark, risk factors, fees và sample length.","trap":"Một năm outperformance chưa xác nhận kỹ năng tạo alpha."}],"formulas":[{"name":"Net abnormal return","expr":"alpha_net ≈ portfolio return − risk-adjusted benchmark return − incremental trading and research costs","meaning":"Chỉ số sơ bộ để đánh giá lợi ích của phân tích vượt thông tin công khai.","conditions":"Benchmark phải tương thích risk exposure, thời gian và cash flow."},{"name":"Information-price feedback","expr":"New relevant information → revised expectations → trading → updated prices","meaning":"Khung logic hình thành giá khi có news.","conditions":"Có thể có delays hoặc limits to arbitrage."}],"examples":[{"question_en":"An active manager beats an index by 2%, incurs 1.4% incremental costs, and has 0.8% additional factor-related expected return. Estimate simple net abnormal return.","steps_vi":["Chênh lệch gross so với benchmark = 2.0%.","Loại 0.8% do chấp nhận thêm rủi ro và 1.4% incremental costs.","Net risk-adjusted alpha ≈ 2.0 − 0.8 − 1.4 = −0.2%."],"answer":"−0.2%","check":"Illustration assumes additive percentage-point adjustments; not a full multifactor attribution."}],"questions":[{"stem_en":"A market that incorporates public announcements rapidly primarily demonstrates which feature?","options":["Guaranteed price stability","Informational efficiency","Elimination of all risk"],"correct":1,"why_vi":"Thông tin được phản ánh nhanh; volatility vẫn xuất hiện.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Which return can investors still rationally expect in an efficient market?","options":["Certain abnormal returns using public data","Zero nominal return","A fair return for bearing priced risk"],"correct":2,"why_vi":"Market efficiency không xóa risk premium.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A fund outperforms a benchmark before fees but underperforms after fees. The most defensible conclusion is that:","options":["Gross outperformance alone is insufficient evidence of net investor value","Market prices must be manipulated","Market efficiency requires identical returns for every fund"],"correct":0,"why_vi":"Costs là điều kiện quan trọng của investor outcomes.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Informational efficiency","back_vi":"Thị trường hiệu quả về thông tin khi giá phản ánh nhanh và đủ thông tin thuộc tập thông tin đang xét. Điều này không có nghĩa mỗi giao dịch đều đúng giá trị nội tại hoặc giá không biến động. Exam trap: Đừng nhầm informational efficiency với operational efficiency hay certainty về cash flows."},{"front_en":"Competitive price discovery","back_vi":"Khi analyst cạnh tranh tìm và giao dịch dựa trên thông tin, lợi ích dự kiến của một tín hiệu sẽ được phản ánh vào giá. Information production có chi phí nên hiệu quả là khái niệm về lợi nhuận sau chi phí và điều chỉnh rủi ro. Exam trap: Giá mới vẫn thay đổi khi news mới xuất hiện."},{"front_en":"Fair risk-adjusted returns","back_vi":"Trong thị trường đủ hiệu quả, không thể đều đặn tạo abnormal risk-adjusted return sau costs chỉ nhờ thông tin đã nằm trong giá. Nhà đầu tư vẫn có thể nhận positive expected return do chịu systematic risk. Exam trap: EMH không dự đoán cổ phiếu có expected return bằng 0."},{"front_en":"Random changes versus randomness","back_vi":"Nếu tin mới khó dự đoán, price changes do news có thể khó dự báo; đây là lập luận, không phải khẳng định tất cả prices luôn random walk hoàn hảo. Expected return có thể thay đổi theo risk premia. Exam trap: Không dùng chỉ một chuỗi giá ngắn để chứng minh EMH."},{"front_en":"Market efficiency in practice","back_vi":"Market efficiency quyết định giá trị của research, cách đặt benchmark và quyết định active/passive. Đánh giá kết quả active fund nên xét đúng benchmark, risk factors, fees và sample length. Exam trap: Một năm outperformance chưa xác nhận kỹ năng tạo alpha."}]},{"id":"CFA26-05-03-LOS02","letter":"3.b","title_en":"Market Value Versus Intrinsic Value","outcome_en":"contrast market value and intrinsic value in equity analysis","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM3 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM3 — Market Efficiency","pages":"official outcomes at physical PDF p133; teaching chapter physical pp133–168"}],"sections":[{"heading":"Market value","body":"Giá thị trường phản ánh giá giao dịch quan sát được nhân với số lượng nếu quy đổi sang market capitalization. Giá có thể phản ánh supply-demand, information, discount rates và sentiment tại thời điểm.","trap":"Market capitalization không phải enterprise value."},{"heading":"Intrinsic value","body":"Intrinsic value là ước tính hiện tại của lợi ích kinh tế tương lai dựa trên cash-flow forecasts và required returns, hoặc mô hình phù hợp khác. Nó là estimate có sai số chứ không phải số thật biết chắc.","trap":"Các analyst có thể cùng hợp lý nhưng định giá khác nhau."},{"heading":"Mispricing terminology","body":"Nếu intrinsic value estimate lớn hơn market price, theo mô hình đó security bị undervalued; thấp hơn price thì overvalued. Để hành động cần xét estimation error và transaction costs.","trap":"Không kết luận chắc có mispricing chỉ từ một điểm ước tính."},{"heading":"Convergence and timing risk","body":"Khoảng chênh price–estimated value có thể duy trì lâu, hoặc intrinsic value thay đổi khi facts thay đổi. Short positions có financing, squeeze và liquidity risk.","trap":"Phân tích đúng chưa đảm bảo trade sinh lời ngay."},{"heading":"Valuation uncertainty","body":"Sensitivity của growth, margins, discount rate và terminal assumptions có thể lớn hơn spread nhỏ giữa estimate và price. Dùng ranges và scenarios để đo mức độ tin cậy.","trap":"Đừng gọi chênh 1% là bargain nếu model error ±20%."}],"formulas":[{"name":"Estimated valuation gap","expr":"(V_est − P_market) / P_market","meaning":"Tỷ lệ chênh giá trị nội tại ước tính so với giá thị trường.","conditions":"Không phải lợi nhuận chắc chắn thực hiện được."},{"name":"Market capitalization","expr":"Market cap = share price × shares outstanding","meaning":"Giá trị vốn chủ sở hữu theo giá thị trường.","conditions":"Chú ý diluted shares và share classes nếu có."}],"examples":[{"question_en":"A stock trades at $40, while an analyst estimates intrinsic value at $48. Calculate the valuation gap relative to market price.","steps_vi":["Estimated gap = (48−40)/40 = 0.20.","Kết luận theo model: potentially undervalued by 20%; cần kiểm tra độ bất định và costs."],"answer":"20% estimated upside","check":"Model-estimated upside is not a guaranteed realized return."}],"questions":[{"stem_en":"An intrinsic value estimate is best characterized as:","options":["A guaranteed future selling price","The most recent trade price by definition","A model-dependent estimate using assumptions"],"correct":2,"why_vi":"Giá trị nội tại dựa assumptions, khác market price quan sát.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A share sells for $75 and is estimated to be worth $60. Relative to the estimate, it appears:","options":["Overvalued","Undervalued","Fairly valued"],"correct":0,"why_vi":"P > V_est nên overvalued theo model.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Two analysts assign different intrinsic values to the same company mainly because they may:","options":["Observe different current exchange prices for the same trade","Use different cash-flow and required-return assumptions","Be required to forecast identical dividends"],"correct":1,"why_vi":"Model input uncertainty có thể tạo kết quả khác.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Market value","back_vi":"Giá thị trường phản ánh giá giao dịch quan sát được nhân với số lượng nếu quy đổi sang market capitalization. Giá có thể phản ánh supply-demand, information, discount rates và sentiment tại thời điểm. Exam trap: Market capitalization không phải enterprise value."},{"front_en":"Intrinsic value","back_vi":"Intrinsic value là ước tính hiện tại của lợi ích kinh tế tương lai dựa trên cash-flow forecasts và required returns, hoặc mô hình phù hợp khác. Nó là estimate có sai số chứ không phải số thật biết chắc. Exam trap: Các analyst có thể cùng hợp lý nhưng định giá khác nhau."},{"front_en":"Mispricing terminology","back_vi":"Nếu intrinsic value estimate lớn hơn market price, theo mô hình đó security bị undervalued; thấp hơn price thì overvalued. Để hành động cần xét estimation error và transaction costs. Exam trap: Không kết luận chắc có mispricing chỉ từ một điểm ước tính."},{"front_en":"Convergence and timing risk","back_vi":"Khoảng chênh price–estimated value có thể duy trì lâu, hoặc intrinsic value thay đổi khi facts thay đổi. Short positions có financing, squeeze và liquidity risk. Exam trap: Phân tích đúng chưa đảm bảo trade sinh lời ngay."},{"front_en":"Valuation uncertainty","back_vi":"Sensitivity của growth, margins, discount rate và terminal assumptions có thể lớn hơn spread nhỏ giữa estimate và price. Dùng ranges và scenarios để đo mức độ tin cậy. Exam trap: Đừng gọi chênh 1% là bargain nếu model error ±20%."}]},{"id":"CFA26-05-03-LOS03","letter":"3.c","title_en":"Drivers of Market Efficiency","outcome_en":"explain the factors that affect a market’s efficiency","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM3 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM3 — Market Efficiency","pages":"official outcomes at physical PDF p133; teaching chapter physical pp133–168"}],"sections":[{"heading":"Breadth of participation","body":"Nhiều investor và analyst độc lập giúp thông tin được tìm kiếm và phản ánh vào giá. Tuy nhiên số lượng đông chưa bảo đảm mọi thông tin được xử lý đúng.","trap":"Đừng xem volume cao là bằng chứng đủ của efficiency."},{"heading":"Access to information","body":"Công bố kịp thời, đáng tin và rẻ hơn giảm information asymmetry. Thông tin bị giới hạn, kế toán thiếu minh bạch hoặc processing khó khiến chênh lệch giá tồn tại.","trap":"Information availability khác information interpretation."},{"heading":"Trading limitations","body":"Short-sale restrictions, transaction costs, price limits, funding constraints và market impact ngăn arbitrage loại mispricing. Risk of interim divergence còn làm trader thận trọng.","trap":"Mispricing không mặc nhiên tạo riskless arbitrage."},{"heading":"Liquidity and market design","body":"Spreads nhỏ, depth tốt, clearing đáng tin và trading infrastructure giúp phản ứng với thông tin; stress periods có thể làm liquidity biến mất.","trap":"Operational liquidity là điều kiện hỗ trợ chứ không tương đương informational efficiency."},{"heading":"Incentives and competition","body":"Phí research và competition quyết định ai sản xuất thông tin. Nếu mọi người miễn phí hưởng hiệu quả giá, incentive thu thập thông tin có thể yếu; efficiency cần hoạt động thông tin.","trap":"Không suy luận mọi active research vô dụng."}],"formulas":[{"name":"Arbitrage profit after friction","expr":"Net opportunity = expected mispricing convergence gain − research − trading − financing costs","meaning":"Quyết định liệu có động cơ điều chỉnh giá.","conditions":"Convergence uncertainty và downside risk cần được xét riêng."},{"name":"Efficiency channels","expr":"More informed competition + accessible disclosures + fewer trading barriers → generally faster incorporation","meaning":"Quan hệ định tính ceteris paribus.","conditions":"Không phải định luật tuyệt đối."}],"examples":[{"question_en":"A security seems 3% underpriced, but the required round-trip costs are 4%. What is the simplest implication?","steps_vi":["Expected gross mispricing gain ≈ 3%.","After 4% trading frictions, the apparent net gain is negative even before uncertainty."],"answer":"The apparent opportunity is not profitable on these assumptions.","check":"Risk and timing can make the outcome worse."}],"questions":[{"stem_en":"Which feature most directly facilitates rapid incorporation of new information into prices?","options":["Broad analyst coverage and accessible disclosures","Restrictions on every short sale","Very high unavoidable transaction costs"],"correct":0,"why_vi":"Information competition làm cập nhật prices tốt hơn.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A mispricing may survive because arbitrageurs face:","options":["Unlimited risk-free capital","Funding and short-selling constraints","Guaranteed convergence dates"],"correct":1,"why_vi":"Limits to arbitrage có thể ngăn chỉnh giá.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A bid–ask spread most directly measures:","options":["The accuracy of intrinsic valuation","The certainty of future earnings","One aspect of trading friction"],"correct":2,"why_vi":"Spread liên quan trading cost, không chứng minh intrinsic price đúng.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Breadth of participation","back_vi":"Nhiều investor và analyst độc lập giúp thông tin được tìm kiếm và phản ánh vào giá. Tuy nhiên số lượng đông chưa bảo đảm mọi thông tin được xử lý đúng. Exam trap: Đừng xem volume cao là bằng chứng đủ của efficiency."},{"front_en":"Access to information","back_vi":"Công bố kịp thời, đáng tin và rẻ hơn giảm information asymmetry. Thông tin bị giới hạn, kế toán thiếu minh bạch hoặc processing khó khiến chênh lệch giá tồn tại. Exam trap: Information availability khác information interpretation."},{"front_en":"Trading limitations","back_vi":"Short-sale restrictions, transaction costs, price limits, funding constraints và market impact ngăn arbitrage loại mispricing. Risk of interim divergence còn làm trader thận trọng. Exam trap: Mispricing không mặc nhiên tạo riskless arbitrage."},{"front_en":"Liquidity and market design","back_vi":"Spreads nhỏ, depth tốt, clearing đáng tin và trading infrastructure giúp phản ứng với thông tin; stress periods có thể làm liquidity biến mất. Exam trap: Operational liquidity là điều kiện hỗ trợ chứ không tương đương informational efficiency."},{"front_en":"Incentives and competition","back_vi":"Phí research và competition quyết định ai sản xuất thông tin. Nếu mọi người miễn phí hưởng hiệu quả giá, incentive thu thập thông tin có thể yếu; efficiency cần hoạt động thông tin. Exam trap: Không suy luận mọi active research vô dụng."}]},{"id":"CFA26-05-03-LOS04","letter":"3.d","title_en":"Forms of Market Efficiency","outcome_en":"contrast weak, semi-strong, and strong forms of informational efficiency","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM3 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM3 — Market Efficiency","pages":"official outcomes at physical PDF p133; teaching chapter physical pp133–168"}],"sections":[{"heading":"Weak form","body":"Price phản ánh toàn bộ historical market data như prices, volumes và return patterns. Nếu weak-form hold, việc dùng riêng price history không tạo abnormal risk-adjusted returns bền vững sau costs.","trap":"Không suy ra public fundamental data đã phản ánh từ weak form."},{"heading":"Semi-strong form","body":"Giá phản ánh all publicly available information, gồm market history, statements, public announcements và economic releases; giá phản ứng nhanh với tin mới.","trap":"Semi-strong cũng bao gồm weak-form information."},{"heading":"Strong form","body":"Giá phản ánh cả public và private information, kể cả material nonpublic information. Đây là giả thuyết nghiêm ngặt, thực tế insider advantage có thể tồn tại.","trap":"Strong form không cho phép insider trading theo luật; là claim về prices, không về legality."},{"heading":"Nested information sets","body":"Strong ⇒ semi-strong ⇒ weak, nhưng chiều ngược lại không bắt buộc. Một test phản bác strong không tự động bác bỏ weak hoặc semi-strong.","trap":"Đừng đọc ba dạng như ba loại thị trường độc lập."},{"heading":"Evidence and tests","body":"Weak-form có thể kiểm tra serial correlation/runs; semi-strong qua event studies; strong qua lợi nhuận groups có private information. Joint-hypothesis problem: kiểm định luôn phụ thuộc risk model.","trap":"Abnormal return tìm thấy có thể do sai benchmark, data bias hoặc costs."}],"formulas":[{"name":"Information nesting","expr":"I_weak ⊂ I_semi-strong ⊂ I_strong","meaning":"Các tập thông tin: historical market data; all public; public and private.","conditions":"Dấu bao hàm không nói mọi thị trường đạt strong form."},{"name":"Event-study abnormal return","expr":"AR_t = actual return_t − expected model return_t","meaning":"Đánh giá phản ứng giá quanh public announcement.","conditions":"Phụ thuộc benchmark and event-window design."}],"examples":[{"question_en":"A company unexpectedly releases material public information at noon. Prices adjust almost immediately. Which market-efficiency form does that most directly support?","steps_vi":["Public announcement thuộc semi-strong information set.","Điều chỉnh gần lập tức cho thấy information incorporation tốt với public news."],"answer":"Evidence consistent with semi-strong efficiency","check":"One event cannot definitively establish the hypothesis."}],"questions":[{"stem_en":"Which information set is incorporated under weak-form efficiency?","options":["Every unpublished merger negotiation","Past prices and trading volume","All public financial statements necessarily"],"correct":1,"why_vi":"Weak-form giới hạn market history.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Semi-strong efficiency includes:","options":["Only private management forecasts","Only last month’s prices, excluding public filings","Public announcements and historical market data"],"correct":2,"why_vi":"Tập public rộng hơn historical price data.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A market that is strong-form efficient must also satisfy:","options":["Semi-strong and weak forms","Only weak form, not semi-strong","Neither of the other forms"],"correct":0,"why_vi":"Strong encompasses all smaller information sets.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Weak form","back_vi":"Price phản ánh toàn bộ historical market data như prices, volumes và return patterns. Nếu weak-form hold, việc dùng riêng price history không tạo abnormal risk-adjusted returns bền vững sau costs. Exam trap: Không suy ra public fundamental data đã phản ánh từ weak form."},{"front_en":"Semi-strong form","back_vi":"Giá phản ánh all publicly available information, gồm market history, statements, public announcements và economic releases; giá phản ứng nhanh với tin mới. Exam trap: Semi-strong cũng bao gồm weak-form information."},{"front_en":"Strong form","back_vi":"Giá phản ánh cả public và private information, kể cả material nonpublic information. Đây là giả thuyết nghiêm ngặt, thực tế insider advantage có thể tồn tại. Exam trap: Strong form không cho phép insider trading theo luật; là claim về prices, không về legality."},{"front_en":"Nested information sets","back_vi":"Strong ⇒ semi-strong ⇒ weak, nhưng chiều ngược lại không bắt buộc. Một test phản bác strong không tự động bác bỏ weak hoặc semi-strong. Exam trap: Đừng đọc ba dạng như ba loại thị trường độc lập."},{"front_en":"Evidence and tests","back_vi":"Weak-form có thể kiểm tra serial correlation/runs; semi-strong qua event studies; strong qua lợi nhuận groups có private information. Joint-hypothesis problem: kiểm định luôn phụ thuộc risk model. Exam trap: Abnormal return tìm thấy có thể do sai benchmark, data bias hoặc costs."}]},{"id":"CFA26-05-03-LOS05","letter":"3.e","title_en":"Implications for Analysis and Portfolio Choice","outcome_en":"explain implications of market efficiency for technical, fundamental, active, and passive management","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM3 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM3 — Market Efficiency","pages":"official outcomes at physical PDF p133; teaching chapter physical pp133–168"}],"sections":[{"heading":"Technical analysis","body":"Chart trends, support/resistance, past volume và momentum signals chỉ dựa trên history. Nếu weak-form hoàn toàn hiệu quả, phương pháp chỉ dùng historical market data không đem lại net risk-adjusted abnormal return ổn định.","trap":"Trading profits trước costs chưa chứng minh alpha."},{"heading":"Fundamental analysis","body":"Estimate cash flows, cost of capital, issuer quality dùng public financial/economic data. Semi-strong form đặt nghi vấn về lợi thế nhất quán chỉ dựa dữ liệu công khai đã được xử lý vào giá.","trap":"Fundamental work vẫn hữu ích cho risk control, governance và asset allocation."},{"heading":"Active management","body":"Active nhằm khai thác mispricing hoặc skill trong forecasting, trading, portfolio construction; phải so benchmark risk-adjusted và net of fees. Quy mô quỹ, capacity và market impact làm alpha khó scale.","trap":"Một active manager có thể outperform do luck hoặc factor tilts."},{"heading":"Passive management","body":"Passive tracking index tiết kiệm research/trading costs, đem market exposure minh bạch; vẫn chịu market risk, tracking error, index concentration và fees.","trap":"Passive không phải risk-free, không chắc outperform từng active manager."},{"heading":"Market efficiency by segment","body":"Emerging, thinly traded hoặc complex assets có thể ít được phân tích hơn; nhưng illiquidity/implementation costs có thể triệt tiêu apparent arbitrage. Chọn chiến lược dựa evidence và constraints cụ thể.","trap":"Đừng mặc định less efficient = easier net profits."}],"formulas":[{"name":"Active net value-added","expr":"Net alpha ≈ realized active return − risk-adjusted benchmark return − active costs","meaning":"Khung đánh giá performance sau chi phí.","conditions":"Cần đủ horizon, factor controls, survivorship bias checks."},{"name":"Passive tracking difference","expr":"Fund net return − target index return","meaning":"Chênh lệch do fees, taxes, sampling và securities lending.","conditions":"Tracking difference khác tracking error variability."}],"examples":[{"question_en":"A passive index product has a 0.10% expense ratio and before-fee tracking is perfect. What is its approximate annual return relative to the benchmark?","steps_vi":["Giả định không có other frictions hoặc offsetting securities lending income.","Chi phí trực tiếp làm fund net return kém index khoảng 0.10 percentage point."],"answer":"Approximately 0.10 percentage point lower","check":"Performance of a real fund can differ because of cash flows, taxes and tracking methods."}],"questions":[{"stem_en":"Under semi-strong efficiency, an investor is least likely to earn persistent abnormal returns by:","options":["Bearing market risk for a fair expected premium","Diversifying across asset classes","Trading on already public earnings reports alone"],"correct":2,"why_vi":"Public info đã được reflected vào prices.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A key attraction of passive management is:","options":["Lower expected implementation and research costs","Guaranteed positive returns","Immunity from market downturns"],"correct":0,"why_vi":"Costs là trọng tâm của passive benefit.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A technical trading rule based only on past prices challenges which form most directly if it generates reliable net abnormal returns?","options":["Only strong form","Weak form","No form of efficiency"],"correct":1,"why_vi":"Price history là weak-form data set.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Technical analysis","back_vi":"Chart trends, support/resistance, past volume và momentum signals chỉ dựa trên history. Nếu weak-form hoàn toàn hiệu quả, phương pháp chỉ dùng historical market data không đem lại net risk-adjusted abnormal return ổn định. Exam trap: Trading profits trước costs chưa chứng minh alpha."},{"front_en":"Fundamental analysis","back_vi":"Estimate cash flows, cost of capital, issuer quality dùng public financial/economic data. Semi-strong form đặt nghi vấn về lợi thế nhất quán chỉ dựa dữ liệu công khai đã được xử lý vào giá. Exam trap: Fundamental work vẫn hữu ích cho risk control, governance và asset allocation."},{"front_en":"Active management","back_vi":"Active nhằm khai thác mispricing hoặc skill trong forecasting, trading, portfolio construction; phải so benchmark risk-adjusted và net of fees. Quy mô quỹ, capacity và market impact làm alpha khó scale. Exam trap: Một active manager có thể outperform do luck hoặc factor tilts."},{"front_en":"Passive management","back_vi":"Passive tracking index tiết kiệm research/trading costs, đem market exposure minh bạch; vẫn chịu market risk, tracking error, index concentration và fees. Exam trap: Passive không phải risk-free, không chắc outperform từng active manager."},{"front_en":"Market efficiency by segment","back_vi":"Emerging, thinly traded hoặc complex assets có thể ít được phân tích hơn; nhưng illiquidity/implementation costs có thể triệt tiêu apparent arbitrage. Chọn chiến lược dựa evidence và constraints cụ thể. Exam trap: Đừng mặc định less efficient = easier net profits."}]},{"id":"CFA26-05-03-LOS06","letter":"3.f","title_en":"Market Anomalies","outcome_en":"describe observed return patterns that challenge simplified market-efficiency predictions","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM3 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM3 — Market Efficiency","pages":"official outcomes at physical PDF p133; teaching chapter physical pp133–168"}],"sections":[{"heading":"Calendar patterns","body":"Day-of-week, January effect hoặc turn-of-year returns từng được ghi nhận ở một số thị trường/giai đoạn. Độ bền theo thời gian thay đổi và phụ thuộc data/research selection.","trap":"Lịch sử anomaly không đồng nghĩa có trading edge hôm nay."},{"heading":"Size and value effects","body":"Small-cap và high book-to-market stocks có lúc outperform sau điều chỉnh thô; có thể phản ánh omitted risk factors, behavioral mispricing hoặc implementation frictions.","trap":"Không coi equity factor premium chắc chắn là phi lý."},{"heading":"Momentum and reversals","body":"Momentum: recent winners có thể tiếp tục outperform trong một số horizons; long-term reversal có thể phản ánh quá mức phản ứng. Cần tách horizon và giao dịch thực tế.","trap":"Không nhầm short-term continuation với long-run mean reversion."},{"heading":"Post-announcement drift","body":"Một số nghiên cứu thấy prices tiếp tục di chuyển cùng chiều unexpected earnings sau công bố. Tuy nhiên cách xác định earnings surprise, risk factors, spread và data snooping ảnh hưởng inference.","trap":"Không có return chắc chắn chỉ nhờ earnings surprise."},{"heading":"Anomaly evaluation","body":"Kiểm tra out-of-sample, multiple testing, structural breaks, survivorship, look-ahead bias và net-of-cost results. Anomaly có thể biến mất khi nhiều investor khai thác.","trap":"Statistical significance khác economic profitability."}],"formulas":[{"name":"Net exploitable anomaly","expr":"Gross pattern return − commissions − spreads − impact − short/borrow costs","meaning":"So sánh thực tiễn trước và sau trading frictions.","conditions":"Không phải công thức định giá canonical."},{"name":"Out-of-sample principle","expr":"Define rule on training data → test untouched data → test robustness","meaning":"Hạn chế overfitting khi nghiên cứu anomalies.","conditions":"Historical backtest đẹp không thay thế live evidence."}],"examples":[{"question_en":"A backtested strategy produces 1.2% gross excess return per year but incurs 1.6% annual implementation costs. What is its simple net excess return?","steps_vi":["Net = 1.2%−1.6%.","Chưa xét model error hoặc factor risk."],"answer":"−0.4% per year","check":"A gross historical premium is not necessarily tradeable."}],"questions":[{"stem_en":"The post-earnings-announcement drift anomaly refers to:","options":["Continued price movement after an earnings surprise","Prices becoming permanently fixed on announcement day","Guaranteed arbitrage around ex-dividend dates"],"correct":0,"why_vi":"Drift nói price điều chỉnh kéo dài sau news.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Why might a documented anomaly fail in live trading?","options":["All securities have guaranteed same return","Costs, crowding, and data mining","Index funds eliminate all information differences"],"correct":1,"why_vi":"Backtest and real net returns không giống nhau.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"The value effect is frequently examined using which characteristic?","options":["Low coupon frequency","High par value","High book-to-market equity"],"correct":2,"why_vi":"Book-to-market là thước đo commonly used in value studies.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Calendar patterns","back_vi":"Day-of-week, January effect hoặc turn-of-year returns từng được ghi nhận ở một số thị trường/giai đoạn. Độ bền theo thời gian thay đổi và phụ thuộc data/research selection. Exam trap: Lịch sử anomaly không đồng nghĩa có trading edge hôm nay."},{"front_en":"Size and value effects","back_vi":"Small-cap và high book-to-market stocks có lúc outperform sau điều chỉnh thô; có thể phản ánh omitted risk factors, behavioral mispricing hoặc implementation frictions. Exam trap: Không coi equity factor premium chắc chắn là phi lý."},{"front_en":"Momentum and reversals","back_vi":"Momentum: recent winners có thể tiếp tục outperform trong một số horizons; long-term reversal có thể phản ánh quá mức phản ứng. Cần tách horizon và giao dịch thực tế. Exam trap: Không nhầm short-term continuation với long-run mean reversion."},{"front_en":"Post-announcement drift","back_vi":"Một số nghiên cứu thấy prices tiếp tục di chuyển cùng chiều unexpected earnings sau công bố. Tuy nhiên cách xác định earnings surprise, risk factors, spread và data snooping ảnh hưởng inference. Exam trap: Không có return chắc chắn chỉ nhờ earnings surprise."},{"front_en":"Anomaly evaluation","back_vi":"Kiểm tra out-of-sample, multiple testing, structural breaks, survivorship, look-ahead bias và net-of-cost results. Anomaly có thể biến mất khi nhiều investor khai thác. Exam trap: Statistical significance khác economic profitability."}]},{"id":"CFA26-05-03-LOS07","letter":"3.g","title_en":"Behavioral Finance and Anomalies","outcome_en":"describe behavioral finance and why biases and limits to arbitrage may contribute to anomalies","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM3 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM3 — Market Efficiency","pages":"official outcomes at physical PDF p133; teaching chapter physical pp133–168"}],"sections":[{"heading":"Bounded rationality and biases","body":"Behavioral finance nghiên cứu cách nhận thức, cảm xúc và framing khiến decision khác frictionless rational models. Bias có thể dẫn systematic errors, nhưng không phải ai cũng phi lý mọi lúc.","trap":"Individual bias không tự đủ chứng minh market mispricing."},{"heading":"Overconfidence and herding","body":"Overconfidence khiến investor đánh giá quá cao signal, giao dịch quá nhiều; herding dẫn nhà đầu tư bắt chước đám đông, khuếch đại trends và volatility.","trap":"Herding đôi khi là rational information inference, không phải luôn bias."},{"heading":"Loss aversion and disposition","body":"Prospect theory mô tả loss aversion quanh reference point; disposition effect: chốt winners sớm và giữ losers quá lâu. Điều này liên quan giá mua gốc, không nhất thiết với intrinsic value hiện tại.","trap":"Không đánh đồng loss aversion với mức risk aversion trong mọi trạng thái."},{"heading":"Anchoring, representativeness, conservatism","body":"Anchoring bám giá ban đầu; representativeness extrapolate pattern từ mẫu nhỏ; conservatism cập nhật expectations chậm. Có thể góp phần underreaction hoặc overreaction.","trap":"Một hành vi quan sát riêng không đủ kết luận mọi price error."},{"heading":"Limits to correction","body":"Arbitrageurs chịu funding/short-selling/benchmark risk và uncertainty về thời điểm reversion. Vì vậy các bias ảnh hưởng price có thể tồn tại dù có người nhìn thấy.","trap":"Behavioral story cần được kiểm chứng bằng dữ liệu và net return."}],"formulas":[{"name":"Disposition effect","expr":"propensity to sell winners sooner than losers relative to purchase reference prices","meaning":"Mô tả thiên lệch hành vi.","conditions":"Không phải công thức sinh lợi hay quy tắc định giá."},{"name":"Behavioral-price mechanism","expr":"biased beliefs + correlated trading + limits to arbitrage → potentially persistent deviations","meaning":"Khung diễn giải conceptual.","conditions":"'Potentially' không phải guarantee."}],"examples":[{"question_en":"An investor immediately sells a winner for a small gain but refuses to sell a loser despite unchanged negative fundamentals. Which bias is most apparent?","steps_vi":["Reference point là purchase price.","Hành động hiện thực hóa gain sớm nhưng tránh ghi nhận loss phản ánh disposition effect."],"answer":"Disposition effect","check":"Without investor motives one cannot prove bias definitively."}],"questions":[{"stem_en":"Selling winners rapidly while retaining losers is most associated with:","options":["Duration matching","Disposition effect","Price weighting"],"correct":1,"why_vi":"Loss aversion có thể dẫn đến disposition effect.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Which behavioral tendency involves excessive trust in one’s forecasting skill?","options":["Liquidity transformation","Reconstitution","Overconfidence"],"correct":2,"why_vi":"Overconfidence leads overtrading/underestimating uncertainty.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Why can behavioral mispricing persist?","options":["Arbitrageurs may face funding and short-selling risks","All investors observe private information","Every deviation guarantees an immediate riskless trade"],"correct":0,"why_vi":"Limits to arbitrage cản sửa sai tức thì.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Bounded rationality and biases","back_vi":"Behavioral finance nghiên cứu cách nhận thức, cảm xúc và framing khiến decision khác frictionless rational models. Bias có thể dẫn systematic errors, nhưng không phải ai cũng phi lý mọi lúc. Exam trap: Individual bias không tự đủ chứng minh market mispricing."},{"front_en":"Overconfidence and herding","back_vi":"Overconfidence khiến investor đánh giá quá cao signal, giao dịch quá nhiều; herding dẫn nhà đầu tư bắt chước đám đông, khuếch đại trends và volatility. Exam trap: Herding đôi khi là rational information inference, không phải luôn bias."},{"front_en":"Loss aversion and disposition","back_vi":"Prospect theory mô tả loss aversion quanh reference point; disposition effect: chốt winners sớm và giữ losers quá lâu. Điều này liên quan giá mua gốc, không nhất thiết với intrinsic value hiện tại. Exam trap: Không đánh đồng loss aversion với mức risk aversion trong mọi trạng thái."},{"front_en":"Anchoring, representativeness, conservatism","back_vi":"Anchoring bám giá ban đầu; representativeness extrapolate pattern từ mẫu nhỏ; conservatism cập nhật expectations chậm. Có thể góp phần underreaction hoặc overreaction. Exam trap: Một hành vi quan sát riêng không đủ kết luận mọi price error."},{"front_en":"Limits to correction","back_vi":"Arbitrageurs chịu funding/short-selling/benchmark risk và uncertainty về thời điểm reversion. Vì vậy các bias ảnh hưởng price có thể tồn tại dù có người nhìn thấy. Exam trap: Behavioral story cần được kiểm chứng bằng dữ liệu và net return."}]}]},{"module_id":"CFA26-05-04","module_title":"Overview of Equity Securities","subject":"Equity Investments","version":"3.8","qa_status":"SOURCE_GROUNDED_DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT","language":"Vietnamese explanatory notes; original English question stems and options","source_policy":"Original bilingual paraphrased lessons and original practice based on CFAI 2026 Equity Volume 5, module 4; primary PDF directly inspected; additional line-by-line editorial checks pending","los":[{"id":"CFA26-05-04-LOS01","letter":"4.a","title_en":"Types and Features of Equity Securities","outcome_en":"describe the characteristics of major equity security types","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM4 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM4 — Overview of Equity Securities","pages":"official outcomes at physical PDF p169; teaching chapter physical pp169–206"}],"sections":[{"heading":"Common shares","body":"Common equity đại diện residual ownership, thường quyền bỏ phiếu, nhận dividends nếu declared, và hưởng capital gains/losses. Khi liquidation, common residual sau creditors và preferred equity.","trap":"Common dividend không phải contractual interest."},{"heading":"Preferred shares","body":"Preferred thường ưu tiên dividends/liquidation trên common và có đặc điểm gần fixed income, nhưng vẫn là equity. Rights cụ thể được quyết định bởi charter, có thể có hoặc không voting.","trap":"Preferred không nhất thiết có maturity hoặc guaranteed payments."},{"heading":"Cumulative and noncumulative","body":"Cumulative preferred: dividends bị bỏ lỡ tích lũy thành arrears trước khi common dividends được trả; noncumulative không mang arrears. Không phải nghĩa vụ bond coupon theo lịch.","trap":"Missing preferred dividend thường khác default của debt."},{"heading":"Participating and convertible","body":"Participating preferred có quyền tham gia phần upside beyond stated preference theo điều kiện; convertible preferred có thể đổi thành common theo ratio, làm payoff phụ thuộc common share price.","trap":"Quyền chuyển đổi làm preferred có optionality."},{"heading":"Callable and putable","body":"Callable preferred cho issuer quyền mua lại theo contract; putable cho holder quyền yêu cầu repurchase, tùy terms. Các option này tác động return và price sensitivity.","trap":"Callable thường hạn chế upside của investor."}],"formulas":[{"name":"Residual common claim","expr":"Common liquidation value = max(remaining assets after senior claims, 0)","meaning":"Ưu tiên common thấp hơn debt/preferred.","conditions":"Simplified waterfall; actual legal priorities vary."},{"name":"Preference dividend cash flow","expr":"Preferred expected dividend ≈ stated dividend per share when declared and payable","meaning":"Cash flow cần theo contractual terms.","conditions":"Arrears and tax treatment depend on security."}],"examples":[{"question_en":"A company has $100 of realizable assets, $70 of senior debt claims, and $20 of preferred liquidation preference. What is left for common equity, ignoring costs?","steps_vi":["Remaining after debt = 100−70 = 30.","After preferred claims = 30−20 = 10."],"answer":"$10","check":"Stylized liquidation waterfall before taxes and other claims."}],"questions":[{"stem_en":"Which claim is usually most residual in liquidation?","options":["Senior secured debt","Contractual bond interest","Common equity"],"correct":2,"why_vi":"Common được chi trả sau claims ưu tiên.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A cumulative preferred share generally provides:","options":["Carryforward of unpaid preferred dividends before common distribution","A guarantee that all dividends are cash-paid on schedule","Unlimited voting power in every circumstance"],"correct":0,"why_vi":"Arrears accumulate; payment timing still conditional.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Convertible preferred stock grants a holder the option to:","options":["Require common shareholders to guarantee dividends","Exchange into a specified common equity amount","Remove all equity downside"],"correct":1,"why_vi":"Convertible adds right based on conversion terms.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Common shares","back_vi":"Common equity đại diện residual ownership, thường quyền bỏ phiếu, nhận dividends nếu declared, và hưởng capital gains/losses. Khi liquidation, common residual sau creditors và preferred equity. Exam trap: Common dividend không phải contractual interest."},{"front_en":"Preferred shares","back_vi":"Preferred thường ưu tiên dividends/liquidation trên common và có đặc điểm gần fixed income, nhưng vẫn là equity. Rights cụ thể được quyết định bởi charter, có thể có hoặc không voting. Exam trap: Preferred không nhất thiết có maturity hoặc guaranteed payments."},{"front_en":"Cumulative and noncumulative","back_vi":"Cumulative preferred: dividends bị bỏ lỡ tích lũy thành arrears trước khi common dividends được trả; noncumulative không mang arrears. Không phải nghĩa vụ bond coupon theo lịch. Exam trap: Missing preferred dividend thường khác default của debt."},{"front_en":"Participating and convertible","back_vi":"Participating preferred có quyền tham gia phần upside beyond stated preference theo điều kiện; convertible preferred có thể đổi thành common theo ratio, làm payoff phụ thuộc common share price. Exam trap: Quyền chuyển đổi làm preferred có optionality."},{"front_en":"Callable and putable","back_vi":"Callable preferred cho issuer quyền mua lại theo contract; putable cho holder quyền yêu cầu repurchase, tùy terms. Các option này tác động return và price sensitivity. Exam trap: Callable thường hạn chế upside của investor."}]},{"id":"CFA26-05-04-LOS02","letter":"4.b","title_en":"Voting and Ownership Rights","outcome_en":"describe how voting rights and other ownership features vary across equity classes","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM4 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM4 — Overview of Equity Securities","pages":"official outcomes at physical PDF p169; teaching chapter physical pp169–206"}],"sections":[{"heading":"Voting structures","body":"One-share-one-vote là phổ biến nhưng dual/multi-class có shares với số votes khác nhau. Voting power có thể khác economic ownership; control premium hoặc governance discount có thể xuất hiện.","trap":"Không mặc định mọi common share có một vote."},{"heading":"Control and board elections","body":"Voting thường liên quan bầu directors, mergers và corporate actions; một số shares nonvoting vẫn có economic claims. Cách vote cumulative/straight voting thay đổi minority representation.","trap":"Voting rights là quyền theo charter và jurisdiction."},{"heading":"Economic rights and priorities","body":"Share classes có thể khác dividend preference, liquidation, conversion và transfer restrictions. Giá hai classes có thể khác do control, liquidity và investor base.","trap":"Giá cao hơn không chỉ phản ánh dividend."},{"heading":"Restrictions and protections","body":"Preemptive rights, tag-along, veto rights hoặc minority protections tùy jurisdiction, covenant và charter. Investor phải kiểm tra issuance dilution và ownership agreements.","trap":"Đừng gán đồng nhất các quyền cho toàn cầu."},{"heading":"Depositary voting","body":"Depositary receipts đại diện underlying shares; holder rights phụ thuộc deposit agreement và quyền truyền vote tới custodian.","trap":"DR holder không luôn có identical voting mechanics như direct holder."}],"formulas":[{"name":"Votes controlled","expr":"Voting power = votes held / total outstanding voting rights","meaning":"Đo quyền kiểm soát, có thể không bằng capital ownership %.","conditions":"Distinct share classes and turnout may alter effective control."},{"name":"Cumulative voting example","expr":"With n board seats, shareholder voting units = shares held × seats elected","meaning":"Mô hình vote pooling điển hình.","conditions":"Specific company law/charter determines election method."}],"examples":[{"question_en":"A founder owns 10 million Class B shares with 10 votes each; public holders own 90 million Class A shares with one vote each. What fraction of votes does the founder control?","steps_vi":["Founder votes=10m×10=100m.","Public votes=90m×1=90m.","Founder share=100/(100+90)."],"answer":"52.63% of voting power","check":"Founder holds only 10% of economic share count assuming equal economic rights."}],"questions":[{"stem_en":"Dual-class stock can create:","options":["Voting control disproportionate to economic ownership","Mandatory identical voting power for every share","Elimination of agency conflicts"],"correct":0,"why_vi":"Multi-class voting weights differ.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A nonvoting equity share may still provide:","options":["Guaranteed senior secured status","An economic residual ownership claim","A fixed contractual bond coupon"],"correct":1,"why_vi":"Voting vs economic rights separate dimensions.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Cumulative voting is often discussed because it can:","options":["Guarantee a controlling majority for every minority investor","Eliminate the need for shareholder meetings","Improve minority shareholder influence in director elections"],"correct":2,"why_vi":"Votes can be concentrated across candidates.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Voting structures","back_vi":"One-share-one-vote là phổ biến nhưng dual/multi-class có shares với số votes khác nhau. Voting power có thể khác economic ownership; control premium hoặc governance discount có thể xuất hiện. Exam trap: Không mặc định mọi common share có một vote."},{"front_en":"Control and board elections","back_vi":"Voting thường liên quan bầu directors, mergers và corporate actions; một số shares nonvoting vẫn có economic claims. Cách vote cumulative/straight voting thay đổi minority representation. Exam trap: Voting rights là quyền theo charter và jurisdiction."},{"front_en":"Economic rights and priorities","back_vi":"Share classes có thể khác dividend preference, liquidation, conversion và transfer restrictions. Giá hai classes có thể khác do control, liquidity và investor base. Exam trap: Giá cao hơn không chỉ phản ánh dividend."},{"front_en":"Restrictions and protections","back_vi":"Preemptive rights, tag-along, veto rights hoặc minority protections tùy jurisdiction, covenant và charter. Investor phải kiểm tra issuance dilution và ownership agreements. Exam trap: Đừng gán đồng nhất các quyền cho toàn cầu."},{"front_en":"Depositary voting","back_vi":"Depositary receipts đại diện underlying shares; holder rights phụ thuộc deposit agreement và quyền truyền vote tới custodian. Exam trap: DR holder không luôn có identical voting mechanics như direct holder."}]},{"id":"CFA26-05-04-LOS03","letter":"4.c","title_en":"Public Versus Private Equity","outcome_en":"compare publicly traded equity with privately held equity securities","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM4 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM4 — Overview of Equity Securities","pages":"official outcomes at physical PDF p169; teaching chapter physical pp169–206"}],"sections":[{"heading":"Trading and liquidity","body":"Public equity thường list trên exchange/regulated venue với quotes và trading frequency cao hơn. Private shares ít giao dịch, có lockups, consent clauses và buyer search costs.","trap":"Public listing không đảm bảo mọi small-cap stock thanh khoản cao."},{"heading":"Information availability","body":"Public companies chịu disclosure, periodic filing và audit requirements theo luật; private firms có data hạn chế và reporting negotiated with investors.","trap":"Disclosure standards khác theo jurisdiction."},{"heading":"Control and governance","body":"Private investors có thể thương lượng board seats, veto rights hoặc governance covenants; public investors thường minority dispersed. Quyền kiểm soát ảnh hưởng valuation.","trap":"Private ownership không đồng nghĩa tất cả investor kiểm soát management."},{"heading":"Valuation and transaction","body":"Public price là mark quan sát nhưng dao động; private valuation dựa comparable transactions, DCF hoặc funding rounds, có uncertainties cao. Private marks có thể được cập nhật ít thường xuyên.","trap":"Volatility reported thấp có thể là stale pricing."},{"heading":"Capital raising and exit","body":"Public equity giúp tiếp cận broad capital pool; private funding qua VC, PE hoặc strategic investors. Exits có thể IPO, M&A hoặc secondary private transaction.","trap":"IPO không tự động tạo cash cho company nếu là secondary sale."}],"formulas":[{"name":"Private illiquidity","expr":"Required expected return may include compensation for illiquidity and other risks","meaning":"Khung định tính, không phải universal fixed premium.","conditions":"Risks and control rights can offset in different directions."},{"name":"Observed-price caveat","expr":"Frequent quoted public prices ≠ error-free intrinsic value","meaning":"Giá quan sát được không phải valuation certainty.","conditions":"Không áp dụng một mô hình cho mọi công ty."}],"examples":[{"question_en":"A startup is privately held and investors cannot sell shares for five years. What feature most directly differentiates it from a widely traded listed stock?","steps_vi":["Restriction on exit and lack of continuous public price discovery.","Investors may require additional expected compensation, subject to other factors."],"answer":"Lower liquidity and harder price discovery","check":"A public listing still may have illiquid securities."}],"questions":[{"stem_en":"Private equity valuations usually involve more:","options":["Intraday exchange quotes","Model inputs and negotiated transaction evidence","Mandatory identical monthly prices across firms"],"correct":1,"why_vi":"Private market lacks liquid exchange price.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Which is a common potential advantage of public equity issuance?","options":["Freedom from all disclosure obligations","Guaranteed lower cost of capital in every case","Access to a broad investment base"],"correct":2,"why_vi":"Public access broadens fundraise but costs vary.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A low reported volatility for infrequently priced private assets may partly result from:","options":["Appraisal smoothing and stale prices","Elimination of underlying business risk","Guaranteed loss protection"],"correct":0,"why_vi":"Infrequent marks understate measured volatility.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Trading and liquidity","back_vi":"Public equity thường list trên exchange/regulated venue với quotes và trading frequency cao hơn. Private shares ít giao dịch, có lockups, consent clauses và buyer search costs. Exam trap: Public listing không đảm bảo mọi small-cap stock thanh khoản cao."},{"front_en":"Information availability","back_vi":"Public companies chịu disclosure, periodic filing và audit requirements theo luật; private firms có data hạn chế và reporting negotiated with investors. Exam trap: Disclosure standards khác theo jurisdiction."},{"front_en":"Control and governance","back_vi":"Private investors có thể thương lượng board seats, veto rights hoặc governance covenants; public investors thường minority dispersed. Quyền kiểm soát ảnh hưởng valuation. Exam trap: Private ownership không đồng nghĩa tất cả investor kiểm soát management."},{"front_en":"Valuation and transaction","back_vi":"Public price là mark quan sát nhưng dao động; private valuation dựa comparable transactions, DCF hoặc funding rounds, có uncertainties cao. Private marks có thể được cập nhật ít thường xuyên. Exam trap: Volatility reported thấp có thể là stale pricing."},{"front_en":"Capital raising and exit","back_vi":"Public equity giúp tiếp cận broad capital pool; private funding qua VC, PE hoặc strategic investors. Exits có thể IPO, M&A hoặc secondary private transaction. Exam trap: IPO không tự động tạo cash cho company nếu là secondary sale."}]},{"id":"CFA26-05-04-LOS04","letter":"4.d","title_en":"Accessing Foreign Equity Markets","outcome_en":"describe ways investors obtain exposure to non-domestic equity","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM4 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM4 — Overview of Equity Securities","pages":"official outcomes at physical PDF p169; teaching chapter physical pp169–206"}],"sections":[{"heading":"Direct foreign share purchase","body":"Investor mua ordinary shares ở foreign exchange bằng foreign currency, phải xét settlement, custody, taxes, trading hours, capital controls và availability.","trap":"Foreign shares có currency exposure dù issuer hoạt động toàn cầu."},{"heading":"Depositary receipts","body":"ADR/GDR là transferable certificates do depositary bank phát hành đại diện underlying foreign shares held by custodian. Trading currency/venue của DR có thể khác underlying.","trap":"Depositary receipt không phải một loại issuer độc lập."},{"heading":"Sponsored versus unsponsored","body":"Sponsored DR thường có issuer participation và defined information/voting arrangements; unsponsored programs có mechanics khác, cần xem deposit agreement.","trap":"Không giả định cùng reporting/cost/voting cho mọi DR."},{"heading":"Global registered shares and cross-listings","body":"Global registered shares có thể trade trên nhiều venues; cross-listing tăng investor reach nhưng có legal, currency và settlement considerations.","trap":"Multiple listings không tự loại bỏ exchange-rate risk."},{"heading":"Funds and associated risks","body":"International ETF/mutual fund tạo diversified foreign exposure; phải xét country risk, FX risk, custody, taxation, political risk và tracking differences.","trap":"Diversification giảm issuer-specific risk, không xóa systematic risk."}],"formulas":[{"name":"Receipt underlying equivalent","expr":"Underlying equivalent shares = number of DRs × underlying shares per DR","meaning":"Mapping DR ratio cho economic exposures.","conditions":"Check actual ratio, fees and corporate actions."},{"name":"Home-currency return approximation","expr":"(1+R_local)(1+FX_return_home_per_local)−1","meaning":"Return khi đổi tài sản foreign về home currency.","conditions":"FX quote orientation phải đúng."}],"examples":[{"question_en":"A foreign share rises 8% in its local currency while that currency depreciates 5% against an investor’s home currency. What is the investor’s approximate home-currency return?","steps_vi":["Gross local growth=1.08.","Currency conversion factor=0.95.","Total home growth=1.08×0.95=1.026."],"answer":"2.6%","check":"Assumes no dividends, taxes, receipt fees or other frictions."}],"questions":[{"stem_en":"A depositary receipt generally represents:","options":["A sovereign foreign-currency bond","A guaranteed exchange-rate hedge","An interest in underlying foreign shares held through a depositary arrangement"],"correct":2,"why_vi":"DR links to underlying foreign equity.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A foreign share appreciates 10% locally but its currency falls 10% versus the investor’s home currency. Home-currency total return is approximately:","options":["−1%","0%","+10%"],"correct":0,"why_vi":"(1.10×0.90)−1=−1%.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Which exposure is often present when buying foreign stocks without hedging?","options":["Guaranteed protection against inflation","Currency risk","Zero jurisdictional risk"],"correct":1,"why_vi":"FX moves matter for home-currency returns.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Direct foreign share purchase","back_vi":"Investor mua ordinary shares ở foreign exchange bằng foreign currency, phải xét settlement, custody, taxes, trading hours, capital controls và availability. Exam trap: Foreign shares có currency exposure dù issuer hoạt động toàn cầu."},{"front_en":"Depositary receipts","back_vi":"ADR/GDR là transferable certificates do depositary bank phát hành đại diện underlying foreign shares held by custodian. Trading currency/venue của DR có thể khác underlying. Exam trap: Depositary receipt không phải một loại issuer độc lập."},{"front_en":"Sponsored versus unsponsored","back_vi":"Sponsored DR thường có issuer participation và defined information/voting arrangements; unsponsored programs có mechanics khác, cần xem deposit agreement. Exam trap: Không giả định cùng reporting/cost/voting cho mọi DR."},{"front_en":"Global registered shares and cross-listings","back_vi":"Global registered shares có thể trade trên nhiều venues; cross-listing tăng investor reach nhưng có legal, currency và settlement considerations. Exam trap: Multiple listings không tự loại bỏ exchange-rate risk."},{"front_en":"Funds and associated risks","back_vi":"International ETF/mutual fund tạo diversified foreign exposure; phải xét country risk, FX risk, custody, taxation, political risk và tracking differences. Exam trap: Diversification giảm issuer-specific risk, không xóa systematic risk."}]},{"id":"CFA26-05-04-LOS05","letter":"4.e","title_en":"Equity Risk and Return","outcome_en":"compare risk–return characteristics of equity security types","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM4 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM4 — Overview of Equity Securities","pages":"official outcomes at physical PDF p169; teaching chapter physical pp169–206"}],"sections":[{"heading":"Common versus preferred","body":"Common equity chịu earnings uncertainty và residual downside nhưng có participation trong upside không cố định; straight preferred thường ưu tiên dividend/liquidation nhưng upside giới hạn hơn.","trap":"Không khẳng định preferred luôn an toàn hơn debt."},{"heading":"Cyclical and defensive equity","body":"Cyclical earnings gắn chặt economy, consumer demand và capital spending; defensive sectors cung cấp hàng/dịch vụ ổn định hơn. Diversification và valuation vẫn quan trọng.","trap":"Defensive không có nghĩa share price không giảm."},{"heading":"Growth and value","body":"Growth stocks có valuation nhạy long-term growth assumptions; value stocks thường được đánh giá theo relative valuation, cash flow và fundamentals. Hai style có thể overlap.","trap":"P/E thấp không tự chứng minh undervalued."},{"heading":"Systematic versus idiosyncratic risk","body":"Equity returns chịu market beta, interest rates, FX và industry factors; firm-specific event risk có thể diversification giảm. Country and liquidity risks có thể đi kèm.","trap":"Diversification không triệt tiêu broad market risk."},{"heading":"International return measurement","body":"Return của investor phụ thuộc share price/dividend bằng local currency cộng FX translation; withholding tax và capital restrictions có thể giảm realized returns.","trap":"Currency và stock returns cộng arithmetic chỉ là xấp xỉ."}],"formulas":[{"name":"Stock total holding-period return","expr":"R=(P1−P0+D)/P0","meaning":"Return từ capital gain và distribution trong cùng currency.","conditions":"Không gồm trading fees/taxes nếu chưa chỉ định."},{"name":"Return in home currency","expr":"R_home=(1+R_foreign)(1+R_FX)−1","meaning":"Compound FX translation cùng local asset return.","conditions":"FX return phải đo theo local currency appreciation against home."}],"examples":[{"question_en":"A preferred security pays $6 annual dividends and moves from $90 to $93. Estimate the holding period return assuming payment and sale over one year.","steps_vi":["Capital gain = $3; dividend = $6.","Return = ($3+$6)/$90 = 0.10."],"answer":"10%","check":"Ignore taxes, fees and reinvestment."}],"questions":[{"stem_en":"Which share type generally has the most residual claim on corporate net assets?","options":["Common equity","Senior secured bond","Cumulative preferred equity"],"correct":0,"why_vi":"Common receives residual after preferred/debt.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Portfolio diversification is most effective at reducing:","options":["All systematic market risk","Idiosyncratic company-specific risk","All expected return variability"],"correct":1,"why_vi":"Non-systematic risk can diversify.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A stock price rises 5% and pays a dividend equal to 2% of initial price. Simple total return is:","options":["3%","10%","7%"],"correct":2,"why_vi":"(P1−P0+D)/P0=5%+2%=7%.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Common versus preferred","back_vi":"Common equity chịu earnings uncertainty và residual downside nhưng có participation trong upside không cố định; straight preferred thường ưu tiên dividend/liquidation nhưng upside giới hạn hơn. Exam trap: Không khẳng định preferred luôn an toàn hơn debt."},{"front_en":"Cyclical and defensive equity","back_vi":"Cyclical earnings gắn chặt economy, consumer demand và capital spending; defensive sectors cung cấp hàng/dịch vụ ổn định hơn. Diversification và valuation vẫn quan trọng. Exam trap: Defensive không có nghĩa share price không giảm."},{"front_en":"Growth and value","back_vi":"Growth stocks có valuation nhạy long-term growth assumptions; value stocks thường được đánh giá theo relative valuation, cash flow và fundamentals. Hai style có thể overlap. Exam trap: P/E thấp không tự chứng minh undervalued."},{"front_en":"Systematic versus idiosyncratic risk","back_vi":"Equity returns chịu market beta, interest rates, FX và industry factors; firm-specific event risk có thể diversification giảm. Country and liquidity risks có thể đi kèm. Exam trap: Diversification không triệt tiêu broad market risk."},{"front_en":"International return measurement","back_vi":"Return của investor phụ thuộc share price/dividend bằng local currency cộng FX translation; withholding tax và capital restrictions có thể giảm realized returns. Exam trap: Currency và stock returns cộng arithmetic chỉ là xấp xỉ."}]},{"id":"CFA26-05-04-LOS06","letter":"4.f","title_en":"Equity Financing of Corporate Assets","outcome_en":"explain how equity finances corporate assets and affects capital structure","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM4 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM4 — Overview of Equity Securities","pages":"official outcomes at physical PDF p169; teaching chapter physical pp169–206"}],"sections":[{"heading":"Balance sheet financing","body":"Assets được tài trợ bằng liabilities và equity; common shares ghi residual balance sheet interest. Phát hành new equity tăng cash assets và shareholder equity khi giữ các yếu tố khác.","trap":"Giá cổ phiếu trên thị trường tăng không tự tăng book equity của issuer."},{"heading":"No scheduled repayment","body":"Common equity không có contractual maturity hoặc bắt buộc hoàn gốc như ordinary debt; giúp absorber losses và funding dài hạn. Đổi lại ownership/control bị phân tán.","trap":"Không suy ra common equity là vốn miễn phí."},{"heading":"Primary equity proceeds","body":"New issue đem proceeds cho issuer sau issuance costs; secondary share transfer không cấp vốn mới. Rights offerings/seasoned offerings và IPO có thể gồm primary lẫn secondary tranches.","trap":"Phải xem số shares newly issued, không chỉ gross offering size."},{"heading":"Dilution and share count","body":"Issuing additional shares có thể dilute voting/earnings per share nếu funds không tạo đủ value; fair-priced issuance có thể tăng equity value mà không nhất thiết làm mỗi share mất giá trị.","trap":"Mechanical EPS dilution không luôn là economic value destruction."},{"heading":"Leverage tradeoff","body":"Debt tạo tax shields trong một số thuế chế, nhưng tăng distress và covenant risk; equity có downside absorption, làm weighted cost/hurdle khác.","trap":"Không có universal optimal debt-equity mix."}],"formulas":[{"name":"Accounting equation","expr":"Assets = Liabilities + Shareholders' equity","meaning":"Nguồn vốn của doanh nghiệp theo balance sheet.","conditions":"Book values may differ from market values."},{"name":"Gross primary proceeds","expr":"Newly issued shares × issue price","meaning":"Cash inflow to issuer before underwriting fees.","conditions":"Excludes secondary shares sold by existing shareholders."}],"examples":[{"question_en":"An issuer sells 3 million newly issued shares for $18 each. Another investor sells 1 million existing shares at the same price. How much gross equity capital does the issuer raise?","steps_vi":["Primary issuance 3m × $18 = $54m.","Existing shareholders receive proceeds on their own secondary shares."],"answer":"$54 million","check":"Ignore underwriting fees; offering has mixed primary/secondary tranches."}],"questions":[{"stem_en":"A company’s initial sale of newly created shares primarily:","options":["Pays all proceeds to secondary-market sellers","Raises equity capital for the issuer","Creates a contractual debt maturity"],"correct":1,"why_vi":"New shares → issuer financing.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Compared with ordinary debt, common equity typically:","options":["Requires a fixed coupon and due date","Is always cheaper in required return","Has no fixed scheduled principal repayment"],"correct":2,"why_vi":"Common lacks scheduled principal repayment obligation.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A secondary-market investor-to-investor stock trade normally:","options":["Does not provide new cash financing directly to the issuer","Increases issued shares automatically","Reduces debt covenants automatically"],"correct":0,"why_vi":"Issuer not generally transaction counterparty.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Balance sheet financing","back_vi":"Assets được tài trợ bằng liabilities và equity; common shares ghi residual balance sheet interest. Phát hành new equity tăng cash assets và shareholder equity khi giữ các yếu tố khác. Exam trap: Giá cổ phiếu trên thị trường tăng không tự tăng book equity của issuer."},{"front_en":"No scheduled repayment","back_vi":"Common equity không có contractual maturity hoặc bắt buộc hoàn gốc như ordinary debt; giúp absorber losses và funding dài hạn. Đổi lại ownership/control bị phân tán. Exam trap: Không suy ra common equity là vốn miễn phí."},{"front_en":"Primary equity proceeds","back_vi":"New issue đem proceeds cho issuer sau issuance costs; secondary share transfer không cấp vốn mới. Rights offerings/seasoned offerings và IPO có thể gồm primary lẫn secondary tranches. Exam trap: Phải xem số shares newly issued, không chỉ gross offering size."},{"front_en":"Dilution and share count","back_vi":"Issuing additional shares có thể dilute voting/earnings per share nếu funds không tạo đủ value; fair-priced issuance có thể tăng equity value mà không nhất thiết làm mỗi share mất giá trị. Exam trap: Mechanical EPS dilution không luôn là economic value destruction."},{"front_en":"Leverage tradeoff","back_vi":"Debt tạo tax shields trong một số thuế chế, nhưng tăng distress và covenant risk; equity có downside absorption, làm weighted cost/hurdle khác. Exam trap: Không có universal optimal debt-equity mix."}]},{"id":"CFA26-05-04-LOS07","letter":"4.g","title_en":"Market Value and Book Value of Equity","outcome_en":"contrast market value and accounting book value of equity","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM4 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM4 — Overview of Equity Securities","pages":"official outcomes at physical PDF p169; teaching chapter physical pp169–206"}],"sections":[{"heading":"Book shareholders' equity","body":"Book equity = reported assets − liabilities dưới accounting standards; là residual carrying value, chịu historical-cost rules, impairment, acquisition accounting và share repurchases.","trap":"Book equity không tự bằng liquidating value."},{"heading":"Market capitalization","body":"Market equity = current common share price × outstanding shares; phản ánh expectations, economic opportunities, intangibles, discount rates và liquidity.","trap":"Tránh nhân wrong share count hoặc bỏ qua share classes."},{"heading":"Price-to-book","body":"P/B ≈ market common equity / book common equity hoặc price/BVPS, với comparable share base. P/B cao có thể do profitable intangible business, không nhất thiết bubble.","trap":"Negative or very small book value khiến ratio khó diễn giải."},{"heading":"Sources of difference","body":"Internally generated brands, R&D, human capital ít được capitalized; poor asset quality và losses có thể khiến book value cao hơn economic value.","trap":"Không xem every book asset bằng market price."},{"heading":"Share repurchase impact","body":"Repurchase bằng cash giảm assets và book equity; effect lên BVPS tùy repurchase price so với pre-transaction BVPS và number of shares. P/B có thể thay đổi cơ học.","trap":"Repurchase không bảo đảm shareholder wealth gain."}],"formulas":[{"name":"Book equity","expr":"Assets_book − Liabilities_book","meaning":"Accounting residual interest.","conditions":"Requires consistent balance sheet scope."},{"name":"Price to book","expr":"P/B = market price per common share / book value per common share","meaning":"Relative valuation based on common equity book values.","conditions":"Be wary of negative BVPS and inconsistent share bases."}],"examples":[{"question_en":"A firm has $800 million reported assets and $500 million liabilities. It has 20 million shares trading at $24. Compute book equity, market equity, and P/B.","steps_vi":["Book equity=800−500=$300m, BVPS=$300m/20m=$15.","Market equity=20m×24=$480m.","P/B=24/15=1.6."],"answer":"Book equity $300m; market equity $480m; P/B 1.60","check":"Assumes a single common share class and no adjustments."}],"questions":[{"stem_en":"Book value of shareholders’ equity most directly equals:","options":["Share price times outstanding shares","Expected future dividends discounted at market rate","Reported assets less reported liabilities"],"correct":2,"why_vi":"Book value accounting balance.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A firm with a $25 market price and $10 BVPS has P/B equal to:","options":["2.5","0.4","15.0"],"correct":0,"why_vi":"P/B=25/10=2.5.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"The market value of equity can exceed book value partly due to:","options":["A requirement that historical cost equal market value","Expectations for unrecognized growth opportunities and intangibles","Guaranteed future dividends"],"correct":1,"why_vi":"Investors price future prospects not fully recognized on books.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Book shareholders' equity","back_vi":"Book equity = reported assets − liabilities dưới accounting standards; là residual carrying value, chịu historical-cost rules, impairment, acquisition accounting và share repurchases. Exam trap: Book equity không tự bằng liquidating value."},{"front_en":"Market capitalization","back_vi":"Market equity = current common share price × outstanding shares; phản ánh expectations, economic opportunities, intangibles, discount rates và liquidity. Exam trap: Tránh nhân wrong share count hoặc bỏ qua share classes."},{"front_en":"Price-to-book","back_vi":"P/B ≈ market common equity / book common equity hoặc price/BVPS, với comparable share base. P/B cao có thể do profitable intangible business, không nhất thiết bubble. Exam trap: Negative or very small book value khiến ratio khó diễn giải."},{"front_en":"Sources of difference","back_vi":"Internally generated brands, R&D, human capital ít được capitalized; poor asset quality và losses có thể khiến book value cao hơn economic value. Exam trap: Không xem every book asset bằng market price."},{"front_en":"Share repurchase impact","back_vi":"Repurchase bằng cash giảm assets và book equity; effect lên BVPS tùy repurchase price so với pre-transaction BVPS và number of shares. P/B có thể thay đổi cơ học. Exam trap: Repurchase không bảo đảm shareholder wealth gain."}]},{"id":"CFA26-05-04-LOS08","letter":"4.h","title_en":"Cost of Equity, ROE, and Required Return","outcome_en":"compare a company’s cost of equity, accounting ROE, and investors’ required rates of return","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM4 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM4 — Overview of Equity Securities","pages":"official outcomes at physical PDF p169; teaching chapter physical pp169–206"}],"sections":[{"heading":"Accounting ROE","body":"ROE = net income available to common shareholders / average common shareholders' equity; phản ánh historical accounting performance, chịu leverage và accounting policies.","trap":"ROE không phải realized shareholder return."},{"heading":"Investor required return","body":"Required return là compensation cần thiết cho time value và equity risk given alternatives; investor-specific constraints/tax views có thể tạo required returns khác nhau.","trap":"Không lấy ROE làm r trực tiếp trong DDM."},{"heading":"Company cost of equity","body":"Cost of equity là opportunity cost doanh nghiệp phải cung cấp cho equity capital để tài trợ dự án có cùng mức rủi ro. Có thể được estimate qua CAPM hoặc approaches khác.","trap":"Cost of equity không phải dividend yield đơn giản."},{"heading":"ROE versus economic value","body":"Project tạo value nếu risk-adjusted return trên capital cao hơn opportunity cost; high accounting ROE có thể do financial leverage chứ không nhất thiết chất lượng kinh doanh cao.","trap":"ROE > cost of equity cần điều chỉnh risk và accounting scope."},{"heading":"Retained earnings and growth","body":"Retaining earnings thay vì dividend vẫn có opportunity cost; sustainable growth approximation g≈ROE×retention khi assumptions ổn định và no new equity.","trap":"Không mặc định tăng growth luôn tăng value nếu reinvestment returns thấp."}],"formulas":[{"name":"ROE","expr":"Net income attributable to common / average common book equity","meaning":"Khả năng sinh lời accounting trên vốn common.","conditions":"Average equity và recurring earnings phù hợp."},{"name":"Required equity return (CAPM illustration)","expr":"r_e = r_f + beta × market equity risk premium","meaning":"Một phương pháp estimate opportunity cost của equity.","conditions":"CAPM assumptions và inputs phải phù hợp."},{"name":"Sustainable growth heuristic","expr":"g ≈ ROE × retention ratio","meaning":"Growth under stable leverage, ROE and dividend policy.","conditions":"Not guaranteed perpetual growth."}],"examples":[{"question_en":"A firm earns $15 million net income attributable to common and has average common book equity of $100 million. Its estimated cost of equity is 12%. What is ROE, and what does the comparison suggest?","steps_vi":["ROE=15/100=15%.","15% > 12%, potentially indicating accounting return above opportunity cost on this stylized measure."],"answer":"ROE 15%, versus cost of equity 12%","check":"Not sufficient to certify economic value creation without risk, accounting and capital-scope checks."}],"questions":[{"stem_en":"Accounting ROE is generally calculated using:","options":["Net income and common shareholders’ book equity","Stock price and required return","Dividends and risk-free rate only"],"correct":0,"why_vi":"ROE là accounting ratio.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Cost of equity primarily represents:","options":["A scheduled coupon paid on common shares","Investors’ opportunity cost for bearing equity risk","A tax-free return guaranteed by the exchange"],"correct":1,"why_vi":"Equity has required expected return, not contractual coupon.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A company with unusually high leverage may show high ROE because:","options":["Risk has been eliminated","Every additional dollar of debt raises net income without cost","Common book equity is a smaller residual base"],"correct":2,"why_vi":"Leverage magnifies ROE and downside risk.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Accounting ROE","back_vi":"ROE = net income available to common shareholders / average common shareholders' equity; phản ánh historical accounting performance, chịu leverage và accounting policies. Exam trap: ROE không phải realized shareholder return."},{"front_en":"Investor required return","back_vi":"Required return là compensation cần thiết cho time value và equity risk given alternatives; investor-specific constraints/tax views có thể tạo required returns khác nhau. Exam trap: Không lấy ROE làm r trực tiếp trong DDM."},{"front_en":"Company cost of equity","back_vi":"Cost of equity là opportunity cost doanh nghiệp phải cung cấp cho equity capital để tài trợ dự án có cùng mức rủi ro. Có thể được estimate qua CAPM hoặc approaches khác. Exam trap: Cost of equity không phải dividend yield đơn giản."},{"front_en":"ROE versus economic value","back_vi":"Project tạo value nếu risk-adjusted return trên capital cao hơn opportunity cost; high accounting ROE có thể do financial leverage chứ không nhất thiết chất lượng kinh doanh cao. Exam trap: ROE > cost of equity cần điều chỉnh risk và accounting scope."},{"front_en":"Retained earnings and growth","back_vi":"Retaining earnings thay vì dividend vẫn có opportunity cost; sustainable growth approximation g≈ROE×retention khi assumptions ổn định và no new equity. Exam trap: Không mặc định tăng growth luôn tăng value nếu reinvestment returns thấp."}]}]},{"module_id":"CFA26-05-05","module_title":"Company Analysis: Past and Present","subject":"Equity Investments","version":"3.8","qa_status":"SOURCE_GROUNDED_DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT","language":"Vietnamese explanatory notes; original English question stems and options","source_policy":"Original bilingual paraphrased lessons and original practice based on CFAI 2026 Equity Volume 5, module 5; primary PDF directly inspected; additional line-by-line editorial checks pending","los":[{"id":"CFA26-05-05-LOS01","letter":"5.a","title_en":"Company Research Report Structure","outcome_en":"describe the principal components of a comprehensive company research report","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM5 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM5 — Company Analysis: Past and Present","pages":"official outcomes at physical PDF p207; teaching chapter physical pp207–254"}],"sections":[{"heading":"Investment thesis and summary","body":"Research report phải nêu company, security, current valuation, investment view và catalysts/risks. Thesis cần liên kết business economics, forecast và estimated intrinsic value, không chỉ mô tả giá quá khứ.","trap":"Một recommendation không có investment horizon/risks khó sử dụng."},{"heading":"Business model and industry","body":"Mô tả products, customers, revenue model, economics, key suppliers, competitive advantage, industry demand và regulatory environment. Cross-check với segment disclosures và third-party market data.","trap":"Không coi management marketing claims là independent evidence."},{"heading":"Historical financial performance","body":"Phân tích income statement, balance sheet và cash flow qua nhiều kỳ, với quality/recurring nature của earnings, leverage, working capital và capital reinvestment. Normalize one-offs khi hợp lý.","trap":"EBIT tăng không nhất thiết cash conversion tốt."},{"heading":"Forecasts, valuation, recommendation","body":"Xây assumptions cho revenue, margins, working capital, capex, financing; chọn DCF/multiples/asset model phù hợp; giải thích target price, upside/downside và time horizon.","trap":"Price target không phải chắc chắn đạt được."},{"heading":"Risks and communication","body":"Viết sensitivity/scenarios, key risks, valuation evidence, limitations, sources, date và conflicts; thể hiện điều kiện khiến thesis sai. Phải phân biệt observed facts với analyst estimates.","trap":"Bài phân tích có thể đúng số nhưng thiếu risk disclosure."}],"formulas":[{"name":"Research workflow","expr":"Business analysis → historical quality → forecasts → valuation → recommendation and risk review","meaning":"Trình tự research nhất quán.","conditions":"Cần feedback loop nếu assumptions contradicted by evidence."},{"name":"Implied upside","expr":"Estimated price target/current price − 1","meaning":"Quy đổi target thành tỷ lệ upside mô hình.","conditions":"Before dividends, costs and uncertainty unless specified."}],"examples":[{"question_en":"A research note assigns a fair value of $60 to a stock currently trading at $50. Calculate implied price upside and state one necessary caveat.","steps_vi":["Implied upside = (60−50)/50 = 20%.","Cần xem investment horizon, dividends, uncertainties, catalysts và risks."],"answer":"20% implied price upside","check":"A price target is an analyst estimate rather than guaranteed return."}],"questions":[{"stem_en":"A comprehensive equity research report should ordinarily include:","options":["Investment thesis, analysis, valuation, and risks","Only a forecast share price","Only the latest press release"],"correct":0,"why_vi":"Full research connects valuation and risks.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Which assumption is most important to make explicit in a price target?","options":["The analyst’s favorite chart color","The forecast horizon and drivers","That valuation uncertainty is zero"],"correct":1,"why_vi":"Time frame and modeling assumptions essential.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Historical financial statements are most useful when they:","options":["Automatically determine the only possible future result","Remove the need for industry analysis","Inform operating drivers and forecasts after quality checks"],"correct":2,"why_vi":"History supports but does not dictate forecast.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Investment thesis and summary","back_vi":"Research report phải nêu company, security, current valuation, investment view và catalysts/risks. Thesis cần liên kết business economics, forecast và estimated intrinsic value, không chỉ mô tả giá quá khứ. Exam trap: Một recommendation không có investment horizon/risks khó sử dụng."},{"front_en":"Business model and industry","back_vi":"Mô tả products, customers, revenue model, economics, key suppliers, competitive advantage, industry demand và regulatory environment. Cross-check với segment disclosures và third-party market data. Exam trap: Không coi management marketing claims là independent evidence."},{"front_en":"Historical financial performance","back_vi":"Phân tích income statement, balance sheet và cash flow qua nhiều kỳ, với quality/recurring nature của earnings, leverage, working capital và capital reinvestment. Normalize one-offs khi hợp lý. Exam trap: EBIT tăng không nhất thiết cash conversion tốt."},{"front_en":"Forecasts, valuation, recommendation","back_vi":"Xây assumptions cho revenue, margins, working capital, capex, financing; chọn DCF/multiples/asset model phù hợp; giải thích target price, upside/downside và time horizon. Exam trap: Price target không phải chắc chắn đạt được."},{"front_en":"Risks and communication","back_vi":"Viết sensitivity/scenarios, key risks, valuation evidence, limitations, sources, date và conflicts; thể hiện điều kiện khiến thesis sai. Phải phân biệt observed facts với analyst estimates. Exam trap: Bài phân tích có thể đúng số nhưng thiếu risk disclosure."}]},{"id":"CFA26-05-05-LOS02","letter":"5.b","title_en":"Determining a Company Business Model","outcome_en":"identify and evaluate how a company creates, delivers, and captures value","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM5 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM5 — Company Analysis: Past and Present","pages":"official outcomes at physical PDF p207; teaching chapter physical pp207–254"}],"sections":[{"heading":"Value proposition and customers","body":"Xác định khách hàng trả tiền vì problem solved, product/service và differentiators. Phân khúc khách hàng cho biết concentration risk và khả năng price discrimination.","trap":"Doanh thu lớn chưa chứng minh unit economics có lợi."},{"heading":"Revenue capture mechanics","body":"Subscription, transaction fee, product sale, licensing, usage-based hoặc advertising có khác timing, gross/net recognition và predictability. Phải hiểu đơn vị đo cơ bản như subscribers, orders, price per unit.","trap":"Revenue model khác cash collection schedule."},{"heading":"Cost structure and unit economics","body":"Fixed versus variable costs, distribution channel, cost to acquire customer, retention, gross profit và contribution margin quyết định scalability. High fixed cost có operating leverage hai chiều.","trap":"High gross margin không đồng nghĩa positive free cash flow."},{"heading":"Competitive advantage and supply chain","body":"Network effects, switching costs, cost leadership, intangible assets, brand, regulation, IP và bargaining power tác động moat bền vững. Kiểm tra dependencies vào key supplier, platform hoặc input.","trap":"Moat có thể bị disruption và phản ứng cạnh tranh."},{"heading":"Evidence and red flags","body":"Triangulate annual report segments, management calls, customers, competitors và transactions; check revenue recognition, churn, related parties, one-time deals và structural changes.","trap":"Company narrative có thể không phản ánh economic substance."}],"formulas":[{"name":"Unit revenue framework","expr":"Revenue = customer count × transactions per customer × average revenue per transaction","meaning":"Phân rã drivers cho transaction businesses.","conditions":"Các metrics cần cùng kỳ và định nghĩa."},{"name":"Contribution margin","expr":"Revenue − variable costs","meaning":"Số tiền sau biến phí để bù fixed costs và profit.","conditions":"Không nhầm với net income."}],"examples":[{"question_en":"A subscription firm has 40,000 paying customers at $25 per month. If customers increase 10% with constant pricing, what is annual revenue after the increase?","steps_vi":["New customers=40,000×1.10=44,000.","Annual revenue=44,000×$25×12."],"answer":"$13.2 million","check":"Assumes every customer pays full year, zero churn and no deferred revenue effects."}],"questions":[{"stem_en":"A subscription business is most directly analyzed using:","options":["Only outstanding share count","Subscriber count, price, churn, and retention","Only property tax rates"],"correct":1,"why_vi":"Recurring revenue drivers relate to subscriber economics.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A firm with high fixed costs often has:","options":["Guaranteed lower business risk","No exposure to sales volume changes","Greater operating leverage"],"correct":2,"why_vi":"Fixed costs amplify operating profits to volume changes.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Customer concentration primarily creates:","options":["Revenue dependency and bargaining exposure","Elimination of default risk","Automatic price leadership"],"correct":0,"why_vi":"Major customer withdrawal can impact firm.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Value proposition and customers","back_vi":"Xác định khách hàng trả tiền vì problem solved, product/service và differentiators. Phân khúc khách hàng cho biết concentration risk và khả năng price discrimination. Exam trap: Doanh thu lớn chưa chứng minh unit economics có lợi."},{"front_en":"Revenue capture mechanics","back_vi":"Subscription, transaction fee, product sale, licensing, usage-based hoặc advertising có khác timing, gross/net recognition và predictability. Phải hiểu đơn vị đo cơ bản như subscribers, orders, price per unit. Exam trap: Revenue model khác cash collection schedule."},{"front_en":"Cost structure and unit economics","back_vi":"Fixed versus variable costs, distribution channel, cost to acquire customer, retention, gross profit và contribution margin quyết định scalability. High fixed cost có operating leverage hai chiều. Exam trap: High gross margin không đồng nghĩa positive free cash flow."},{"front_en":"Competitive advantage and supply chain","back_vi":"Network effects, switching costs, cost leadership, intangible assets, brand, regulation, IP và bargaining power tác động moat bền vững. Kiểm tra dependencies vào key supplier, platform hoặc input. Exam trap: Moat có thể bị disruption và phản ứng cạnh tranh."},{"front_en":"Evidence and red flags","back_vi":"Triangulate annual report segments, management calls, customers, competitors và transactions; check revenue recognition, churn, related parties, one-time deals và structural changes. Exam trap: Company narrative có thể không phản ánh economic substance."}]},{"id":"CFA26-05-05-LOS03","letter":"5.c","title_en":"Revenue and Pricing-Power Evaluation","outcome_en":"evaluate revenue drivers, mix, volumes, price, and ability to sustain pricing","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM5 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM5 — Company Analysis: Past and Present","pages":"official outcomes at physical PDF p207; teaching chapter physical pp207–254"}],"sections":[{"heading":"Bottom-up revenue analysis","body":"Estimate quantities and average price by geography/product/customer, then reconcile segment totals. Volume and price/mix changes should be separated; acquired revenue should not be misclassified as organic.","trap":"Total revenue growth can hide declining unit economics."},{"heading":"Top-down revenue analysis","body":"Begin industry total addressable market, growth and firm's share; forecast share gain/loss and price trends. Useful for macro-sensitive sectors but requires plausible market definition.","trap":"TAM is not firm's achievable revenue."},{"heading":"Pricing power","body":"Ability to raise prices above cost inflation without losing economically damaging demand volume; assessed via differentiation, elasticity, substitutes, switching costs and competitors.","trap":"Price increase alone is not proof of pricing power."},{"heading":"Revenue quality and mix","body":"Recurring vs nonrecurring, contract length, backlog, seasonality, customer retention, organic vs acquisition, and currency translation matter for forecast persistence.","trap":"Backlog may not convert to recognized revenue on expected dates."},{"heading":"Volume-price-mix bridge","body":"Revenue change comprises quantity, price, product/customer mix and FX/acquisitions as relevant. Reconcile drivers to stated total and monitor competitive response.","trap":"Applying volume growth and price growth as simple sum misses interaction."}],"formulas":[{"name":"Segment revenue","expr":"R = ∑(unit volume_i × realized price_i)","meaning":"Bottom-up revenue estimate across segments.","conditions":"Comparable quantity and price basis."},{"name":"Compound price-volume growth","expr":"(1+g_quantity)(1+g_price)−1","meaning":"Revenue growth before mix, FX and acquisitions.","conditions":"Price and volume changes assumed multiplicative."},{"name":"Top-down revenue","expr":"Firm revenue = industry revenue × firm market share","meaning":"Cross-check bottom-up with overall industry economics.","conditions":"Same market definition, period and currency."}],"examples":[{"question_en":"Units grow 12% and average realized price falls 3%, with unchanged mix. Compute the new revenue growth rate.","steps_vi":["Revenue multiplier=1.12×0.97=1.0864.","Revenue growth = 8.64%, not simply 9%."],"answer":"8.64%","check":"Ignoring FX, acquisitions, product mix and returns."}],"questions":[{"stem_en":"A company increases unit volume 5% and selling price 5%. Ignoring mix, revenue growth is:","options":["Exactly 10.00%","5.00%","10.25%"],"correct":2,"why_vi":"1.05×1.05−1=10.25%.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Strong pricing power is most consistent with:","options":["Retaining demand and margins after reasonable price increases","Permanent demand collapse after any price increase","Pricing below cost indefinitely"],"correct":0,"why_vi":"Price elasticity and differentiation matter.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Top-down revenue forecasting most directly uses:","options":["Only deferred tax liabilities","Industry size and market share","Only treasury stock changes"],"correct":1,"why_vi":"Industry × share maps to firm sales.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Bottom-up revenue analysis","back_vi":"Estimate quantities and average price by geography/product/customer, then reconcile segment totals. Volume and price/mix changes should be separated; acquired revenue should not be misclassified as organic. Exam trap: Total revenue growth can hide declining unit economics."},{"front_en":"Top-down revenue analysis","back_vi":"Begin industry total addressable market, growth and firm's share; forecast share gain/loss and price trends. Useful for macro-sensitive sectors but requires plausible market definition. Exam trap: TAM is not firm's achievable revenue."},{"front_en":"Pricing power","back_vi":"Ability to raise prices above cost inflation without losing economically damaging demand volume; assessed via differentiation, elasticity, substitutes, switching costs and competitors. Exam trap: Price increase alone is not proof of pricing power."},{"front_en":"Revenue quality and mix","back_vi":"Recurring vs nonrecurring, contract length, backlog, seasonality, customer retention, organic vs acquisition, and currency translation matter for forecast persistence. Exam trap: Backlog may not convert to recognized revenue on expected dates."},{"front_en":"Volume-price-mix bridge","back_vi":"Revenue change comprises quantity, price, product/customer mix and FX/acquisitions as relevant. Reconcile drivers to stated total and monitor competitive response. Exam trap: Applying volume growth and price growth as simple sum misses interaction."}]},{"id":"CFA26-05-05-LOS04","letter":"5.d","title_en":"Operating Profitability and Working Capital","outcome_en":"evaluate operating profit and operating working capital using relevant metrics","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM5 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM5 — Company Analysis: Past and Present","pages":"official outcomes at physical PDF p207; teaching chapter physical pp207–254"}],"sections":[{"heading":"Operating margins","body":"Gross margin, EBITDA margin và EBIT/operating margin giúp tách cost of goods sold, operating overhead, D&A. So sánh theo segment và qua chu kỳ, điều chỉnh one-time items.","trap":"EBITDA ignores capex and working capital needs."},{"heading":"Profitability drivers","body":"Product mix, price, input costs, labor, capacity utilization và SG&A efficiency quyết định margins; fixed costs amplify sales shocks. Compare peers only when accounting classifications aligned.","trap":"High margin không tự nghĩa low risk."},{"heading":"Operating working capital","body":"Receivables + inventory − payables là simplified noncash operating working capital; increased investment thường uses cash, còn release supports cash. Không trộn cash/debt financing vào working capital operating.","trap":"NWC tăng có thể tiêu thụ cash dù earnings tăng."},{"heading":"Cash conversion cycle","body":"DSO, DIO và DPO đo time cash tied up in operations; CCC=DSO+DIO−DPO. Seasonality và denominator conventions cần đồng nhất.","trap":"Negative CCC có thể là business model strength hoặc supplier pressure."},{"heading":"Quality and sustainability","body":"Xem receivable aging, inventory obsolescence, supplier terms và aggressive payment delays; revenue growth không chất lượng nếu receivables/inventory build quá nhanh.","trap":"Kéo dài DPO vô hạn không khả thi."}],"formulas":[{"name":"Operating margin","expr":"EBIT / revenue","meaning":"Profit từ operating activities trước interest and tax.","conditions":"Consistent EBIT classification across companies."},{"name":"Noncash operating working capital","expr":"Accounts receivable + inventory − accounts payable","meaning":"Simplified investment in operating current accounts.","conditions":"Extend to other operating current assets/liabilities as appropriate."},{"name":"Cash conversion cycle","expr":"DSO + DIO − DPO","meaning":"Thời gian tiền mặt bị khóa từ hàng tồn tới thu tiền.","conditions":"Turnover ratios measured on consistent annual/daily basis."}],"examples":[{"question_en":"A retailer has DSO of 20 days, DIO of 65 days, and DPO of 50 days. What is its cash conversion cycle?","steps_vi":["CCC = 20+65−50.","CCC = 35 days; shorter cycle generally means less time cash tied up."],"answer":"35 days","check":"Interpret relative to business model and supplier/customer arrangements."}],"questions":[{"stem_en":"An increase in accounts receivable, all else equal, usually:","options":["Uses operating cash","Releases operating cash","Reduces recorded revenue automatically"],"correct":0,"why_vi":"More sales not yet collected ties up cash.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"If DSO is 30, DIO is 50, and DPO is 40 days, CCC equals:","options":["120 days","40 days","20 days"],"correct":1,"why_vi":"CCC=30+50−40=40.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Which ratio most directly measures operating profit before interest and tax relative to sales?","options":["Current ratio","Debt-to-equity ratio","EBIT margin"],"correct":2,"why_vi":"EBIT margin=EBIT/revenue.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Operating margins","back_vi":"Gross margin, EBITDA margin và EBIT/operating margin giúp tách cost of goods sold, operating overhead, D&A. So sánh theo segment và qua chu kỳ, điều chỉnh one-time items. Exam trap: EBITDA ignores capex and working capital needs."},{"front_en":"Profitability drivers","back_vi":"Product mix, price, input costs, labor, capacity utilization và SG&A efficiency quyết định margins; fixed costs amplify sales shocks. Compare peers only when accounting classifications aligned. Exam trap: High margin không tự nghĩa low risk."},{"front_en":"Operating working capital","back_vi":"Receivables + inventory − payables là simplified noncash operating working capital; increased investment thường uses cash, còn release supports cash. Không trộn cash/debt financing vào working capital operating. Exam trap: NWC tăng có thể tiêu thụ cash dù earnings tăng."},{"front_en":"Cash conversion cycle","back_vi":"DSO, DIO và DPO đo time cash tied up in operations; CCC=DSO+DIO−DPO. Seasonality và denominator conventions cần đồng nhất. Exam trap: Negative CCC có thể là business model strength hoặc supplier pressure."},{"front_en":"Quality and sustainability","back_vi":"Xem receivable aging, inventory obsolescence, supplier terms và aggressive payment delays; revenue growth không chất lượng nếu receivables/inventory build quá nhanh. Exam trap: Kéo dài DPO vô hạn không khả thi."}]},{"id":"CFA26-05-05-LOS05","letter":"5.e","title_en":"Capital Investment and Capital Structure","outcome_en":"evaluate a company’s capital investments, funding mix, leverage, and sustainability","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM5 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM5 — Company Analysis: Past and Present","pages":"official outcomes at physical PDF p207; teaching chapter physical pp207–254"}],"sections":[{"heading":"Capital investment needs","body":"Maintenance capex thay thế assets; growth capex mở rộng capacity/products. Capex phải gắn với projected demand, utilization, life cycles và incremental return on invested capital.","trap":"Capex tăng có thể là investment hoặc catch-up maintenance."},{"heading":"Asset intensity and reinvestment","body":"Asset turnover, depreciation vs capex và PP&E trends cho biết nhu cầu tài sản; asset-light businesses có thể invest trong R&D hoặc customer acquisition không ghi PP&E.","trap":"Book capex thấp không chứng minh reinvestment thấp."},{"heading":"Capital structure composition","body":"Debt, preferred, equity và lease obligations có maturity, costs, covenants, security và priority khác nhau. Debt-to-capital hoặc debt/EBITDA cần interpretation theo business cyclicality.","trap":"Lease liabilities có thể quan trọng khi đánh giá leverage."},{"heading":"Debt capacity and servicing","body":"Interest coverage, cash flow/debt, maturity profile và refinancing conditions quyết định financial flexibility. Distinguish EBITDA from cash actually available to repay debt.","trap":"EBIT/interest coverage không thay cho liquidity analysis."},{"heading":"Allocation of capital","body":"Management phân tiền giữa acquisitions, organic investment, buybacks, debt reduction, dividends; monitor investment returns versus cost of capital và incentives.","trap":"Share repurchases không tự luôn accretive về intrinsic value."}],"formulas":[{"name":"Interest coverage","expr":"EBIT / interest expense","meaning":"Cushion operating income gives for interest obligations.","conditions":"Does not capture debt principal repayments or capex."},{"name":"Net investment","expr":"Capital expenditures − depreciation","meaning":"Approximate growth in fixed operating asset base absent disposals/acquisitions.","conditions":"Accounting approximation only."},{"name":"Debt to capital","expr":"Debt / (debt + common and preferred equity)","meaning":"Financing mix at book or market values as specified.","conditions":"Do not mix book debt with market equity without labeling."}],"examples":[{"question_en":"A firm reports EBIT of $120 million and interest expense of $30 million. What is EBIT interest coverage?","steps_vi":["120 / 30 = 4.0.","Compare with peers and historical volatility; does not guarantee refinancing ability."],"answer":"4.0×","check":"Excludes principal repayment, cash taxes, capex and working capital."}],"questions":[{"stem_en":"Interest coverage most directly compares:","options":["Cash with accounts receivable","EBIT with interest expense","Revenue with inventory only"],"correct":1,"why_vi":"EBIT/interest expense assesses interest servicing.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Which use of cash is most likely a growth investment?","options":["Paying a previously declared ordinary dividend","Buying back existing shares at market price","Expanding production capacity for forecast demand"],"correct":2,"why_vi":"New production capacity constitutes operational investment.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A company’s debt maturity schedule matters because it:","options":["Affects refinancing and liquidity risk","Determines the exact market P/E","Guarantees debt will never default"],"correct":0,"why_vi":"Timing of obligations determines liquidity pressure.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Capital investment needs","back_vi":"Maintenance capex thay thế assets; growth capex mở rộng capacity/products. Capex phải gắn với projected demand, utilization, life cycles và incremental return on invested capital. Exam trap: Capex tăng có thể là investment hoặc catch-up maintenance."},{"front_en":"Asset intensity and reinvestment","back_vi":"Asset turnover, depreciation vs capex và PP&E trends cho biết nhu cầu tài sản; asset-light businesses có thể invest trong R&D hoặc customer acquisition không ghi PP&E. Exam trap: Book capex thấp không chứng minh reinvestment thấp."},{"front_en":"Capital structure composition","back_vi":"Debt, preferred, equity và lease obligations có maturity, costs, covenants, security và priority khác nhau. Debt-to-capital hoặc debt/EBITDA cần interpretation theo business cyclicality. Exam trap: Lease liabilities có thể quan trọng khi đánh giá leverage."},{"front_en":"Debt capacity and servicing","back_vi":"Interest coverage, cash flow/debt, maturity profile và refinancing conditions quyết định financial flexibility. Distinguish EBITDA from cash actually available to repay debt. Exam trap: EBIT/interest coverage không thay cho liquidity analysis."},{"front_en":"Allocation of capital","back_vi":"Management phân tiền giữa acquisitions, organic investment, buybacks, debt reduction, dividends; monitor investment returns versus cost of capital và incentives. Exam trap: Share repurchases không tự luôn accretive về intrinsic value."}]}]},{"module_id":"CFA26-05-06","module_title":"Industry and Competitive Analysis","subject":"Equity Investments","version":"3.8","qa_status":"SOURCE_GROUNDED_DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT","language":"Vietnamese explanatory notes; original English question stems and options","source_policy":"Original bilingual paraphrased lessons and original practice based on CFAI 2026 Equity Volume 5, module 6; primary PDF directly inspected; additional line-by-line editorial checks pending","los":[{"id":"CFA26-05-06-LOS01","letter":"6.a","title_en":"Purpose and Process of Industry Analysis","outcome_en":"describe the objectives and sequence of industry and competitive analysis","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM6 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM6 — Industry and Competitive Analysis","pages":"official outcomes at physical PDF p255; teaching chapter physical pp255–294"}],"sections":[{"heading":"Why analyze industries","body":"Industry structure ảnh hưởng demand growth, margins, ROIC, cyclicality và value creation. Tách company-specific performance khỏi tailwind/headwind của industry để forecast có cơ sở.","trap":"Một công ty tăng trưởng cùng thị trường không nhất thiết giành share."},{"heading":"Define relevant industry","body":"Xác định economic substitutes, customer job-to-be-done, geography, channel và regulatory boundaries. Companies đa ngành có thể cần segment-level analysis thay vì single industry label.","trap":"Administrative classification không luôn trùng competitive market."},{"heading":"Survey industry economics","body":"Ước tính size, market growth, concentration, profitability, investment intensity, cash generation và growth lifecycle. Sử dụng comparable data và điều chỉnh disruptions.","trap":"Industry revenue growth không tự kéo theo profitability."},{"heading":"Analyze structure and context","body":"Porter Five Forces để hiểu competitive economics; PESTLE để hiểu external macro drivers; technology và regulation ảnh hưởng cả forces lẫn opportunity.","trap":"Các framework hỗ trợ phân tích, không thay số liệu."},{"heading":"Translate to valuation","body":"Xây firm relative positioning, sustainable advantage, margins, growth, capital needs và risk scenarios; track leading indicators và evidence trái thesis.","trap":"Forecast công ty phải reconcile với industry constraints."}],"formulas":[{"name":"Industry analysis chain","expr":"Define scope → quantify economics → evaluate forces and environment → position firms → forecast","meaning":"Quy trình kiểm tra logic giữa macro/industry/firm.","conditions":"Iterative if peers or substitute boundaries change."},{"name":"Relative growth decomposition","expr":"Company revenue growth ≈ industry growth + market-share contribution + mix/FX effects","meaning":"Heuristic phân rã.","conditions":"Use multiplicative share × industry level for exact projection."}],"examples":[{"question_en":"An industry’s revenue grows 6% and a company’s revenue grows 6% with stable product mix. What is the simplest inference about market share?","steps_vi":["Assuming same market perimeter and periods, company sales and industry sales grow at same rate.","Share ratio remains approximately constant."],"answer":"Market share is approximately unchanged","check":"Differences in FX, acquisitions and product mix can alter inference."}],"questions":[{"stem_en":"The primary use of industry analysis for equity valuation is to:","options":["Replace all issuer financial statements","Inform sustainable company growth and profitability assumptions","Guarantee future investment returns"],"correct":1,"why_vi":"Industry economics constrain company forecasts.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Analyzing a conglomerate often requires:","options":["Using only headquarters’ legal registration","Ignoring separate product markets","Segment-level industry classification"],"correct":2,"why_vi":"Multi-industry exposure needs breakdown.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Industry growth and a company’s market-share change are:","options":["Distinct revenue drivers","Identical by definition","Unrelated to company sales"],"correct":0,"why_vi":"Company revenue=industry size×share.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Why analyze industries","back_vi":"Industry structure ảnh hưởng demand growth, margins, ROIC, cyclicality và value creation. Tách company-specific performance khỏi tailwind/headwind của industry để forecast có cơ sở. Exam trap: Một công ty tăng trưởng cùng thị trường không nhất thiết giành share."},{"front_en":"Define relevant industry","back_vi":"Xác định economic substitutes, customer job-to-be-done, geography, channel và regulatory boundaries. Companies đa ngành có thể cần segment-level analysis thay vì single industry label. Exam trap: Administrative classification không luôn trùng competitive market."},{"front_en":"Survey industry economics","back_vi":"Ước tính size, market growth, concentration, profitability, investment intensity, cash generation và growth lifecycle. Sử dụng comparable data và điều chỉnh disruptions. Exam trap: Industry revenue growth không tự kéo theo profitability."},{"front_en":"Analyze structure and context","back_vi":"Porter Five Forces để hiểu competitive economics; PESTLE để hiểu external macro drivers; technology và regulation ảnh hưởng cả forces lẫn opportunity. Exam trap: Các framework hỗ trợ phân tích, không thay số liệu."},{"front_en":"Translate to valuation","back_vi":"Xây firm relative positioning, sustainable advantage, margins, growth, capital needs và risk scenarios; track leading indicators và evidence trái thesis. Exam trap: Forecast công ty phải reconcile với industry constraints."}]},{"id":"CFA26-05-06-LOS02","letter":"6.b","title_en":"Industry Classification and Peer Groups","outcome_en":"describe industry grouping methods and their advantages and limitations","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM6 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM6 — Industry and Competitive Analysis","pages":"official outcomes at physical PDF p255; teaching chapter physical pp255–294"}],"sections":[{"heading":"Product or service similarity","body":"Group companies bằng sản phẩm cung cấp, use cases, customers và substitutes. Useful for direct competitor analysis nhưng hybrid firms hoặc platform firms khó gắn một nhóm.","trap":"Similar accounting labels không đủ chứng minh competitive substitutability."},{"heading":"Third-party sector classifications","body":"Các hệ thống như GICS, ICB hoặc industry databases nhóm issuers theo methodology; giúp benchmark và data comparability. Classification rules, review dates và revenue-based focus khác nhau.","trap":"GICS sector label không thay thế business due diligence."},{"heading":"Geographic and value-chain grouping","body":"Competitors có thể khác theo location, price tier, distribution channel hoặc supply-chain stage; nhóm primary producers khác downstream retailers về economics.","trap":"Peer same country nhưng khác profit pool có thể không comparable."},{"heading":"Classification by economic traits","body":"Cyclical/defensive, growth/mature, asset-intensive/asset-light, regulated/nonregulated gợi insight về factors nhưng là lớp phân tích bổ sung.","trap":"Không xem style phân nhóm là mutually exclusive."},{"heading":"Peer set quality","body":"Chọn peers theo segment mix, accounting, revenue currency, size, capital structure và operating model; explain adjustments và outliers.","trap":"Peer multiple trung bình vô nghĩa nếu business models quá khác."}],"formulas":[{"name":"Segment exposure","expr":"Weighted group exposure ≈ ∑(segment revenue_i/total revenue × industry group_i)","meaning":"Khung phân bổ exposure đa ngành.","conditions":"Revenue weights are not automatically profit or asset weights."},{"name":"Peer selection process","expr":"Business similarity → geography → accounting consistency → capital intensity → valuation applicability","meaning":"Rà soát nhóm comps.","conditions":"Peer groups require judgment and may evolve."}],"examples":[{"question_en":"A conglomerate earns 70% of revenue from cloud services and 30% from consumer electronics. Why might a single-sector peer multiple mislead?","steps_vi":["Hai mảng có margin, growth, capex và risk khác nhau.","Valuing each segment against a suitable peer group may better reflect business economics."],"answer":"Different segments require distinct industry comparables.","check":"Revenue weights alone may not capture value contribution."}],"questions":[{"stem_en":"GICS is primarily used to:","options":["Calculate exact intrinsic value","Set central bank interest rates","Group companies into industry and sector categories"],"correct":2,"why_vi":"Industry classification supports peer/benchmark analysis.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A company with several disparate business segments is often best evaluated using:","options":["Segment-specific peer groups","One arbitrary company-wide peer irrespective of business mix","No financial analysis"],"correct":0,"why_vi":"Segment economics differ.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A useful peer set ideally controls for:","options":["Identical stock ticker lengths","Similar operating models and financial reporting conventions","Exactly the same dividend per share"],"correct":1,"why_vi":"Comparability improves analysis.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Product or service similarity","back_vi":"Group companies bằng sản phẩm cung cấp, use cases, customers và substitutes. Useful for direct competitor analysis nhưng hybrid firms hoặc platform firms khó gắn một nhóm. Exam trap: Similar accounting labels không đủ chứng minh competitive substitutability."},{"front_en":"Third-party sector classifications","back_vi":"Các hệ thống như GICS, ICB hoặc industry databases nhóm issuers theo methodology; giúp benchmark và data comparability. Classification rules, review dates và revenue-based focus khác nhau. Exam trap: GICS sector label không thay thế business due diligence."},{"front_en":"Geographic and value-chain grouping","back_vi":"Competitors có thể khác theo location, price tier, distribution channel hoặc supply-chain stage; nhóm primary producers khác downstream retailers về economics. Exam trap: Peer same country nhưng khác profit pool có thể không comparable."},{"front_en":"Classification by economic traits","back_vi":"Cyclical/defensive, growth/mature, asset-intensive/asset-light, regulated/nonregulated gợi insight về factors nhưng là lớp phân tích bổ sung. Exam trap: Không xem style phân nhóm là mutually exclusive."},{"front_en":"Peer set quality","back_vi":"Chọn peers theo segment mix, accounting, revenue currency, size, capital structure và operating model; explain adjustments và outliers. Exam trap: Peer multiple trung bình vô nghĩa nếu business models quá khác."}]},{"id":"CFA26-05-06-LOS03","letter":"6.c","title_en":"Industry Size, Growth, and Profitability","outcome_en":"determine industry market size, growth, profitability and market-share trends","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM6 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM6 — Industry and Competitive Analysis","pages":"official outcomes at physical PDF p255; teaching chapter physical pp255–294"}],"sections":[{"heading":"Market sizing","body":"Total addressable market cần định nghĩa price/volume, geography và product boundaries, đo industry revenue ở cùng currency/period. Units × average industry selling price tạo cross-check.","trap":"TAM claim của management dễ phóng đại nếu inclusion quá rộng."},{"heading":"Growth stages","body":"Emerging/high-growth, consolidation, mature và declining industries có demand patterns, capex và competitive responses khác nhau. Lifecycle không cứng nhắc, innovation có thể đảo chiều.","trap":"Mature industry vẫn có pockets of growth."},{"heading":"Share and concentration","body":"Market share bằng company sales/defined industry sales; tập trung thị trường đánh giá qua top firms' shares hoặc HHI. High concentration đôi khi hỗ trợ pricing nhưng còn phụ thuộc entry/substitutes.","trap":"HHI là concentration indicator, không trực tiếp monopoly profit."},{"heading":"Industry profitability","body":"Operating margins, ROIC so với cost of capital, cash conversion và margin dispersion qua chu kỳ cho thấy industry attractiveness. Growth cao có thể đi với returns thấp do rivalry.","trap":"High revenue growth != economic profit."},{"heading":"Trend decomposition and risks","body":"Mix/FX/acquisitions, substitution, regulation, cyclicality, capacity growth và pricing determine industry outlook. Verify historical data and forward indicators rather than straight-line extrapolation.","trap":"Một năm boom không đại diện long-run demand."}],"formulas":[{"name":"Market share","expr":"Company sales / total relevant industry sales","meaning":"Tỷ trọng doanh thu theo market perimeter.","conditions":"Comparable products, periods and currencies."},{"name":"Industry growth","expr":"(Industry size_t / Industry size_(t−1)) − 1","meaning":"Tốc độ tăng industry sales giữa hai kỳ.","conditions":"Adjust for nominal prices/FX when appropriate."},{"name":"HHI concentration","expr":"HHI = ∑(market share %)^2","meaning":"Đo concentration dựa market shares percent.","conditions":"Interpretation varies by jurisdiction and market definition."}],"examples":[{"question_en":"Four firms have industry shares of 40%, 30%, 20%, and 10%. Calculate the Herfindahl–Hirschman Index using percentage shares.","steps_vi":["HHI=40²+30²+20²+10².","=1,600+900+400+100."],"answer":"3,000","check":"Illustrates concentration, not a standalone profitability forecast."}],"questions":[{"stem_en":"An industry has $200 billion sales and a company has $10 billion sales. The company’s market share is:","options":["5%","10%","20%"],"correct":0,"why_vi":"10/200=5%.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Industry concentration is often assessed using:","options":["The coupon rate of a bond","The Herfindahl–Hirschman Index","Earnings per share alone"],"correct":1,"why_vi":"HHI sums squared market shares.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"An industry with strong revenue growth but intense price competition may have:","options":["Guaranteed increasing ROIC","No capital expenditure needs","Weak or declining profitability"],"correct":2,"why_vi":"Revenue growth and profitability separate.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Market sizing","back_vi":"Total addressable market cần định nghĩa price/volume, geography và product boundaries, đo industry revenue ở cùng currency/period. Units × average industry selling price tạo cross-check. Exam trap: TAM claim của management dễ phóng đại nếu inclusion quá rộng."},{"front_en":"Growth stages","back_vi":"Emerging/high-growth, consolidation, mature và declining industries có demand patterns, capex và competitive responses khác nhau. Lifecycle không cứng nhắc, innovation có thể đảo chiều. Exam trap: Mature industry vẫn có pockets of growth."},{"front_en":"Share and concentration","back_vi":"Market share bằng company sales/defined industry sales; tập trung thị trường đánh giá qua top firms' shares hoặc HHI. High concentration đôi khi hỗ trợ pricing nhưng còn phụ thuộc entry/substitutes. Exam trap: HHI là concentration indicator, không trực tiếp monopoly profit."},{"front_en":"Industry profitability","back_vi":"Operating margins, ROIC so với cost of capital, cash conversion và margin dispersion qua chu kỳ cho thấy industry attractiveness. Growth cao có thể đi với returns thấp do rivalry. Exam trap: High revenue growth != economic profit."},{"front_en":"Trend decomposition and risks","back_vi":"Mix/FX/acquisitions, substitution, regulation, cyclicality, capacity growth và pricing determine industry outlook. Verify historical data and forward indicators rather than straight-line extrapolation. Exam trap: Một năm boom không đại diện long-run demand."}]},{"id":"CFA26-05-06-LOS04","letter":"6.d","title_en":"Porter Five Forces and PESTLE","outcome_en":"analyze industry structure and external trends using competitive forces and PESTLE","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM6 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM6 — Industry and Competitive Analysis","pages":"official outcomes at physical PDF p255; teaching chapter physical pp255–294"}],"sections":[{"heading":"Rivalry among incumbents","body":"Firms cạnh tranh price, service, product innovation, distribution; high fixed costs, low differentiation và slow demand growth có thể tăng rivalry.","trap":"Market concentration alone không quyết định rivalry intensity."},{"heading":"Supplier and buyer bargaining","body":"Few suppliers with scarce inputs or high switching costs có supplier power; concentrated customers with low switching costs tạo buyer power, compress margins.","trap":"Customer và supplier power không luôn tương quan ngược."},{"heading":"Threat of entrants and substitutes","body":"Entrants bị ngăn bởi capital needs, scale, network effects, brand và regulation; substitutes khác category có thể cùng solve customer need.","trap":"Substitute khác direct rival; low entry không luôn đủ profitability."},{"heading":"PESTLE context","body":"Political, Economic, Social, Technological, Legal, Environmental drivers làm thay đổi demand, cost, rules và risks. Dùng causal mapping từ macro events tới cụ thể forecasts.","trap":"PESTLE list chỉ là checklist nếu không có materiality assessment."},{"heading":"Dynamic interpretation","body":"Forces và environment tương tác: new technology lowers barriers, regulations cap prices, climate standards raise investment needs. Assess relative changes và scenario uncertainty.","trap":"Competitive landscape changes; framework không nên đóng băng."}],"formulas":[{"name":"Porter framework","expr":"Rivalry + entry threat + substitute threat + supplier power + buyer power","meaning":"Năm lực cạnh tranh tác động industry returns.","conditions":"Qualitative structure, not a numerical sum of scores."},{"name":"PESTLE","expr":"Political, Economic, Social, Technological, Legal, Environmental","meaning":"Sáu nhóm drivers external.","conditions":"Each factor needs company-specific translation."}],"examples":[{"question_en":"A software vendor has very high customer switching costs but depends on one unique cloud infrastructure supplier. Identify two forces.","steps_vi":["Customer switching costs may reduce buyer bargaining power.","Concentrated essential cloud supplier can have high bargaining power."],"answer":"Potentially weaker buyer power but stronger supplier power","check":"Relative strength depends on substitutes and contractual flexibility."}],"questions":[{"stem_en":"A dominant input provider can most directly increase:","options":["Buyers’ switching costs in every case","Supplier bargaining power","The number of substitutes automatically"],"correct":1,"why_vi":"Supplier concentration can pressure downstream margin.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Which item belongs to PESTLE rather than Porter’s Five Forces?","options":["Bargaining power of buyers","Threat of new entrants","An environmental emissions regulation"],"correct":2,"why_vi":"Environmental/legal external context is PESTLE.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A streaming service competing with cinema entertainment may create which force for cinemas?","options":["Threat of substitutes","Supplier bargaining power only","No competitive force"],"correct":0,"why_vi":"Different service solves similar consumption need.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Rivalry among incumbents","back_vi":"Firms cạnh tranh price, service, product innovation, distribution; high fixed costs, low differentiation và slow demand growth có thể tăng rivalry. Exam trap: Market concentration alone không quyết định rivalry intensity."},{"front_en":"Supplier and buyer bargaining","back_vi":"Few suppliers with scarce inputs or high switching costs có supplier power; concentrated customers with low switching costs tạo buyer power, compress margins. Exam trap: Customer và supplier power không luôn tương quan ngược."},{"front_en":"Threat of entrants and substitutes","back_vi":"Entrants bị ngăn bởi capital needs, scale, network effects, brand và regulation; substitutes khác category có thể cùng solve customer need. Exam trap: Substitute khác direct rival; low entry không luôn đủ profitability."},{"front_en":"PESTLE context","back_vi":"Political, Economic, Social, Technological, Legal, Environmental drivers làm thay đổi demand, cost, rules và risks. Dùng causal mapping từ macro events tới cụ thể forecasts. Exam trap: PESTLE list chỉ là checklist nếu không có materiality assessment."},{"front_en":"Dynamic interpretation","back_vi":"Forces và environment tương tác: new technology lowers barriers, regulations cap prices, climate standards raise investment needs. Assess relative changes và scenario uncertainty. Exam trap: Competitive landscape changes; framework không nên đóng băng."}]},{"id":"CFA26-05-06-LOS05","letter":"6.e","title_en":"Competitive Strategy and Position","outcome_en":"evaluate a firm’s competitive strategy and its position versus peers","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM6 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM6 — Industry and Competitive Analysis","pages":"official outcomes at physical PDF p255; teaching chapter physical pp255–294"}],"sections":[{"heading":"Cost leadership","body":"Low unit costs từ scale, procurement, automation, operations giúp firm charge low price hoặc earn higher margin; maintain advantage only nếu competitors khó replicate.","trap":"Low price không nhất thiết low cost."},{"heading":"Differentiation","body":"Brand, technology, service, network effects và customer integration giúp price premium hoặc loyalty; must exceed incremental costs of differentiation.","trap":"Premium brand có thể lose power khi substitute emerges."},{"heading":"Focus or niche","body":"Firm tập trung segment/region với tailored offerings; có thể defend specialized customer base nhưng chịu concentration và market-size risks.","trap":"Niche firm có thể không scale toàn industry."},{"heading":"Measures of competitive position","body":"Relative market share, margins, retention, ROIC, product quality, distribution, R&D efficiency và pricing evidence giúp test moat. Compare over cycle, not a single quarter.","trap":"Market share cao không chứng minh shareholder value creation."},{"heading":"Strategic sustainability","body":"Evaluate sources of advantage, management execution, response to disruption, barriers to imitation và reinvestment required. Map strengths/weaknesses to valuation drivers and downside scenarios.","trap":"Strategy analysis phải chuyển thành revenue, margins, capex và risk inputs."}],"formulas":[{"name":"Economic profit heuristic","expr":"Economic profit ≈ NOPAT − (invested capital × WACC)","meaning":"Profit vượt required return trên invested capital.","conditions":"Capital definitions and tax/industry conventions matter."},{"name":"Relative operating spread","expr":"Firm operating margin − peer group comparable margin","meaning":"Dấu hiệu cạnh tranh về profitability.","conditions":"Adjust mix, leverage below EBIT and accounting."}],"examples":[{"question_en":"A company earns $120m NOPAT on $1 billion invested capital with a 10% WACC. Estimate economic profit.","steps_vi":["Capital charge=1,000×10%=$100m.","Economic profit = 120−100 = $20m."],"answer":"$20 million","check":"Simplified EVA-style calculation; requires consistent capital and tax definitions."}],"questions":[{"stem_en":"Cost leadership is most directly based on:","options":["Always charging the highest price","Having the longest company name","Sustaining lower comparable unit costs"],"correct":2,"why_vi":"Lower unit costs create competitive options.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Differentiation can support value when:","options":["Customers pay sufficient premiums relative to incremental costs","Every competitor has identical products","Unit economics are irrelevant"],"correct":0,"why_vi":"Willingness to pay must exceed cost.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A durable competitive advantage is most directly indicated by:","options":["A single unusually profitable quarter","Persistent superior risk-adjusted returns on capital with defendable drivers","Strong revenue growth without regard to capital invested"],"correct":1,"why_vi":"Sustainable economics over cycle matter.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Cost leadership","back_vi":"Low unit costs từ scale, procurement, automation, operations giúp firm charge low price hoặc earn higher margin; maintain advantage only nếu competitors khó replicate. Exam trap: Low price không nhất thiết low cost."},{"front_en":"Differentiation","back_vi":"Brand, technology, service, network effects và customer integration giúp price premium hoặc loyalty; must exceed incremental costs of differentiation. Exam trap: Premium brand có thể lose power khi substitute emerges."},{"front_en":"Focus or niche","back_vi":"Firm tập trung segment/region với tailored offerings; có thể defend specialized customer base nhưng chịu concentration và market-size risks. Exam trap: Niche firm có thể không scale toàn industry."},{"front_en":"Measures of competitive position","back_vi":"Relative market share, margins, retention, ROIC, product quality, distribution, R&D efficiency và pricing evidence giúp test moat. Compare over cycle, not a single quarter. Exam trap: Market share cao không chứng minh shareholder value creation."},{"front_en":"Strategic sustainability","back_vi":"Evaluate sources of advantage, management execution, response to disruption, barriers to imitation và reinvestment required. Map strengths/weaknesses to valuation drivers and downside scenarios. Exam trap: Strategy analysis phải chuyển thành revenue, margins, capex và risk inputs."}]}]},{"module_id":"CFA26-05-07","module_title":"Company Analysis: Forecasting","subject":"Equity Investments","version":"3.8","qa_status":"SOURCE_GROUNDED_DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT","language":"Vietnamese explanatory notes; original English question stems and options","source_policy":"Original bilingual paraphrased lessons and original practice based on CFAI 2026 Equity Volume 5, module 7; primary PDF directly inspected; additional line-by-line editorial checks pending","los":[{"id":"CFA26-05-07-LOS01","letter":"7.a","title_en":"Financial Forecasting Framework","outcome_en":"explain forecasting objects, methods, time horizons and consistency checks","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM7 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM7 — Company Analysis: Forecasting","pages":"official outcomes at physical PDF p295; teaching chapter physical pp295–344"}],"sections":[{"heading":"What to forecast","body":"Forecast drivers, individual statement items, summary measures hoặc ad hoc measures tùy available data và explanatory power. Drivers giúp trace economic mechanism; direct line-item forecasts đơn giản khi data hạn chế.","trap":"Complex model không tự đáng tin hơn model đơn giản."},{"heading":"Forecasting methods","body":"Historical trends, base rates/reversion, management guidance, bottom-up and top-down analysis, analyst judgement có ưu nhược. Guidance cần independent plausibility check.","trap":"Không extrapolate cyclical peak indefinitely."},{"heading":"Forecast horizon","body":"Chọn horizon dựa business/industry cycles, competitive transition, investor mandate và thời điểm company đạt normalized steady state. Explicit forecast period phải hỗ trợ terminal value.","trap":"Terminal assumptions thường chi phối DCF nếu horizon ngắn."},{"heading":"Three-statement integration","body":"Forecast sales/margins ảnh hưởng net income; working capital/capex ảnh hưởng cash flow; cash and borrowing flow qua balance sheet. Check cash bridge and balance sheet reconciliation.","trap":"Revenue forecast tốt chưa đủ nếu cash funding không cân."},{"heading":"Scenarios and controls","body":"Xây assumptions documented, base/bull/bear, driver sensitivities và actual-vs-forecast review. Không trộn nominal growth với real discount rates hoặc currency definitions.","trap":"Scenario probabilities cần justification, không phải trang trí."}],"formulas":[{"name":"Balance sheet identity","expr":"Forecast assets = forecast liabilities + forecast equity","meaning":"Consistency check across statements.","conditions":"All cash/debt/equity plugs need transparent treatment."},{"name":"Forecast object hierarchy","expr":"Economic drivers → accounting line items → summary KPIs → value","meaning":"Logic từ operating assumptions tới valuation.","conditions":"Avoid double-counting drivers."}],"examples":[{"question_en":"A company’s revenue and margins are forecast to grow while receivables and inventory also rise sharply. What forecast check is most important?","steps_vi":["Growth có thể tiêu thụ cash through working capital.","Link income, balance sheet and cash-flow forecasts to see funding needs."],"answer":"Integrate working capital and financing needs into the three statements.","check":"Income growth is not identical to cash generation."}],"questions":[{"stem_en":"Which is an example of a forecast driver rather than a forecast financial-statement line item?","options":["Reported total revenue","Year-end total assets","Unit sales volume"],"correct":2,"why_vi":"Unit volume drives revenue line.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"The forecast horizon should primarily reflect:","options":["Business economics, cycles, and valuation needs","A fixed universal number of years for every firm","The number of directors alone"],"correct":0,"why_vi":"Time horizon chosen based on context.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A three-statement model should always satisfy:","options":["Forecast dividends equal forecast revenue","Assets equal liabilities plus equity","Operating cash flow equals net income every year"],"correct":1,"why_vi":"Balance sheet reconciliation essential.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"What to forecast","back_vi":"Forecast drivers, individual statement items, summary measures hoặc ad hoc measures tùy available data và explanatory power. Drivers giúp trace economic mechanism; direct line-item forecasts đơn giản khi data hạn chế. Exam trap: Complex model không tự đáng tin hơn model đơn giản."},{"front_en":"Forecasting methods","back_vi":"Historical trends, base rates/reversion, management guidance, bottom-up and top-down analysis, analyst judgement có ưu nhược. Guidance cần independent plausibility check. Exam trap: Không extrapolate cyclical peak indefinitely."},{"front_en":"Forecast horizon","back_vi":"Chọn horizon dựa business/industry cycles, competitive transition, investor mandate và thời điểm company đạt normalized steady state. Explicit forecast period phải hỗ trợ terminal value. Exam trap: Terminal assumptions thường chi phối DCF nếu horizon ngắn."},{"front_en":"Three-statement integration","back_vi":"Forecast sales/margins ảnh hưởng net income; working capital/capex ảnh hưởng cash flow; cash and borrowing flow qua balance sheet. Check cash bridge and balance sheet reconciliation. Exam trap: Revenue forecast tốt chưa đủ nếu cash funding không cân."},{"front_en":"Scenarios and controls","back_vi":"Xây assumptions documented, base/bull/bear, driver sensitivities và actual-vs-forecast review. Không trộn nominal growth với real discount rates hoặc currency definitions. Exam trap: Scenario probabilities cần justification, không phải trang trí."}]},{"id":"CFA26-05-07-LOS02","letter":"7.b","title_en":"Revenue Forecasting Approaches","outcome_en":"explain top-down and bottom-up approaches to forecasting company revenue","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM7 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM7 — Company Analysis: Forecasting","pages":"official outcomes at physical PDF p295; teaching chapter physical pp295–344"}],"sections":[{"heading":"Bottom-up price and volume","body":"Forecast each product/segment's units, customers, transactions and realized price, then aggregate. Handle churn, capacity, new products, foreign currency and timing.","trap":"Average selling price ignores product mix if not adjusted."},{"heading":"Top-down market and share","body":"Project industry addressable sales × firm market share; share forecast should reflect competition, capacity and distribution. Macro assumptions reconcile with GDP and category growth.","trap":"Firm share cannot rise indefinitely beyond feasible size."},{"heading":"Historical base and convergence","body":"High historical growth may converge toward industry/long-run economy; new businesses need ramp assumptions, mature firms may track replacement demand. Avoid mechanical fixed growth without economics.","trap":"Analysts should justify persistence and competitive response."},{"heading":"Organic versus inorganic growth","body":"Separate acquisitions/divestitures from organic growth, FX translation from underlying demand, and one-time demand surges from recurring sales.","trap":"Acquired revenue is not same as same-store expansion."},{"heading":"Checks and sensitivities","body":"Compare projected volume to addressable customer base, pricing to elasticity/inflation, margin to competitors, and capacity utilization. Use optimistic/pessimistic drivers.","trap":"Forecast growth can be internally inconsistent with headcount/capex."}],"formulas":[{"name":"Bottom-up revenue","expr":"∑(forecast units_i × forecast realized price_i)","meaning":"Total projected sales by product/segment.","conditions":"Revenue recognition and mix must be consistent."},{"name":"Top-down revenue","expr":"Forecast industry revenue × forecast market share","meaning":"Implies firm sales based on category.","conditions":"Same perimeter, geography, currency and period."},{"name":"Revenue growth","expr":"(R1/R0)−1","meaning":"Period-over-period company sales forecast.","conditions":"Beware acquisitions/FX in growth interpretation."}],"examples":[{"question_en":"A firm expects its industry’s sales to be $5 billion and its share to rise from 4% to 5%. What company revenue is implied by the new share?","steps_vi":["Revenue=5,000m×0.05.","New revenue=$250m; compare with current $200m if industry size were unchanged."],"answer":"$250 million","check":"No FX or product-mix differences assumed."}],"questions":[{"stem_en":"Bottom-up revenue forecasting is most associated with:","options":["Price times volume by product","Only share repurchase estimates","Discounting dividends without operating drivers"],"correct":0,"why_vi":"Segment unit economics drive revenue.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"If industry sales reach $8 billion and a firm expects 3% market share, forecast revenue is:","options":["$2.4 billion","$240 million","$24 million"],"correct":1,"why_vi":"8,000m×3%=240m.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Forecasting new revenue from a takeover should normally be distinguished from:","options":["Financing interest expense","All other segment reporting","Organic growth"],"correct":2,"why_vi":"M&A adds inorganic revenue.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Bottom-up price and volume","back_vi":"Forecast each product/segment's units, customers, transactions and realized price, then aggregate. Handle churn, capacity, new products, foreign currency and timing. Exam trap: Average selling price ignores product mix if not adjusted."},{"front_en":"Top-down market and share","back_vi":"Project industry addressable sales × firm market share; share forecast should reflect competition, capacity and distribution. Macro assumptions reconcile with GDP and category growth. Exam trap: Firm share cannot rise indefinitely beyond feasible size."},{"front_en":"Historical base and convergence","back_vi":"High historical growth may converge toward industry/long-run economy; new businesses need ramp assumptions, mature firms may track replacement demand. Avoid mechanical fixed growth without economics. Exam trap: Analysts should justify persistence and competitive response."},{"front_en":"Organic versus inorganic growth","back_vi":"Separate acquisitions/divestitures from organic growth, FX translation from underlying demand, and one-time demand surges from recurring sales. Exam trap: Acquired revenue is not same as same-store expansion."},{"front_en":"Checks and sensitivities","back_vi":"Compare projected volume to addressable customer base, pricing to elasticity/inflation, margin to competitors, and capacity utilization. Use optimistic/pessimistic drivers. Exam trap: Forecast growth can be internally inconsistent with headcount/capex."}]},{"id":"CFA26-05-07-LOS03","letter":"7.c","title_en":"Operating Expense and Working Capital Forecasts","outcome_en":"explain how to forecast expenses and working-capital requirements","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM7 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM7 — Company Analysis: Forecasting","pages":"official outcomes at physical PDF p295; teaching chapter physical pp295–344"}],"sections":[{"heading":"Cost behavior","body":"Split variable costs tied to volume/revenue, fixed costs tied to capacity and semi-variable costs. Forecast price/cost inflation, supplier contracts, wage growth and economies of scale.","trap":"Assuming every cost grows at sales rate misstates operating leverage."},{"heading":"Margin and line-item approaches","body":"Model COGS as unit inputs or % sales; SG&A based staff, customer acquisition, revenue; D&A linked asset base and useful lives. Evaluate gross/EBIT margin realism.","trap":"EBITDA cannot substitute depreciation forecast for accounting income."},{"heading":"Working-capital drivers","body":"Forecast receivables with DSO, inventories with DIO and COGS, payables with DPO and COGS; account for seasonality and changing collection/payment terms.","trap":"DSO/DPO use different base line items; avoid common denominator."},{"heading":"Cash-flow connection","body":"Δoperating NWC = ΔAR + ΔInventory − ΔAP in simplified model; increase is generally cash use. Growth can require external capital even while income positive.","trap":"Changes in current liabilities often provide financing, not additional cash use."},{"heading":"Stress tests","body":"Test margin compression, slower collections, excess stock, supplier tightening and cost inflation. Keep balance-sheet and cash-flow models reconciled.","trap":"Fast-growing sales may worsen liquidity temporarily."}],"formulas":[{"name":"Forecast A/R","expr":"Revenue × DSO / days in period","meaning":"Receivables from collection days.","conditions":"Revenue should match DSO period and relevant net sales."},{"name":"Forecast inventory","expr":"COGS × DIO / days in period","meaning":"Operating inventory estimate.","conditions":"COGS, not sales, typically denominator."},{"name":"Forecast A/P","expr":"COGS × DPO / days in period","meaning":"Payables tied to purchasing costs.","conditions":"Purchasing versus COGS differences may matter."},{"name":"Change in working capital","expr":"ΔNWC = ΔAR + Δinventory − ΔAP","meaning":"Simplified noncash working capital investment.","conditions":"Include other operating accounts when material."}],"examples":[{"question_en":"Annual forecast revenue is $365 million, with DSO 40 days. Estimate year-end accounts receivable assuming 365 days and stable sales.","steps_vi":["Forecast receivables ≈ 365m×40/365.","= $40 million."],"answer":"$40 million","check":"Simple steady-state ratio calculation; excludes seasonality and taxes."}],"questions":[{"stem_en":"If COGS is $730 million annually and DIO is 20 days (365-day year), inventory is approximately:","options":["$20 million","$40 million","$73 million"],"correct":1,"why_vi":"730m×20/365=40m.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"All else equal, an increase in DSO is most likely to:","options":["Shorten the collection period","Decrease accounts receivable automatically","Increase accounts receivable and reduce cash conversion"],"correct":2,"why_vi":"DSO higher implies slower collection.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A company’s variable expenses are most closely linked to:","options":["The activity or sales volume driving them","Book share price only","The number of analysts following the stock only"],"correct":0,"why_vi":"Variable costs change with economic activity.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Cost behavior","back_vi":"Split variable costs tied to volume/revenue, fixed costs tied to capacity and semi-variable costs. Forecast price/cost inflation, supplier contracts, wage growth and economies of scale. Exam trap: Assuming every cost grows at sales rate misstates operating leverage."},{"front_en":"Margin and line-item approaches","back_vi":"Model COGS as unit inputs or % sales; SG&A based staff, customer acquisition, revenue; D&A linked asset base and useful lives. Evaluate gross/EBIT margin realism. Exam trap: EBITDA cannot substitute depreciation forecast for accounting income."},{"front_en":"Working-capital drivers","back_vi":"Forecast receivables with DSO, inventories with DIO and COGS, payables with DPO and COGS; account for seasonality and changing collection/payment terms. Exam trap: DSO/DPO use different base line items; avoid common denominator."},{"front_en":"Cash-flow connection","back_vi":"Δoperating NWC = ΔAR + ΔInventory − ΔAP in simplified model; increase is generally cash use. Growth can require external capital even while income positive. Exam trap: Changes in current liabilities often provide financing, not additional cash use."},{"front_en":"Stress tests","back_vi":"Test margin compression, slower collections, excess stock, supplier tightening and cost inflation. Keep balance-sheet and cash-flow models reconciled. Exam trap: Fast-growing sales may worsen liquidity temporarily."}]},{"id":"CFA26-05-07-LOS04","letter":"7.d","title_en":"Capital Investment and Funding Forecasts","outcome_en":"explain how to forecast capital investment and capital structure","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM7 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM7 — Company Analysis: Forecasting","pages":"official outcomes at physical PDF p295; teaching chapter physical pp295–344"}],"sections":[{"heading":"Maintenance and growth capex","body":"Forecast baseline asset replacement and new capacity separately, linked to utilization, technological change and replacement cycles. Depreciation is accounting expense, not cash outflow.","trap":"Assuming capex=depreciation can miss asset growth or aging assets."},{"heading":"Long-lived asset roll-forward","body":"Ending PP&E ≈ beginning PP&E + capex − depreciation − disposals/impairments (adjust for acquisitions/FX). Forecast depreciation based on vintages/useful lives.","trap":"Double-counting capex in both assets and expenses is incorrect."},{"heading":"Funding cash deficits","body":"Operating CF−capex−dividends−debt maturities may require borrowing/equity/cash draw. Interest expense depends on projected average debt and rate. Model covenants and refinancing.","trap":"Debt plug with no interest feedback makes model inconsistent."},{"heading":"Capital structure assumptions","body":"Debt targets, share issuance, buybacks, dividends, lease commitments and maturity schedules determine future equity/debt balances and WACC. Avoid mechanically fixed D/E under all scenarios.","trap":"Issuing equity affects shares and earnings per share."},{"heading":"Scenario resilience","body":"Stress higher rates, lower operating cash generation, delayed capex and credit tightening; assess liquidity runway and headroom.","trap":"Positive EBITDA doesn't always cover debt maturities."}],"formulas":[{"name":"Net PP&E roll-forward","expr":"Ending PP&E = beginning PP&E + capex − D&A − disposals + other adjustments","meaning":"Link capital spending to balance sheet.","conditions":"D&A must be portion relating to modeled PP&E."},{"name":"Simple funding gap","expr":"Funding need ≈ capital spending + debt due + distributions − operating cash flow − planned cash draw","meaning":"Approximate required external financing.","conditions":"Other investing/financing cash flows may be material."},{"name":"Projected interest","expr":"Interest expense ≈ average outstanding debt × average financing rate","meaning":"Connect debt forecast to earnings.","conditions":"Rate may be floating, hedged or tranche-specific."}],"examples":[{"question_en":"A company starts with $500m net PP&E, plans $90m capex and $50m depreciation, with no disposals. What ending PP&E is implied?","steps_vi":["Ending PP&E=500+90−50.","= $540m."],"answer":"$540 million","check":"Excludes acquisitions, FX and other asset adjustments."}],"questions":[{"stem_en":"A capital-intensive company’s depreciation forecast is most directly linked to:","options":["The stock exchange bid–ask spread","Only current cash dividends","Its depreciable asset base and asset lives"],"correct":2,"why_vi":"D&A reflects asset amortization schedule.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A company’s ending net PP&E rises by how much if capex is $100m and depreciation is $60m, with no other changes?","options":["$40 million","$160 million","−$40 million"],"correct":0,"why_vi":"Net PP&E change = capex−depreciation=40m.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A company with large scheduled debt maturities faces particular sensitivity to:","options":["Only total share volume traded","Refinancing rates and liquidity availability","Historical dividend record alone"],"correct":1,"why_vi":"Maturity and debt-market conditions drive funding risk.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Maintenance and growth capex","back_vi":"Forecast baseline asset replacement and new capacity separately, linked to utilization, technological change and replacement cycles. Depreciation is accounting expense, not cash outflow. Exam trap: Assuming capex=depreciation can miss asset growth or aging assets."},{"front_en":"Long-lived asset roll-forward","back_vi":"Ending PP&E ≈ beginning PP&E + capex − depreciation − disposals/impairments (adjust for acquisitions/FX). Forecast depreciation based on vintages/useful lives. Exam trap: Double-counting capex in both assets and expenses is incorrect."},{"front_en":"Funding cash deficits","back_vi":"Operating CF−capex−dividends−debt maturities may require borrowing/equity/cash draw. Interest expense depends on projected average debt and rate. Model covenants and refinancing. Exam trap: Debt plug with no interest feedback makes model inconsistent."},{"front_en":"Capital structure assumptions","back_vi":"Debt targets, share issuance, buybacks, dividends, lease commitments and maturity schedules determine future equity/debt balances and WACC. Avoid mechanically fixed D/E under all scenarios. Exam trap: Issuing equity affects shares and earnings per share."},{"front_en":"Scenario resilience","back_vi":"Stress higher rates, lower operating cash generation, delayed capex and credit tightening; assess liquidity runway and headroom. Exam trap: Positive EBITDA doesn't always cover debt maturities."}]},{"id":"CFA26-05-07-LOS05","letter":"7.e","title_en":"Scenario Analysis in Forecasting","outcome_en":"describe the design and interpretation of alternative company forecast scenarios","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM7 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM7 — Company Analysis: Forecasting","pages":"official outcomes at physical PDF p295; teaching chapter physical pp295–344"}],"sections":[{"heading":"Base, upside and downside cases","body":"Xây coherent worlds with drivers: demand growth, share, pricing, margins, working capital, capex, credit availability. Một base case là central working estimate, không phải outcome certain.","trap":"Bull không nên chỉ cộng đều vào tất cả outputs."},{"heading":"Sensitivity versus scenario","body":"Sensitivity thay một biến hoặc hai biến giữ others constant; scenario thay nhiều drivers có liên hệ như recession → volume, price, margin, DSO, funding costs.","trap":"Các biến liên quan cần được thay nhất quán."},{"heading":"Probability weighting","body":"Nếu assign probabilities có cơ sở, expected outcome = ∑p_i×value_i; phải đảm bảo probabilities sum 100% và không trộn target price với cash flows sai cách.","trap":"Weighted average không nói downside tail đã bị loại bỏ."},{"heading":"Reverse stress testing","body":"Xác định điều kiện nào gây liquidity breach, covenant breach hoặc investment thesis failure. Useful for risk limits và watch indicators.","trap":"Một model có margin of safety không đảm bảo không default."},{"heading":"Monitoring and communication","body":"Document assumptions, triggers, ranges và model updates khi evidence thay đổi. Distinguish model uncertainty từ irreducible future risk.","trap":"Results nên report cùng assumptions và confidence, không chỉ một target."}],"formulas":[{"name":"Probability-weighted estimate","expr":"E[V] = Σ(probability_i × scenario value_i)","meaning":"Kỳ vọng đơn giản nếu scenarios exhaustive và probabilities consistent.","conditions":"Must specify whether valuation is at same date/units."},{"name":"Downside to scenario","expr":"(Downside case value / current price) − 1","meaning":"Đo price change đến case value.","conditions":"Not a probability-adjusted expected return."}],"examples":[{"question_en":"A scenario model values one share at $30 in a 20%-probability bear case, $50 in a 60% base case, and $70 in a 20% bull case. Compute expected value.","steps_vi":["Weighted value=0.2×30+0.6×50+0.2×70.","=6+30+14=$50."],"answer":"$50 per share","check":"Assumes mutually exclusive exhaustive scenarios and subjective probabilities."}],"questions":[{"stem_en":"Which analysis changes several correlated assumptions to represent a recession?","options":["Scenario analysis","A one-variable sensitivity test only","A dividend record-date test"],"correct":0,"why_vi":"Recession affects revenue, margins and working capital jointly.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"With scenario values $20 (25%) and $60 (75%), the probability-weighted value equals:","options":["$40","$50","$30"],"correct":1,"why_vi":".25×20+.75×60=50.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A risk-focused forecast should:","options":["Assume creditors roll debt in every scenario","Omit links between profit and cash","Identify the assumptions under which cash or covenant limits are breached"],"correct":2,"why_vi":"Reverse stress testing finds thesis/funding failures.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Base, upside and downside cases","back_vi":"Xây coherent worlds with drivers: demand growth, share, pricing, margins, working capital, capex, credit availability. Một base case là central working estimate, không phải outcome certain. Exam trap: Bull không nên chỉ cộng đều vào tất cả outputs."},{"front_en":"Sensitivity versus scenario","back_vi":"Sensitivity thay một biến hoặc hai biến giữ others constant; scenario thay nhiều drivers có liên hệ như recession → volume, price, margin, DSO, funding costs. Exam trap: Các biến liên quan cần được thay nhất quán."},{"front_en":"Probability weighting","back_vi":"Nếu assign probabilities có cơ sở, expected outcome = ∑p_i×value_i; phải đảm bảo probabilities sum 100% và không trộn target price với cash flows sai cách. Exam trap: Weighted average không nói downside tail đã bị loại bỏ."},{"front_en":"Reverse stress testing","back_vi":"Xác định điều kiện nào gây liquidity breach, covenant breach hoặc investment thesis failure. Useful for risk limits và watch indicators. Exam trap: Một model có margin of safety không đảm bảo không default."},{"front_en":"Monitoring and communication","back_vi":"Document assumptions, triggers, ranges và model updates khi evidence thay đổi. Distinguish model uncertainty từ irreducible future risk. Exam trap: Results nên report cùng assumptions và confidence, không chỉ một target."}]}]},{"module_id":"CFA26-05-08","module_title":"Equity Valuation: Concepts and Basic Tools","subject":"Equity Investments","version":"3.8","qa_status":"SOURCE_GROUNDED_DETAILED_DRAFT_PENDING_INDEPENDENT_ACADEMIC_AUDIT","language":"Vietnamese explanatory notes; original English question stems and options","source_policy":"Original bilingual paraphrased lessons and original practice based on CFAI 2026 Equity Volume 5, module 8; primary PDF directly inspected; additional line-by-line editorial checks pending","los":[{"id":"CFA26-05-08-LOS01","letter":"8.a","title_en":"Overvaluation and Undervaluation","outcome_en":"evaluate valuation versus market price to classify an equity security","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"Observed price versus estimated value","body":"Market price P là observable transaction/quote; intrinsic value V là estimate dựa forecast và discounting hoặc comparable framework. P và V khác nhau là cơ sở của valuation opinion.","trap":"Model estimate không phải true value quan sát được."},{"heading":"Undervaluation and overvaluation","body":"V_est>P gợi undervalued, V_est<P gợi overvalued; V≈P gọi approximately fair value trong tolerance. Action cần cân nhắc dividends, horizon, risk và opportunity cost.","trap":"Không tự động recommend short khi overvalued nếu borrow/catalyst risk cao."},{"heading":"Margin of safety","body":"Price discount tới estimate giúp buffer cho model error, nhưng chỉ có ý nghĩa khi estimates có căn cứ và uncertainty được stress-tested. Margin 20% không bảo đảm investment return 20%.","trap":"Một giá rẻ có thể là value trap."},{"heading":"Required return and discount rate","body":"Required expected return tăng thường làm present value giảm, nếu giữ cash flow forecasts; uncertainty trong r và terminal estimates có thể chi phối valuation.","trap":"Đừng trộn cost of debt vào discounting equity dividends."},{"heading":"Decision and catalyst discipline","body":"Document upside, downside, sensitivity, catalysts, thesis breakpoints, liquidity và implementation costs. Distinguish security worth from price trajectory.","trap":"Timing risk tồn tại ngay cả khi model đúng về long-run cash flow."}],"formulas":[{"name":"Valuation premium/discount","expr":"(V_est − P)/P","meaning":"Positive indicates modeled upside vs observed price.","conditions":"Before dividends and investor-specific costs."},{"name":"Classification","expr":"V_est>P undervalued; V_est≈P fairly valued; V_est<P overvalued","meaning":"Interpret in model uncertainty range.","conditions":"Approximation depends on analyst tolerance and confidence."}],"examples":[{"question_en":"A security trades at $80, and a model values it at $92. Calculate implied upside relative to price.","steps_vi":["Valuation spread=92−80=$12.","Relative gap=12/80=15%."],"answer":"15% estimated upside; potentially undervalued","check":"The model estimate does not guarantee a 15% realized gain."}],"questions":[{"stem_en":"A stock trading at $40 with an estimated intrinsic value of $32 is:","options":["Overvalued relative to the model","Undervalued relative to the model","Guaranteed to decline tomorrow"],"correct":0,"why_vi":"V_est<P nên overvalued theo model.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Valuation estimates should be compared with market price while also considering:","options":["Only the stock ticker","Assumptions, uncertainty, and implementation costs","Guaranteed future price convergence"],"correct":1,"why_vi":"Valuation gap has model/timing risk.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"If estimated value is $55 and market price is $50, modeled price upside is:","options":["5%","9.09%","10%"],"correct":2,"why_vi":"(55−50)/50=10%.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Observed price versus estimated value","back_vi":"Market price P là observable transaction/quote; intrinsic value V là estimate dựa forecast và discounting hoặc comparable framework. P và V khác nhau là cơ sở của valuation opinion. Exam trap: Model estimate không phải true value quan sát được."},{"front_en":"Undervaluation and overvaluation","back_vi":"V_est>P gợi undervalued, V_est<P gợi overvalued; V≈P gọi approximately fair value trong tolerance. Action cần cân nhắc dividends, horizon, risk và opportunity cost. Exam trap: Không tự động recommend short khi overvalued nếu borrow/catalyst risk cao."},{"front_en":"Margin of safety","back_vi":"Price discount tới estimate giúp buffer cho model error, nhưng chỉ có ý nghĩa khi estimates có căn cứ và uncertainty được stress-tested. Margin 20% không bảo đảm investment return 20%. Exam trap: Một giá rẻ có thể là value trap."},{"front_en":"Required return and discount rate","back_vi":"Required expected return tăng thường làm present value giảm, nếu giữ cash flow forecasts; uncertainty trong r và terminal estimates có thể chi phối valuation. Exam trap: Đừng trộn cost of debt vào discounting equity dividends."},{"front_en":"Decision and catalyst discipline","back_vi":"Document upside, downside, sensitivity, catalysts, thesis breakpoints, liquidity và implementation costs. Distinguish security worth from price trajectory. Exam trap: Timing risk tồn tại ngay cả khi model đúng về long-run cash flow."}]},{"id":"CFA26-05-08-LOS02","letter":"8.b","title_en":"Categories of Equity Valuation Models","outcome_en":"describe present-value, relative-value, and asset-based valuation approaches","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"Present value models","body":"Discount expected future economic distributions to shareholder (DDM), cash flows to equity (FCFE) or sometimes enterprise cash flows at appropriate rate. Direct link to fundamentals nhưng nhạy assumptions.","trap":"FCFF value enterprise, not common equity directly."},{"heading":"Price multiple models","body":"Relative valuation so share price/EPS, book, revenue hoặc operating cash flow với comparables; dễ communicate nhưng peer selection và cycle adjustments quan trọng.","trap":"Low multiple có thể do low growth/high risk."},{"heading":"Enterprise-value multiples","body":"EV/EBITDA, EV/sales dùng total operating business value với operating measures before financing costs; equity estimate phải bridge từ enterprise value.","trap":"EV/EBITDA không phải P/E substitute với cùng numerator."},{"heading":"Asset-based approaches","body":"Estimate assets at current economic/liquidation values less liabilities, especially for asset-rich, holding or liquidation cases. Brand, people và synergies có thể khó đo.","trap":"Book value không tự equal appraised asset value."},{"heading":"Selection and triangulation","body":"Model phù hợp tùy firm lifecycle, dividend policy, cash-flow predictability, intangibles, distress và reporting. Triangulate approaches without naively averaging inconsistent estimates.","trap":"Model complexity không bảo đảm accuracy."}],"formulas":[{"name":"General equity DCF","expr":"Equity value = PV(expected cash flows to equity discounted at equity required return)","meaning":"Present-value category.","conditions":"Consistent equity cash flows and r_e."},{"name":"Relative multiple","expr":"Estimated equity price = benchmark multiple × comparable per-share fundamental","meaning":"Price-multiple category.","conditions":"Adjust for growth, risk, accounting and capital structure."},{"name":"Net asset approach","expr":"Equity value ≈ economically appraised assets − economically appraised liabilities","meaning":"Asset-based category.","conditions":"Appraised rather than automatically book figures."}],"examples":[{"question_en":"Two comparable firms have forward P/E of 12× and 14×. An analyst selects a justified peer multiple of 13× for a target with forward EPS of $3. What is implied price?","steps_vi":["Target price=13×$3.","= $39 per share."],"answer":"$39","check":"Peer comparability and earnings quality need independent evaluation."}],"questions":[{"stem_en":"A valuation based on discounted expected future dividends is a:","options":["Pure asset-based liquidation model","Present-value model","Price-to-book multiple model"],"correct":1,"why_vi":"DDM is PV of cash distributions.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A comparable-company P/E estimate primarily relies on:","options":["Guaranteed liquidation proceeds","Only the risk-free interest rate","Relative market pricing of similar firms"],"correct":2,"why_vi":"Price-multiples use comparable equity pricing.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A firm whose major assets can be reliably appraised may be particularly suited to:","options":["Asset-based valuation","Historical price trend extrapolation only","Guaranteed constant dividend assumptions"],"correct":0,"why_vi":"Asset appraisal useful for holdings/asset-rich firms.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Present value models","back_vi":"Discount expected future economic distributions to shareholder (DDM), cash flows to equity (FCFE) or sometimes enterprise cash flows at appropriate rate. Direct link to fundamentals nhưng nhạy assumptions. Exam trap: FCFF value enterprise, not common equity directly."},{"front_en":"Price multiple models","back_vi":"Relative valuation so share price/EPS, book, revenue hoặc operating cash flow với comparables; dễ communicate nhưng peer selection và cycle adjustments quan trọng. Exam trap: Low multiple có thể do low growth/high risk."},{"front_en":"Enterprise-value multiples","back_vi":"EV/EBITDA, EV/sales dùng total operating business value với operating measures before financing costs; equity estimate phải bridge từ enterprise value. Exam trap: EV/EBITDA không phải P/E substitute với cùng numerator."},{"front_en":"Asset-based approaches","back_vi":"Estimate assets at current economic/liquidation values less liabilities, especially for asset-rich, holding or liquidation cases. Brand, people và synergies có thể khó đo. Exam trap: Book value không tự equal appraised asset value."},{"front_en":"Selection and triangulation","back_vi":"Model phù hợp tùy firm lifecycle, dividend policy, cash-flow predictability, intangibles, distress và reporting. Triangulate approaches without naively averaging inconsistent estimates. Exam trap: Model complexity không bảo đảm accuracy."}]},{"id":"CFA26-05-08-LOS03","letter":"8.c","title_en":"Dividends, Splits, and Repurchases","outcome_en":"describe ordinary, special, stock dividends, stock splits, reverse splits, and repurchases","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"Regular versus special cash dividends","body":"Regular dividends thường kỳ vọng recurring tùy board policy; extra/special dividends là irregular nonrecurring distributions. Dividends chuyển cash khỏi firm sang shareholders, giảm cash assets.","trap":"Special dividend không nên đưa vào g perpetual như regular dividend."},{"heading":"Stock dividends","body":"Company phân phối thêm shares proportionally; each investor owns more shares but usually same proportional company interest, with price-per-share adjustment. Aggregate economic wealth unchanged absent information/tax effects.","trap":"Stock dividend không tạo cash income."},{"heading":"Forward and reverse splits","body":"A 2-for-1 split doubles share count and halves theoretical per-share price; reverse split làm điều ngược lại. Không tự đổi total common equity market cap khi frictionless.","trap":"Split không phải instant value creation."},{"heading":"Share repurchases","body":"Buyback dùng cash để giảm shares outstanding; là cách trả vốn cho selling shareholders, có thể thay EPS và ownership weights. Value impact depends on repurchase price, funding, alternative uses and taxes.","trap":"EPS accretion không luôn value accretion."},{"heading":"Payout policy nuance","body":"Shareholder returns gồm dividends và buyback effects, nhưng buybacks tạo cash benefit trực tiếp chỉ cho shares được bán. Capital gains/tax treatment differs by investor.","trap":"Không cộng toàn bộ buyback spending như dividend received by every investor."}],"formulas":[{"name":"Post-split theoretical price","expr":"New price = old price / split factor","meaning":"2-for-1: factor 2; 1-for-5 reverse split: factor 0.2.","conditions":"Abstracts information, frictions and market movements."},{"name":"Post-split shares","expr":"New shares = old shares × split factor","meaning":"Giữ aggregate economic position.","conditions":"Same split ratio for same class."},{"name":"Dividend yield","expr":"Regular annual dividend per share / current share price","meaning":"Cash distribution yield at reference price.","conditions":"Special cash dividends require separate handling."}],"examples":[{"question_en":"An investor owns 200 shares trading at $60. After a 3-for-2 stock split, find theoretical shares and share price.","steps_vi":["Split factor=3/2=1.5.","New shares=200×1.5=300.","Theoretical new share price=60/1.5=$40."],"answer":"300 shares at $40 each","check":"Total pre/post position value $12,000, ignoring market movements."}],"questions":[{"stem_en":"A 2-for-1 stock split, all else equal, should initially result in:","options":["Twice the total firm value","Half the share count at double the price","Twice as many shares at roughly half the share price"],"correct":2,"why_vi":"Split reshapes units without economic value creation.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A special dividend is best understood as:","options":["An additional nonregular cash distribution","A mandatory perpetual fixed payment","A pure share-count adjustment"],"correct":0,"why_vi":"Special payouts are not ordinary recurring dividends.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A share repurchase typically:","options":["Creates a new outstanding debt claim automatically","Reduces outstanding shares and corporate cash, all else equal","Guarantees improved intrinsic value per share"],"correct":1,"why_vi":"Price paid and reinvestment alternatives determine effects.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Regular versus special cash dividends","back_vi":"Regular dividends thường kỳ vọng recurring tùy board policy; extra/special dividends là irregular nonrecurring distributions. Dividends chuyển cash khỏi firm sang shareholders, giảm cash assets. Exam trap: Special dividend không nên đưa vào g perpetual như regular dividend."},{"front_en":"Stock dividends","back_vi":"Company phân phối thêm shares proportionally; each investor owns more shares but usually same proportional company interest, with price-per-share adjustment. Aggregate economic wealth unchanged absent information/tax effects. Exam trap: Stock dividend không tạo cash income."},{"front_en":"Forward and reverse splits","back_vi":"A 2-for-1 split doubles share count and halves theoretical per-share price; reverse split làm điều ngược lại. Không tự đổi total common equity market cap khi frictionless. Exam trap: Split không phải instant value creation."},{"front_en":"Share repurchases","back_vi":"Buyback dùng cash để giảm shares outstanding; là cách trả vốn cho selling shareholders, có thể thay EPS và ownership weights. Value impact depends on repurchase price, funding, alternative uses and taxes. Exam trap: EPS accretion không luôn value accretion."},{"front_en":"Payout policy nuance","back_vi":"Shareholder returns gồm dividends và buyback effects, nhưng buybacks tạo cash benefit trực tiếp chỉ cho shares được bán. Capital gains/tax treatment differs by investor. Exam trap: Không cộng toàn bộ buyback spending như dividend received by every investor."}]},{"id":"CFA26-05-08-LOS04","letter":"8.d","title_en":"Dividend Payment Chronology","outcome_en":"describe declaration, ex-dividend, record, and payment dates","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"Declaration date","body":"Board announces dividend amount, relevant eligibility dates and payment date, subject to legal/jurisdictional specifics. Declaration can create payable accounting liability depending on rules.","trap":"Declaration is not when cash reaches shareholders."},{"heading":"Ex-dividend date","body":"First date shares trade without right to upcoming dividend under relevant exchange settlement conventions. Buyers on/after ex-date normally do not receive that declared dividend.","trap":"Ex-date timing relative to record date depends on settlement regime."},{"heading":"Holder-of-record date","body":"Issuer/depositary identifies registered holders for entitlement; trade settlement processing determines whose holdings qualify. Record date should not be confused with cash payment.","trap":"Buying on record date may be too late if ex-date already passed."},{"heading":"Payment date","body":"Issuer pays cash to eligible holders; actual brokerage credit and withholding tax may differ by jurisdiction. Cash exits firm on payment.","trap":"Paid dividend can be delayed operationally despite entitlement."},{"heading":"Ex-date share price behavior","body":"Theoretical ex-dividend price drop approximately equals dividend under no other news and frictionless assumptions; actual move reflects taxes, market moves and supply/demand.","trap":"Không thể arbitrage riskless bằng mua ngay trước ex-date."}],"formulas":[{"name":"Standard conceptual order","expr":"Declaration → ex-dividend → holder of record → payment","meaning":"Mốc timeline thông thường.","conditions":"Exchange settlement reforms may alter dates and exceptional cases."},{"name":"Ex-date theoretical adjustment","expr":"P_ex ≈ P_cum − dividend per share","meaning":"Simplified when no other price-moving information.","conditions":"Taxes, intraday news and market volatility break exact equality."}],"examples":[{"question_en":"A stock closes at $51 just before going ex-dividend on a $1 cash dividend, with no other news or frictions. What is the theoretical ex-dividend price?","steps_vi":["Cash distribution removes $1 from corporate equity per share.","Theoretical price ≈51−1."],"answer":"$50","check":"Real-world market price can differ due to new information and taxes."}],"questions":[{"stem_en":"A buyer who purchases shares on the ex-dividend date normally:","options":["Does not receive the announced dividend","Always receives two dividends","Becomes entitled regardless of settlement rules"],"correct":0,"why_vi":"Ex-date is first trading without declared entitlement.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Which date usually occurs last in the dividend process?","options":["Declaration date","Payment date","Ex-dividend date"],"correct":1,"why_vi":"Payment transfers cash at end of timeline.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A share trades cum-dividend at $30 before a $0.50 payment. Ignoring news and taxes, its theoretical ex-dividend price is:","options":["$30.50","$15.00","$29.50"],"correct":2,"why_vi":"30−0.50=29.50.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Declaration date","back_vi":"Board announces dividend amount, relevant eligibility dates and payment date, subject to legal/jurisdictional specifics. Declaration can create payable accounting liability depending on rules. Exam trap: Declaration is not when cash reaches shareholders."},{"front_en":"Ex-dividend date","back_vi":"First date shares trade without right to upcoming dividend under relevant exchange settlement conventions. Buyers on/after ex-date normally do not receive that declared dividend. Exam trap: Ex-date timing relative to record date depends on settlement regime."},{"front_en":"Holder-of-record date","back_vi":"Issuer/depositary identifies registered holders for entitlement; trade settlement processing determines whose holdings qualify. Record date should not be confused with cash payment. Exam trap: Buying on record date may be too late if ex-date already passed."},{"front_en":"Payment date","back_vi":"Issuer pays cash to eligible holders; actual brokerage credit and withholding tax may differ by jurisdiction. Cash exits firm on payment. Exam trap: Paid dividend can be delayed operationally despite entitlement."},{"front_en":"Ex-date share price behavior","back_vi":"Theoretical ex-dividend price drop approximately equals dividend under no other news and frictionless assumptions; actual move reflects taxes, market moves and supply/demand. Exam trap: Không thể arbitrage riskless bằng mua ngay trước ex-date."}]},{"id":"CFA26-05-08-LOS05","letter":"8.e","title_en":"Dividend Discount and FCFE Present-Value Models","outcome_en":"explain why discounting expected shareholder cash flows yields equity value","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"Present value rationale","body":"Equity's economic value relates to cash ultimately available to owners, discounted for time value and equity risk. Infinite-life share value can be represented by series of expected future distributions under suitable assumptions.","trap":"Earnings are accounting profits, not automatically distributable cash."},{"heading":"Dividend discount model","body":"DDM values common equity from discounted expected dividends D_t including terminal value; useful when dividends meaningfully proxy distribution capacity. Very sensitive to long-run dividend forecasts.","trap":"No dividends today does not imply company has zero economic value."},{"heading":"FCFE valuation","body":"Free cash flow to equity is cash potentially available to equity after operations, reinvestment and net borrowing; relevant when actual dividends do not reflect payout capacity.","trap":"FCFE after debt cash flows; don't discount with WACC."},{"heading":"FCFF distinction","body":"Free cash flow to firm is for all capital providers, valued at WACC to estimate enterprise value; then subtract net debt and other senior claims to common.","trap":"Mixing FCFF with equity cost of capital is inconsistent."},{"heading":"Terminal value and required returns","body":"In multiperiod models discount each cash flow at rate consistent with its claim/risk and forecast terminal value carefully. Growth below required return for perpetual constant growth.","trap":"Terminal value can dominate; stress growth and discount rate."}],"formulas":[{"name":"Dividend discount general form","expr":"V0 = Σ[t≥1] E[D_t]/(1+r_e)^t","meaning":"PV expected common dividends.","conditions":"Conceptual infinite stream, discount rate consistent."},{"name":"FCFE approximation","expr":"FCFE = CFO − capex + net borrowing","meaning":"Available cash to common after reinvestment/debt funding.","conditions":"Subject to company-specific treatment of preferred and nonoperating items."},{"name":"FCFF to equity bridge","expr":"Equity value ≈ enterprise value − net debt − preferred claims − noncontrolling interests + adjustments","meaning":"Convert enterprise to common equity value.","conditions":"Definition consistency is essential."}],"examples":[{"question_en":"A stock is expected to pay $3 in dividends one year from now and sell for $55 at that time. With an equity required return of 10%, estimate its present value.","steps_vi":["One-year payoff=$3+$55=$58.","Present value=58/1.10=$52.727... ."],"answer":"$52.73","check":"One-period model; sale price itself should reflect subsequent distributions."}],"questions":[{"stem_en":"Discounted dividends in a DDM should use:","options":["Pretax cost of debt only","Cost of equity","Treasury bill rate regardless of equity risk"],"correct":1,"why_vi":"Claim being discounted is to equity owners.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"FCFE differs from FCFF mainly because FCFE:","options":["Is measured before all capital provider claims by definition","Always equals reported net income","Reflects net borrowing and cash available to equity"],"correct":2,"why_vi":"FCFE explicitly incorporates borrowing cash flows.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A company currently paying no dividends can still have value because:","options":["Investors expect future distributable cash flows or value realization","Equity claims necessarily have zero future payoffs","Cost of equity must be zero"],"correct":0,"why_vi":"Value derives future owner benefits, not just current payout.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Present value rationale","back_vi":"Equity's economic value relates to cash ultimately available to owners, discounted for time value and equity risk. Infinite-life share value can be represented by series of expected future distributions under suitable assumptions. Exam trap: Earnings are accounting profits, not automatically distributable cash."},{"front_en":"Dividend discount model","back_vi":"DDM values common equity from discounted expected dividends D_t including terminal value; useful when dividends meaningfully proxy distribution capacity. Very sensitive to long-run dividend forecasts. Exam trap: No dividends today does not imply company has zero economic value."},{"front_en":"FCFE valuation","back_vi":"Free cash flow to equity is cash potentially available to equity after operations, reinvestment and net borrowing; relevant when actual dividends do not reflect payout capacity. Exam trap: FCFE after debt cash flows; don't discount with WACC."},{"front_en":"FCFF distinction","back_vi":"Free cash flow to firm is for all capital providers, valued at WACC to estimate enterprise value; then subtract net debt and other senior claims to common. Exam trap: Mixing FCFF with equity cost of capital is inconsistent."},{"front_en":"Terminal value and required returns","back_vi":"In multiperiod models discount each cash flow at rate consistent with its claim/risk and forecast terminal value carefully. Growth below required return for perpetual constant growth. Exam trap: Terminal value can dominate; stress growth and discount rate."}]},{"id":"CFA26-05-08-LOS06","letter":"8.f","title_en":"Strengths and Limitations of Valuation Models","outcome_en":"explain advantages and drawbacks of present-value, multiple and asset-based methods","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"Present value strengths","body":"Cash-flow models directly connect price to long-run fundamental economics, reinvestment and required return. Good for scenario analysis and estimating value outside immediate peer prices.","trap":"Uncertain long-horizon assumptions can swamp apparent precision."},{"heading":"Present value weaknesses","body":"Forecasts, terminal growth, discount rates and payout modeling may be fragile, especially distressed firms, cyclical or young companies. DDM with low/no dividend may understate near-term distributable potential.","trap":"A detailed spreadsheet is not automatically more accurate."},{"heading":"Relative valuation strengths","body":"Multiples are easy to calculate, explain and compare; embody market consensus prices and can cross-check DCF. Useful with sufficient, economically comparable traded peers.","trap":"If peer group collectively mispriced, relative valuation inherits errors."},{"heading":"Relative valuation weaknesses","body":"Differences in accounting, growth, margins, risk, capital structure and one-off earnings distort comparability. Negative earnings make P/E not meaningful in customary sense.","trap":"Selecting only high-multiple peers introduces confirmation bias."},{"heading":"Asset-based tradeoffs","body":"Asset values can anchor firms with separable assets/liquidation outcomes, but may neglect brands, network effects, internally developed IP and going-concern synergies. Asset appraisals can be stale.","trap":"Book assets not same as realizable net assets."}],"formulas":[{"name":"Model selection rubric","expr":"Cash-flow visibility + payout policy + peer quality + asset separability → choose model(s)","meaning":"Qualitative guidance for model appropriateness.","conditions":"A combination can reveal uncertainty rather than a single truth."},{"name":"Sensitivity of PV","expr":"Higher required return → lower present value, ceteris paribus","meaning":"Directional PV relation.","conditions":"Cash-flow forecast may itself change with rates/economy."}],"examples":[{"question_en":"An unprofitable high-growth firm has negative EPS but positive sales, while peers have different leverage. Which valuation caution is most direct?","steps_vi":["Conventional P/E is not useful with negative earnings.","EV/sales or scenario cash flow may provide additional context, with margins and leverage adjustments."],"answer":"Avoid relying on P/E; use suitable models and explicit assumptions.","check":"No sales-based multiple eliminates profitability risk."}],"questions":[{"stem_en":"A principal weakness of DCF valuation is its:","options":["Inability to incorporate any risk","Reliance on current peer multiples only","Sensitivity to long-run assumptions"],"correct":2,"why_vi":"Growth and discount assumptions can dominate.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Comparable-company multiples are most reliable when:","options":["Companies have similar economics and accounting policies","Companies have completely unrelated business models","All earnings are negative"],"correct":0,"why_vi":"Relative comparability essential.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"An asset-based approach may systematically miss value from:","options":["Physical land with observable transactions","Internally generated brands and synergies","Explicit debt liabilities"],"correct":1,"why_vi":"Intangibles can escape asset book/appraisal measures.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Present value strengths","back_vi":"Cash-flow models directly connect price to long-run fundamental economics, reinvestment and required return. Good for scenario analysis and estimating value outside immediate peer prices. Exam trap: Uncertain long-horizon assumptions can swamp apparent precision."},{"front_en":"Present value weaknesses","back_vi":"Forecasts, terminal growth, discount rates and payout modeling may be fragile, especially distressed firms, cyclical or young companies. DDM with low/no dividend may understate near-term distributable potential. Exam trap: A detailed spreadsheet is not automatically more accurate."},{"front_en":"Relative valuation strengths","back_vi":"Multiples are easy to calculate, explain and compare; embody market consensus prices and can cross-check DCF. Useful with sufficient, economically comparable traded peers. Exam trap: If peer group collectively mispriced, relative valuation inherits errors."},{"front_en":"Relative valuation weaknesses","back_vi":"Differences in accounting, growth, margins, risk, capital structure and one-off earnings distort comparability. Negative earnings make P/E not meaningful in customary sense. Exam trap: Selecting only high-multiple peers introduces confirmation bias."},{"front_en":"Asset-based tradeoffs","back_vi":"Asset values can anchor firms with separable assets/liquidation outcomes, but may neglect brands, network effects, internally developed IP and going-concern synergies. Asset appraisals can be stale. Exam trap: Book assets not same as realizable net assets."}]},{"id":"CFA26-05-08-LOS07","letter":"8.g","title_en":"Non-Callable Perpetual Preferred Stock Value","outcome_en":"calculate value of a plain preferred security with a fixed perpetual dividend","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"Preferred as constant cash stream","body":"Plain noncallable nonconvertible preferred with fixed dividend and no maturity resembles equity perpetuity; value equals annual expected dividend divided by required preferred return.","trap":"Only if payments assumed perpetual and contractual features align."},{"heading":"Dividend dollar amount","body":"If preferred par $100 with 6% stated annual dividend, annual cash D=$6; dividend yield based on market price may differ from stated rate on par.","trap":"6% of par is not necessarily return on purchase price."},{"heading":"Required rate impact","body":"Higher required preferred return lowers present value; lower required return raises value, assuming fixed expected dividend. Credit/deferral risk should affect r or cash flow expectation.","trap":"Preferred dividends may be skipped/deferred subject to terms."},{"heading":"Payment frequency and features","body":"Semiannual/quarterly dividend timing may require corresponding period discounting; callable, convertible, participating, redeemable provisions need additional modeling.","trap":"Do not blindly apply simple D/r to finite-life callable claims."},{"heading":"Preference and price","body":"Seniority to common does not equal senior bond priority; preferred remains exposed to issuer risk and illiquidity. Compare issued price with model value and ask about dividend sustainability.","trap":"Preferred is not risk-free government perpetual debt."}],"formulas":[{"name":"Perpetual fixed preferred valuation","expr":"V_p = D_p / r_p","meaning":"Dividend dollars per year / annual required return.","conditions":"Noncallable nonconvertible fixed-payment perpetual assumption."},{"name":"Preferred stated dividend","expr":"D_p = par value × stated dividend rate","meaning":"Translate stated rate on par into dollars.","conditions":"Actual payment frequency and deferability matter."}],"examples":[{"question_en":"A $100-par perpetual preferred share pays a 7% annual dividend and has an investor required return of 8%. Estimate intrinsic value.","steps_vi":["Annual dividend=$100×0.07=$7.","$7/0.08=$87.50."],"answer":"$87.50","check":"Plain noncallable, nonconvertible perpetual fixed dividends assumed."}],"questions":[{"stem_en":"A perpetual preferred share paying $5 annually with a 10% required return is worth approximately:","options":["$50","$5","$500"],"correct":0,"why_vi":"V=5/0.10=50.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"An increase in the required return on fixed-dividend preferred stock generally:","options":["Increases dividend dollars contractually","Decreases intrinsic value","Has no effect on price"],"correct":1,"why_vi":"D/r inverse to r.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A 6% stated dividend on $100 par preferred typically means annual dividend of:","options":["$0.60","6% of market price regardless of price","$6"],"correct":2,"why_vi":"Par × stated rate sets annual cash amount.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Preferred as constant cash stream","back_vi":"Plain noncallable nonconvertible preferred with fixed dividend and no maturity resembles equity perpetuity; value equals annual expected dividend divided by required preferred return. Exam trap: Only if payments assumed perpetual and contractual features align."},{"front_en":"Dividend dollar amount","back_vi":"If preferred par $100 with 6% stated annual dividend, annual cash D=$6; dividend yield based on market price may differ from stated rate on par. Exam trap: 6% of par is not necessarily return on purchase price."},{"front_en":"Required rate impact","back_vi":"Higher required preferred return lowers present value; lower required return raises value, assuming fixed expected dividend. Credit/deferral risk should affect r or cash flow expectation. Exam trap: Preferred dividends may be skipped/deferred subject to terms."},{"front_en":"Payment frequency and features","back_vi":"Semiannual/quarterly dividend timing may require corresponding period discounting; callable, convertible, participating, redeemable provisions need additional modeling. Exam trap: Do not blindly apply simple D/r to finite-life callable claims."},{"front_en":"Preference and price","back_vi":"Seniority to common does not equal senior bond priority; preferred remains exposed to issuer risk and illiquidity. Compare issued price with model value and ask about dividend sustainability. Exam trap: Preferred is not risk-free government perpetual debt."}]},{"id":"CFA26-05-08-LOS08","letter":"8.h","title_en":"Gordon Growth and Two-Stage Dividend Models","outcome_en":"calculate and interpret constant-growth and two-stage dividend values","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"Gordon constant-growth model","body":"V0 = D1/(r−g), with D1 next-period expected dividend, r equity required return, g perpetual dividend growth. Requires r>g and credible stable growth.","trap":"D0 is NOT D1; grow most recent dividend first."},{"heading":"Sensitivity to spread","body":"When r−g nhỏ, valuation rất nhạy. g phải bền vững dài hạn relative to economic growth; discount rate and growth need same nominal/real terms.","trap":"g≥r makes simple model economically invalid in this setting."},{"heading":"High-growth explicit stage","body":"Two-stage DDM forecast D1...DN at supernormal growth (or individually), then stable growth g_L beyond year N. Terminal value at N = D_(N+1)/(r−g_L).","trap":"Terminal value is at end of N, not time 0."},{"heading":"Discount all payments","body":"V0=Σ[t=1..N] D_t/(1+r)^t + V_N/(1+r)^N. Use consistent r and sensible assumptions about change of payout ratio.","trap":"Don't add D_N twice or fail to discount terminal value."},{"heading":"Interpreting growth","body":"Higher g raises value holding other inputs, but higher growth may need reinvestment/capital and can change payout; adjust forecasts rather than arbitrarily boosting g.","trap":"Fast firm revenue growth does not automatically equal perpetual dividend growth."}],"formulas":[{"name":"Gordon growth","expr":"V0 = D1 / (r_e − g)","meaning":"Constant-growth DDM equity price.","conditions":"Stable g < r_e; D1 = D0(1+g)."},{"name":"Two-stage DDM","expr":"V0 = Σ[t=1..N] D_t/(1+r_e)^t + (D_(N+1)/(r_e−g_L))/(1+r_e)^N","meaning":"Explicit high-growth cash flows plus discounted terminal value.","conditions":"r_e > g_L, correct timing of terminal."},{"name":"Retention growth heuristic","expr":"g ≈ ROE × retention","meaning":"Can help assess long-run dividend growth drivers.","conditions":"Stable capital policy and ROE assumptions."}],"examples":[{"question_en":"A stock just paid a $2 dividend. Dividends will grow 20% for the next year, then 4% perpetually. Required return is 10%. Calculate today’s value using a two-stage DDM.","steps_vi":["D1=2×1.20=$2.40; D2=2.40×1.04=$2.496.","Terminal value at t=1: P1=D2/(0.10−0.04)=41.60.","V0=(D1+P1)/1.10=(2.40+41.60)/1.10."],"answer":"$40.00","check":"One high-growth year, then stable growth starts with D2."}],"questions":[{"stem_en":"A stock has D0=$3, g=4%, and r=10%. Gordon value is:","options":["$50.00","$52.00","$31.20"],"correct":1,"why_vi":"D1=3×1.04=3.12; V=3.12/0.06=52.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"In a two-stage DDM, terminal value at year N should be discounted:","options":["Never, because terminal value is already PV0","By (1+g)^N instead of required return","By (1+r)^N to time zero"],"correct":2,"why_vi":"P_N must be brought to t0.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"The Gordon growth model is not appropriate when the assumed perpetual growth rate is:","options":["Greater than or equal to the required return","Positive but less than required return","Lower than long-run inflation"],"correct":0,"why_vi":"r−g must be positive under standard model.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Gordon constant-growth model","back_vi":"V0 = D1/(r−g), with D1 next-period expected dividend, r equity required return, g perpetual dividend growth. Requires r>g and credible stable growth. Exam trap: D0 is NOT D1; grow most recent dividend first."},{"front_en":"Sensitivity to spread","back_vi":"When r−g nhỏ, valuation rất nhạy. g phải bền vững dài hạn relative to economic growth; discount rate and growth need same nominal/real terms. Exam trap: g≥r makes simple model economically invalid in this setting."},{"front_en":"High-growth explicit stage","back_vi":"Two-stage DDM forecast D1...DN at supernormal growth (or individually), then stable growth g_L beyond year N. Terminal value at N = D_(N+1)/(r−g_L). Exam trap: Terminal value is at end of N, not time 0."},{"front_en":"Discount all payments","back_vi":"V0=Σ[t=1..N] D_t/(1+r)^t + V_N/(1+r)^N. Use consistent r and sensible assumptions about change of payout ratio. Exam trap: Don't add D_N twice or fail to discount terminal value."},{"front_en":"Interpreting growth","back_vi":"Higher g raises value holding other inputs, but higher growth may need reinvestment/capital and can change payout; adjust forecasts rather than arbitrarily boosting g. Exam trap: Fast firm revenue growth does not automatically equal perpetual dividend growth."}]},{"id":"CFA26-05-08-LOS09","letter":"8.i","title_en":"Choosing Constant Growth Versus Multistage DDM","outcome_en":"identify firms appropriate for constant-growth and multistage dividend models","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"Constant-growth candidate","body":"Mature stable company with predictable cash dividends, sustainable payout policy, stable ROE/capital needs và growth below r. Sectors with recurring cash generation often fit better than very young ventures.","trap":"Stable dividend history alone không guarantee future constant growth."},{"heading":"Multistage candidate","body":"Company with temporary high growth or changing payout, competitive transition, regulatory shift or anticipated maturation; forecast stage(s) explicitly then long-run normal growth.","trap":"N-stage terminal must reflect sustainable economics."},{"heading":"Low or no dividends","body":"Rapidly reinvesting business may have earnings/FCFE but no current dividend; strict near-term DDM less informative unless future payouts modeled. FCFE or suitable multiples can supplement.","trap":"No dividend today ≠ no intrinsic value."},{"heading":"Growth, payout, and reinvestment","body":"Growth depends investment rate and incremental returns; firms cannot indefinitely grow payouts faster than economic capacity. Forecast payouts and reinvestment jointly.","trap":"Increasing dividends without cash support creates financing strain."},{"heading":"Stress test appropriateness","body":"Analyze cost of equity, terminal growth, competitive change, business risk and timing until steady state. If assumptions unstable, use ranges or alternative model.","trap":"A two-stage model remains highly sensitive to terminal value."}],"formulas":[{"name":"Stable-growth feasibility","expr":"r_e > g_stable and g_stable supported by long-run earnings/cash capacity","meaning":"Screen for constant-growth DDM.","conditions":"A mathematical denominator alone does not prove economics."},{"name":"Dividend-payout identity","expr":"Dividend payout ratio = dividends to common / earnings to common","meaning":"Links sustainable dividends to earnings.","conditions":"Invalid/unstable interpretation for negative earnings."}],"examples":[{"question_en":"A mature utility pays regular dividends with stable 3% growth, while an early-stage technology company reinvests all cash and has uncertain future payout. Which model is more naturally suited to the utility?","steps_vi":["Utility stable payouts can support constant-growth forecasts.","Technology company may require multistage FCFE or other valuation."],"answer":"Constant-growth DDM for the mature utility","check":"Subject to the utility’s sustainable r>g and business risk."}],"questions":[{"stem_en":"A constant-growth DDM is most suitable for a company with:","options":["No identifiable payout policy and unstable earnings","A dividend rate growing faster than discount rate forever","Stable perpetual dividend growth assumptions"],"correct":2,"why_vi":"Sustainable stable growth required.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A multistage DDM is generally more suitable when:","options":["A temporary high-growth period precedes mature growth","Dividend growth is known constant indefinitely","There is no company equity claim"],"correct":0,"why_vi":"Growth transitions need staged forecast.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"For a non-dividend-paying high-growth company, an analyst may prefer:","options":["Automatically assign zero equity value","FCFE or another appropriate fundamental model","Assume perpetual current dividend of zero with no future change"],"correct":1,"why_vi":"Current payout absence not equal no future benefit.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Constant-growth candidate","back_vi":"Mature stable company with predictable cash dividends, sustainable payout policy, stable ROE/capital needs và growth below r. Sectors with recurring cash generation often fit better than very young ventures. Exam trap: Stable dividend history alone không guarantee future constant growth."},{"front_en":"Multistage candidate","back_vi":"Company with temporary high growth or changing payout, competitive transition, regulatory shift or anticipated maturation; forecast stage(s) explicitly then long-run normal growth. Exam trap: N-stage terminal must reflect sustainable economics."},{"front_en":"Low or no dividends","back_vi":"Rapidly reinvesting business may have earnings/FCFE but no current dividend; strict near-term DDM less informative unless future payouts modeled. FCFE or suitable multiples can supplement. Exam trap: No dividend today ≠ no intrinsic value."},{"front_en":"Growth, payout, and reinvestment","back_vi":"Growth depends investment rate and incremental returns; firms cannot indefinitely grow payouts faster than economic capacity. Forecast payouts and reinvestment jointly. Exam trap: Increasing dividends without cash support creates financing strain."},{"front_en":"Stress test appropriateness","back_vi":"Analyze cost of equity, terminal growth, competitive change, business risk and timing until steady state. If assumptions unstable, use ranges or alternative model. Exam trap: A two-stage model remains highly sensitive to terminal value."}]},{"id":"CFA26-05-08-LOS10","letter":"8.j","title_en":"P/E Rationale and Fundamentals","outcome_en":"explain the rationale for price multiples and relate P/E to fundamentals and comparables","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"P/E as capitalization of earnings","body":"P/E = price/EPS links market equity valuation to accounting earnings, which investors use as proxy for future cash-flow capacity. Choice trailing vs forward EPS and one-off items matters.","trap":"Earnings != distributable dividends."},{"heading":"Fundamental P/E relation","body":"Under Gordon logic V/E1 = (D1/E1)/(r−g) = forward payout ratio/(r−g), if comparable earnings/dividends and assumptions. Higher payout/growth raises ratio; higher r lowers it ceteris paribus.","trap":"Growth may require reinvestment, reducing payout."},{"heading":"Comparables valuation","body":"Use relevant peer P/E median or normalized range adjusted for risk, growth, return on capital, business mix and accounting. Applying market multiple blindly can import peer mispricing.","trap":"Same industry label insufficient peer comparability."},{"heading":"Trailing versus forward P/E","body":"Trailing earnings based last 12 months, forward earnings on expected next period; cyclicality/negative earnings alter meaning. Ensure price and earnings time basis stated.","trap":"Never compare trailing target with forward peers without adjusting."},{"heading":"Justified versus observed","body":"Justified P/E derives from fundamentals; observed reflects market expectations and sentiment. A higher P/E is not automatically overvaluation if justified growth/payout/risk differ.","trap":"Cheap-looking P/E may signal structurally weak earnings."}],"formulas":[{"name":"P/E multiple","expr":"P/E = common stock price / EPS attributable to common","meaning":"Price relative to earnings per share.","conditions":"EPS time basis, dilution and one-offs matter."},{"name":"Justified forward P/E (stable growth)","expr":"V0/E1 = payout ratio_forward / (r_e − g)","meaning":"Connect P/E to dividend payout, risk and growth.","conditions":"D1 = payout×E1; r_e>g; stable growth."},{"name":"Comparable target","expr":"Price_target = justified peer P/E × normalized target EPS","meaning":"Relative-value estimate.","conditions":"Adjust peer growth, risk, earnings quality."}],"examples":[{"question_en":"A stock has next-year expected EPS of $4, expected dividend payout of 50%, r=10% and stable growth g=5%. Calculate justified forward P/E.","steps_vi":["Justified forward P/E=0.50/(0.10−0.05).","=10.0×; implied value=10×$4=$40."],"answer":"10.0× forward P/E; $40 implied value","check":"Assumes sustainable Gordon payout and stable dividend growth."}],"questions":[{"stem_en":"Under a constant-growth model, higher required equity return with other inputs fixed tends to:","options":["Lower justified P/E","Raise justified P/E","Leave justified P/E always unchanged"],"correct":0,"why_vi":"P/E=payout/(r−g).","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A stock at $80 with expected EPS of $5 has a forward P/E of:","options":["5×","16×","400×"],"correct":1,"why_vi":"80/5=16.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"When comparing firms using P/E, the analyst should pay particular attention to:","options":["Only the ticker symbol length","Whether the exchange uses green price displays","Growth, risk, and earnings definitions"],"correct":2,"why_vi":"Comparable normalized EPS essential.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"P/E as capitalization of earnings","back_vi":"P/E = price/EPS links market equity valuation to accounting earnings, which investors use as proxy for future cash-flow capacity. Choice trailing vs forward EPS and one-off items matters. Exam trap: Earnings != distributable dividends."},{"front_en":"Fundamental P/E relation","back_vi":"Under Gordon logic V/E1 = (D1/E1)/(r−g) = forward payout ratio/(r−g), if comparable earnings/dividends and assumptions. Higher payout/growth raises ratio; higher r lowers it ceteris paribus. Exam trap: Growth may require reinvestment, reducing payout."},{"front_en":"Comparables valuation","back_vi":"Use relevant peer P/E median or normalized range adjusted for risk, growth, return on capital, business mix and accounting. Applying market multiple blindly can import peer mispricing. Exam trap: Same industry label insufficient peer comparability."},{"front_en":"Trailing versus forward P/E","back_vi":"Trailing earnings based last 12 months, forward earnings on expected next period; cyclicality/negative earnings alter meaning. Ensure price and earnings time basis stated. Exam trap: Never compare trailing target with forward peers without adjusting."},{"front_en":"Justified versus observed","back_vi":"Justified P/E derives from fundamentals; observed reflects market expectations and sentiment. A higher P/E is not automatically overvaluation if justified growth/payout/risk differ. Exam trap: Cheap-looking P/E may signal structurally weak earnings."}]},{"id":"CFA26-05-08-LOS11","letter":"8.k","title_en":"Equity Price Multiples","outcome_en":"calculate and interpret P/E, price to cash flow, P/S, and P/B multiples","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"Price to earnings","body":"P/E = P/EPS, using trailing or forward earnings; high may reflect growth/risk differences, negative EPS makes ratio nonmeaningful for ordinary comparison. Check normalized earnings and dilution.","trap":"Small positive EPS can create absurdly high P/E."},{"heading":"Price to cash flow","body":"P/CF uses a specified cash-flow measure per share, frequently CFO or another estimate of operating CF; accounting noncash charges distort earnings less than cash flow but working capital can swing CFO.","trap":"P/CF definition must be stated, not assumed FCF."},{"heading":"Price to sales","body":"P/S = price/sales per share or market equity/revenue, useful for low earnings firms but ignores margins, capital intensity and debt obligations.","trap":"Two equal P/S firms can have vastly different profitability."},{"heading":"Price to book","body":"P/B = price/BVPS, especially discussed with financials/asset-heavy firms; book equity can diverge from economic value and be negative.","trap":"Negative BVPS invalidates ordinary cheap/expensive interpretation."},{"heading":"Peer interpretation","body":"Use consistent share counts, currencies, accounting/periods, growth and financial risk; combine multiples with intrinsic economics rather than ranking based on one ratio.","trap":"Multiples are relative, not guarantee of value."}],"formulas":[{"name":"P/E and P/CF","expr":"P/E = P/EPS; P/CF = P/(operating CF per share)","meaning":"Common equity price multiples.","conditions":"Label cash-flow definition and period."},{"name":"P/S","expr":"P/S = market capitalization / sales = P/(sales/share)","meaning":"Valuation per sales dollar.","conditions":"Sales positive but profit margins may be negative."},{"name":"P/B","expr":"P/B = market capitalization / book common equity = P/BVPS","meaning":"Valuation per accounting equity.","conditions":"Use relevant common-equity book value and shares."}],"examples":[{"question_en":"A company has price $30, EPS $2, operating cash flow per share $3, sales per share $15, and BVPS $10. Compute four common multiples.","steps_vi":["P/E=30/2=15×; P/operating CF=30/3=10×.","P/S=30/15=2×; P/B=30/10=3×."],"answer":"P/E 15×; P/operating CF 10×; P/S 2×; P/B 3×","check":"Cash flow denominator explicitly defined as operating cash flow."}],"questions":[{"stem_en":"A firm with $60 stock price and $4 EPS has a P/E ratio of:","options":["0.067×","15×","240×"],"correct":1,"why_vi":"60/4=15.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A company with $12 billion market capitalization and $4 billion revenue has P/S of:","options":["0.33×","48×","3.0×"],"correct":2,"why_vi":"12/4=3.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"Which price multiple is most distorted by an extremely small positive EPS?","options":["P/E","P/S with stable sales","Price to operating cash flow with stable CFO"],"correct":0,"why_vi":"Denominator near zero inflates P/E.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Price to earnings","back_vi":"P/E = P/EPS, using trailing or forward earnings; high may reflect growth/risk differences, negative EPS makes ratio nonmeaningful for ordinary comparison. Check normalized earnings and dilution. Exam trap: Small positive EPS can create absurdly high P/E."},{"front_en":"Price to cash flow","back_vi":"P/CF uses a specified cash-flow measure per share, frequently CFO or another estimate of operating CF; accounting noncash charges distort earnings less than cash flow but working capital can swing CFO. Exam trap: P/CF definition must be stated, not assumed FCF."},{"front_en":"Price to sales","back_vi":"P/S = price/sales per share or market equity/revenue, useful for low earnings firms but ignores margins, capital intensity and debt obligations. Exam trap: Two equal P/S firms can have vastly different profitability."},{"front_en":"Price to book","back_vi":"P/B = price/BVPS, especially discussed with financials/asset-heavy firms; book equity can diverge from economic value and be negative. Exam trap: Negative BVPS invalidates ordinary cheap/expensive interpretation."},{"front_en":"Peer interpretation","back_vi":"Use consistent share counts, currencies, accounting/periods, growth and financial risk; combine multiples with intrinsic economics rather than ranking based on one ratio. Exam trap: Multiples are relative, not guarantee of value."}]},{"id":"CFA26-05-08-LOS12","letter":"8.l","title_en":"Enterprise Value Multiples","outcome_en":"describe enterprise-value multiples and their application to common equity valuation","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"Enterprise versus equity value","body":"Enterprise value estimates market value of operating business to capital providers; typical bridge EV=market common equity + debt + preferred + noncontrolling interest−cash, subject to treatment of investments.","trap":"EV and market cap are not interchangeable."},{"heading":"Matching denominator","body":"EV/EBITDA hoặc EV/revenue pairs value to operating metrics available before capital structure claims; equity multiples P/E use after-interest earnings. Avoid mismatched numerator and denominator.","trap":"EV/net income is usually inconsistent."},{"heading":"When EV/EBITDA helps","body":"Comparing similar businesses with different debt levels and depreciation schedules; may require adjustments for lease accounting and nonrecurring expenses. EBITDA omits capex/taxes/working capital.","trap":"EV/EBITDA low does not automatically mean cheap for capital-intensive business."},{"heading":"Implied equity bridge","body":"Peer EV multiple × target EBITDA = implied EV. Subtract net debt, preferred, minorities and adjustments to find common equity; divide by diluted common shares.","trap":"Forgetting debt will overvalue common stock."},{"heading":"Limitations and consistency","body":"Cash may be restricted/nonoperating, financial firms have different debt economics, negative EBITDA problematic and lease adjustments affect comparability. Compare adjusted enterprise definitions consistently.","trap":"Avoid blanket EV/EBITDA on banks without special treatment."}],"formulas":[{"name":"EV bridge","expr":"EV ≈ equity market cap + debt + preferred + noncontrolling interest − cash and cash equivalents","meaning":"Stylized enterprise valuation.","conditions":"Include other nonoperating assets/claims as appropriate."},{"name":"Enterprise multiple","expr":"EV/EBITDA = enterprise value / EBITDA","meaning":"Cross-capital-structure operating comparison.","conditions":"Similar accounting and leverage/leases treatment."},{"name":"Implied common value","expr":"Equity value = enterprise value − debt − preferred − noncontrolling interests + cash + adjustments","meaning":"Bridge from business value to residual common claim.","conditions":"Match enterprise definition and net debt."}],"examples":[{"question_en":"A firm has EBITDA of $80 million. Comparable firms trade at 7× EV/EBITDA. The target has $130m debt and $30m cash, no preferred or minorities, and 20m shares. Find implied share price.","steps_vi":["Implied EV=80×7=$560m.","Net debt=130−30=$100m, so implied common equity=560−100=$460m.","Price per share=460/20=$23."],"answer":"$23.00 per share","check":"Assumes all debt/cash and EBITDA definitions comparable."}],"questions":[{"stem_en":"The most internally consistent ratio below is:","options":["EV/EPS","Market capitalization/interest expense","EV/EBITDA"],"correct":2,"why_vi":"EV is to all capital providers, EBITDA pre-financing operating measure.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A company has market equity $100m, debt $50m, cash $20m and no other claims. EV is approximately:","options":["$130 million","$70 million","$170 million"],"correct":0,"why_vi":"EV=100+50−20=130.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"If EV is $500m and net debt is $100m with no other adjustments, implied common equity is:","options":["$600 million","$400 million","$100 million"],"correct":1,"why_vi":"Equity=EV−net debt=400.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Enterprise versus equity value","back_vi":"Enterprise value estimates market value of operating business to capital providers; typical bridge EV=market common equity + debt + preferred + noncontrolling interest−cash, subject to treatment of investments. Exam trap: EV and market cap are not interchangeable."},{"front_en":"Matching denominator","back_vi":"EV/EBITDA hoặc EV/revenue pairs value to operating metrics available before capital structure claims; equity multiples P/E use after-interest earnings. Avoid mismatched numerator and denominator. Exam trap: EV/net income is usually inconsistent."},{"front_en":"When EV/EBITDA helps","back_vi":"Comparing similar businesses with different debt levels and depreciation schedules; may require adjustments for lease accounting and nonrecurring expenses. EBITDA omits capex/taxes/working capital. Exam trap: EV/EBITDA low does not automatically mean cheap for capital-intensive business."},{"front_en":"Implied equity bridge","back_vi":"Peer EV multiple × target EBITDA = implied EV. Subtract net debt, preferred, minorities and adjustments to find common equity; divide by diluted common shares. Exam trap: Forgetting debt will overvalue common stock."},{"front_en":"Limitations and consistency","back_vi":"Cash may be restricted/nonoperating, financial firms have different debt economics, negative EBITDA problematic and lease adjustments affect comparability. Compare adjusted enterprise definitions consistently. Exam trap: Avoid blanket EV/EBITDA on banks without special treatment."}]},{"id":"CFA26-05-08-LOS13","letter":"8.m","title_en":"Asset-Based Equity Valuation","outcome_en":"describe asset-based approaches and when they can estimate common equity value","overview_vi":"Bài học song ngữ bám sát phạm vi kỹ năng của Equity Investments LM8 trong CFAI Level I 2026. Giải thích là bản biên soạn độc lập; điều kiện áp dụng, bẫy nhận thức và giả định được trình bày riêng. Chưa được chứng nhận kiểm toán học thuật từng dòng.","source":[{"id":"CFA Institute Level I Curriculum 2026, Equity Investments Volume 5, LM8 — Equity Valuation: Concepts and Basic Tools","pages":"official outcomes at physical PDF p345; teaching chapter physical pp345–398"}],"sections":[{"heading":"Net asset value","body":"Equity value approximates market/appraised value of identifiable assets minus market/appraised liabilities and senior claims. Useful for asset-holding firms and potential liquidation analyses.","trap":"Book balance sheet figures often need revaluation."},{"heading":"Replacement and liquidation concepts","body":"Replacement value estimates cost to reproduce productive assets; liquidation value estimates net realization after sale costs, taxes and claims. Going-concern value may be much higher.","trap":"Fire-sale pricing differs from orderly asset appraisal."},{"heading":"Hidden or hard-to-measure assets","body":"Customer relationships, patents, R&D, internally developed brands and network effects may not appear as separable assets under accounting rules. Asset-based model can underestimate high-quality going concerns.","trap":"Intangible valuation itself highly uncertain."},{"heading":"Liabilities and contingencies","body":"Pension obligations, leases, litigation, environmental cleanup, taxes, minority interests and off-balance-sheet commitments can reduce residual value. Assess seniority and timing.","trap":"Ignoring contingent claims overstates common equity."},{"heading":"Appropriate use and cross-checks","body":"Asset-based methods particularly relevant to real estate companies, investment holding firms, distressed or liquidation cases; combine with earnings/cash-flow models to assess franchise value.","trap":"NAV discount may reflect liquidity, taxes and control rather than free arbitrage."}],"formulas":[{"name":"Appraised net asset value","expr":"NAV_equity = market-valued assets − market-valued liabilities and senior claims","meaning":"Residual common economic claim.","conditions":"Include contingent liabilities and asset disposal costs."},{"name":"NAV per share","expr":"NAVPS = appraised net equity assets / common shares outstanding","meaning":"Per-share asset-based estimate.","conditions":"Share count/dilution and valuation date consistent."}],"examples":[{"question_en":"A holding company owns assets appraised at $900 million, has $350 million debt and $50 million expected net liquidation/tax costs. With 25 million shares and no other claims, estimate NAV per share.","steps_vi":["Net equity NAV=900−350−50=$500m.","NAV per share=500/25=$20."],"answer":"$20 per share","check":"Assumes appraisals realizable and no other liabilities or claims."}],"questions":[{"stem_en":"Asset-based valuation primarily estimates common equity as:","options":["Appraised assets less economic liabilities and senior claims","Market price times expected EPS","Annual dividend divided by EPS"],"correct":0,"why_vi":"Asset-based residual economic value.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"A holding company has $600m assets, $200m liabilities and 20m common shares. Ignoring other costs, NAVPS is:","options":["$30","$20","$10"],"correct":1,"why_vi":"(600−200)/20=20.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."},{"stem_en":"An important limitation of a simple book-NAV model for a software company is:","options":["Book cash balances always equal zero","Equity cannot have asset-based value","Unrecognized internally generated intangible value"],"correct":2,"why_vi":"Software/intangibles may not be on book at market value.","trap_vi":"Phân biệt chính xác giả định, phạm vi thông tin, mẫu số và điều kiện của từng khái niệm."}],"cards":[{"front_en":"Net asset value","back_vi":"Equity value approximates market/appraised value of identifiable assets minus market/appraised liabilities and senior claims. Useful for asset-holding firms and potential liquidation analyses. Exam trap: Book balance sheet figures often need revaluation."},{"front_en":"Replacement and liquidation concepts","back_vi":"Replacement value estimates cost to reproduce productive assets; liquidation value estimates net realization after sale costs, taxes and claims. Going-concern value may be much higher. Exam trap: Fire-sale pricing differs from orderly asset appraisal."},{"front_en":"Hidden or hard-to-measure assets","back_vi":"Customer relationships, patents, R&D, internally developed brands and network effects may not appear as separable assets under accounting rules. Asset-based model can underestimate high-quality going concerns. Exam trap: Intangible valuation itself highly uncertain."},{"front_en":"Liabilities and contingencies","back_vi":"Pension obligations, leases, litigation, environmental cleanup, taxes, minority interests and off-balance-sheet commitments can reduce residual value. Assess seniority and timing. Exam trap: Ignoring contingent claims overstates common equity."},{"front_en":"Appropriate use and cross-checks","back_vi":"Asset-based methods particularly relevant to real estate companies, investment holding firms, distressed or liquidation cases; combine with earnings/cash-flow models to assess franchise value. Exam trap: NAV discount may reflect liquidity, taxes and control rather than free arbitrage."}]}]}];
